CORE = json.loads('{"pokearb_core/__init__.py": "\\"\\"\\"PokeArb core engines. No I/O lives in this package.\\n\\nEvery module here takes plain value objects and returns plain value objects.\\nThat constraint is what makes the backtester trustworthy: replaying history\\ncannot accidentally read present-day state, because there is nothing to read.\\n\\"\\"\\"\\n\\nfrom .types import (  # noqa: F401\\n    UNKNOWN,\\n    CardVariant,\\n    ConditionDistribution,\\n    Currency,\\n    DataQuality,\\n    Edition,\\n    EU_CONDITION_LADDER,\\n    EuCondition,\\n    EvidenceRef,\\n    FairValue,\\n    FxRate,\\n    Grader,\\n    Language,\\n    Listing,\\n    Money,\\n    PopulationSnapshot,\\n    Printing,\\n    Sale,\\n    Scenario,\\n    SupplySnapshot,\\n    Unknown,\\n)\\n\\n__version__ = \\"0.1.0\\"\\n", "pokearb_core/adapters/__init__.py": "\\"\\"\\"PokeArb core subpackage.\\"\\"\\"\\n", "pokearb_core/adapters/base.py": "\\"\\"\\"Adapter framework and the compliance gate.\\n\\nEvery marketplace gets its own adapter converting source payloads into the\\nshared internal schema. Before any adapter can issue a request, its\\n``SourcePolicy`` must be filled in and marked verified.\\n\\nThe gate is not bureaucracy. The default is ``enabled=False`` with\\n``verification_status=UNVERIFIED``, and the collector refuses to run an\\nunverified source. That forces the robots and terms check to happen *before*\\nthe first request rather than after a block, which is the difference between a\\ncompliant system and one that finds out the hard way.\\n\\nCardmarket is the concrete case. Its documentation forbids Dedicated App users\\nfrom continuously polling public marketplace resources on consecutive days, so\\n``CardmarketAdapter`` additionally refuses continuous public polling when the\\ncredential type is Dedicated, no matter what the policy row says.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport abc\\nimport hashlib\\nimport json\\nfrom dataclasses import dataclass, field\\nfrom datetime import date, datetime, timezone\\nfrom decimal import Decimal\\nfrom enum import Enum\\nfrom typing import Any, Iterable, Mapping, Optional, Sequence\\n\\nfrom ..types import FxRate, Listing, PopulationSnapshot, Sale\\n\\n__all__ = [\\n    \\"VerificationStatus\\",\\n    \\"SourcePolicy\\",\\n    \\"RawRecord\\",\\n    \\"SourceDisabledError\\",\\n    \\"PolicyViolationError\\",\\n    \\"Adapter\\",\\n    \\"CatalogueSource\\",\\n    \\"SalesSource\\",\\n    \\"ListingSource\\",\\n    \\"PopulationSource\\",\\n    \\"FxSource\\",\\n]\\n\\n\\nclass VerificationStatus(str, Enum):\\n    UNVERIFIED = \\"unverified\\"\\n    VERIFIED_API = \\"verified_api\\"\\n    VERIFIED_PERMITTED = \\"verified_permitted\\"\\n    BLOCKED = \\"blocked\\"\\n\\n\\nclass SourceDisabledError(RuntimeError):\\n    \\"\\"\\"The source has not been verified and enabled.\\"\\"\\"\\n\\n\\nclass PolicyViolationError(RuntimeError):\\n    \\"\\"\\"The requested access pattern is forbidden by the source\'s own terms.\\"\\"\\"\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass SourcePolicy:\\n    \\"\\"\\"Compliance record for one source. No adapter runs without one.\\"\\"\\"\\n\\n    source_id: str\\n    display_name: str\\n    base_url: str\\n    verification_status: VerificationStatus = VerificationStatus.UNVERIFIED\\n    enabled: bool = False\\n    has_official_api: Optional[bool] = None\\n    api_docs_url: Optional[str] = None\\n    robots_checked_on: Optional[date] = None\\n    robots_allows_paths: Optional[bool] = None\\n    terms_reviewed_on: Optional[date] = None\\n    terms_url: Optional[str] = None\\n    #: Hard request budget. The scheduler treats this as a ceiling, not a target.\\n    max_requests_per_minute: int = 6\\n    min_seconds_between_requests: Decimal = Decimal(\\"10\\")\\n    #: Access patterns this source explicitly forbids, by name.\\n    forbidden_patterns: tuple[str, ...] = ()\\n    credentials_required: tuple[str, ...] = ()\\n    notes: Optional[str] = None\\n\\n    def assert_runnable(self) -> None:\\n        if not self.enabled:\\n            raise SourceDisabledError(\\n                f\\"Source \'{self.source_id}\' is disabled. Enabling it requires \\"\\n                \\"filling in robots_checked_on, terms_reviewed_on and setting \\"\\n                \\"verification_status away from UNVERIFIED.\\"\\n            )\\n        if self.verification_status in (\\n            VerificationStatus.UNVERIFIED,\\n            VerificationStatus.BLOCKED,\\n        ):\\n            raise SourceDisabledError(\\n                f\\"Source \'{self.source_id}\' has verification_status=\\"\\n                f\\"{self.verification_status.value}; refusing to issue requests.\\"\\n            )\\n        if self.verification_status is VerificationStatus.VERIFIED_PERMITTED:\\n            if self.robots_checked_on is None or self.terms_reviewed_on is None:\\n                raise SourceDisabledError(\\n                    f\\"Source \'{self.source_id}\' claims permitted access but is \\"\\n                    \\"missing a robots or terms review date.\\"\\n                )\\n            if self.robots_allows_paths is False:\\n                raise PolicyViolationError(\\n                    f\\"robots rules for \'{self.source_id}\' disallow the configured paths.\\"\\n                )\\n\\n    def assert_pattern_allowed(self, pattern: str) -> None:\\n        if pattern in self.forbidden_patterns:\\n            raise PolicyViolationError(\\n                f\\"Access pattern \'{pattern}\' is forbidden by the terms of \\"\\n                f\\"\'{self.source_id}\'. See {self.terms_url or self.api_docs_url}.\\"\\n            )\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass RawRecord:\\n    \\"\\"\\"Verbatim source payload, stored before any parsing.\\n\\n    Keeping the raw payload is what lets improved matching logic be replayed\\n    over years of history without refetching anything, which the brief asks for\\n    explicitly.\\n    \\"\\"\\"\\n\\n    source_id: str\\n    fetched_at: datetime\\n    request_url: str\\n    payload: Any\\n    content_hash: str = \\"\\"\\n    http_status: Optional[int] = None\\n\\n    @staticmethod\\n    def hash_payload(payload: Any) -> str:\\n        blob = json.dumps(payload, sort_keys=True, ensure_ascii=False, default=str)\\n        return hashlib.sha256(blob.encode(\\"utf-8\\")).hexdigest()\\n\\n    def with_hash(self) -> \\"RawRecord\\":\\n        return RawRecord(\\n            self.source_id, self.fetched_at, self.request_url, self.payload,\\n            self.hash_payload(self.payload), self.http_status,\\n        )\\n\\n\\nclass Adapter(abc.ABC):\\n    \\"\\"\\"Base adapter. Subclasses convert payloads into the internal schema.\\"\\"\\"\\n\\n    def __init__(self, policy: SourcePolicy) -> None:\\n        self.policy = policy\\n\\n    @property\\n    def source_id(self) -> str:\\n        return self.policy.source_id\\n\\n    def _guard(self, pattern: str = \\"default\\") -> None:\\n        self.policy.assert_runnable()\\n        self.policy.assert_pattern_allowed(pattern)\\n\\n    @abc.abstractmethod\\n    def capabilities(self) -> Mapping[str, bool]:\\n        \\"\\"\\"What this adapter can actually supply, given current access.\\"\\"\\"\\n\\n\\nclass CatalogueSource(Adapter):\\n    @abc.abstractmethod\\n    def fetch_sets(self) -> Sequence[RawRecord]: ...\\n\\n    @abc.abstractmethod\\n    def fetch_cards(self, set_code: str) -> Sequence[RawRecord]: ...\\n\\n\\nclass SalesSource(Adapter):\\n    @abc.abstractmethod\\n    def fetch_sales(self, query: str, since: datetime) -> Sequence[Sale]: ...\\n\\n\\nclass ListingSource(Adapter):\\n    @abc.abstractmethod\\n    def fetch_listings(self, query: str) -> Sequence[Listing]: ...\\n\\n\\nclass PopulationSource(Adapter):\\n    @abc.abstractmethod\\n    def fetch_population(self, reference: str) -> Optional[PopulationSnapshot]: ...\\n\\n\\nclass FxSource(Adapter):\\n    @abc.abstractmethod\\n    def fetch_rates(self, on: Optional[date] = None) -> Sequence[FxRate]: ...\\n", "pokearb_core/adapters/gated.py": "\\"\\"\\"Adapters for sources whose access is constrained.\\n\\nEach one ships with a complete interface, a schema, tests and mocks, and a\\npolicy record that records *why* it is off. The brief asked for exactly this:\\nimplement the integration point even when the credentials are unavailable, and\\ndocument what is missing.\\n\\nThe constraints below were each verified against the source\'s own\\ndocumentation while writing the Phase 1 document. The URLs are in\\n``api_docs_url`` on every policy, so the reason a source is off is always one\\nfield lookup away rather than tribal knowledge.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime\\nfrom decimal import Decimal\\nfrom typing import Mapping, Optional, Sequence\\n\\nfrom ..types import Listing, PopulationSnapshot, Sale\\nfrom .base import (\\n    Adapter,\\n    ListingSource,\\n    PolicyViolationError,\\n    PopulationSource,\\n    SalesSource,\\n    SourcePolicy,\\n    VerificationStatus,\\n)\\n\\n__all__ = [\\n    \\"PSA_POLICY\\",\\n    \\"EBAY_SOLD_POLICY\\",\\n    \\"EBAY_BROWSE_POLICY\\",\\n    \\"CARDMARKET_POLICY\\",\\n    \\"PRICECHARTING_POLICY\\",\\n    \\"JAPANESE_SOURCE_TEMPLATE\\",\\n    \\"PsaCertAdapter\\",\\n    \\"EbaySoldAdapter\\",\\n    \\"CardmarketAdapter\\",\\n    \\"PriceChartingAdapter\\",\\n    \\"PRICECHARTING_GRADE_MAP\\",\\n]\\n\\n\\nPSA_POLICY = SourcePolicy(\\n    source_id=\\"psa\\",\\n    display_name=\\"PSA Public API\\",\\n    base_url=\\"https://api.psacard.com/publicapi/\\",\\n    verification_status=VerificationStatus.VERIFIED_API,\\n    enabled=False,\\n    has_official_api=True,\\n    api_docs_url=\\"https://www.psacard.com/publicapi/documentation\\",\\n    credentials_required=(\\"PSA_API_TOKEN\\",),\\n    max_requests_per_minute=10,\\n    forbidden_patterns=(\\"population_report\\",),\\n    notes=(\\n        \\"The PSA Public API documentation states the only available method set is \\"\\n        \\"cert verification by cert number. Population report data is NOT exposed. \\"\\n        \\"Population fields therefore remain unknown until a licensed population \\"\\n        \\"feed is connected. No population figure is ever estimated.\\"\\n    ),\\n)\\n\\nEBAY_SOLD_POLICY = SourcePolicy(\\n    source_id=\\"ebay_sold\\",\\n    display_name=\\"eBay Marketplace Insights API (sold items)\\",\\n    base_url=\\"https://api.ebay.com/buy/marketplace_insights/v1_beta\\",\\n    verification_status=VerificationStatus.UNVERIFIED,\\n    enabled=False,\\n    has_official_api=True,\\n    api_docs_url=\\"https://developer.ebay.com/api-docs/buy/marketplace-insights/static/overview.html\\",\\n    credentials_required=(\\"EBAY_CLIENT_ID\\", \\"EBAY_CLIENT_SECRET\\"),\\n    notes=(\\n        \\"Limited Release API available only to select developers approved by \\"\\n        \\"business units. Sales history range is capped at 90 days. Categories \\"\\n        \\"must additionally be whitelisted per partner. Adapter is complete and \\"\\n        \\"inactive pending access.\\"\\n    ),\\n)\\n\\nEBAY_BROWSE_POLICY = SourcePolicy(\\n    source_id=\\"ebay_browse\\",\\n    display_name=\\"eBay Browse API (active listings)\\",\\n    base_url=\\"https://api.ebay.com/buy/browse/v1\\",\\n    verification_status=VerificationStatus.UNVERIFIED,\\n    enabled=False,\\n    has_official_api=True,\\n    api_docs_url=\\"https://developer.ebay.com/api-docs/buy/browse/static/overview.html\\",\\n    credentials_required=(\\"EBAY_CLIENT_ID\\", \\"EBAY_CLIENT_SECRET\\"),\\n    forbidden_patterns=(\\"fair_value_input\\",),\\n    notes=(\\n        \\"Active listings only. Wired to supply and liquidity signals. The \\"\\n        \\"forbidden pattern \'fair_value_input\' is enforced in code so listings \\"\\n        \\"can never reach the fair value engine.\\"\\n    ),\\n)\\n\\nCARDMARKET_POLICY = SourcePolicy(\\n    source_id=\\"cardmarket\\",\\n    display_name=\\"Cardmarket RESTful API\\",\\n    base_url=\\"https://api.cardmarket.com/ws/v2.0\\",\\n    verification_status=VerificationStatus.UNVERIFIED,\\n    enabled=False,\\n    has_official_api=True,\\n    api_docs_url=\\"https://api.cardmarket.com/ws/documentation/API:Auth_Overview\\",\\n    credentials_required=(\\n        \\"CARDMARKET_APP_TOKEN\\", \\"CARDMARKET_APP_SECRET\\",\\n        \\"CARDMARKET_ACCESS_TOKEN\\", \\"CARDMARKET_ACCESS_SECRET\\",\\n    ),\\n    forbidden_patterns=(\\"continuous_public_marketplace_polling\\",),\\n    notes=(\\n        \\"Cardmarket documentation states API access is restricted to \\"\\n        \\"professional sellers subject to manual approval, and explicitly \\"\\n        \\"disallows Dedicated App users from constantly requesting only the \\"\\n        \\"public Marketplace resources on consecutive days. A continuously \\"\\n        \\"scanning Europe Steal Finder is therefore NOT implementable against \\"\\n        \\"Cardmarket on a Dedicated credential. See docs/01-data-sources.md.\\"\\n    ),\\n)\\n\\nPRICECHARTING_POLICY = SourcePolicy(\\n    source_id=\\"pricecharting\\",\\n    display_name=\\"PriceCharting Prices API\\",\\n    base_url=\\"https://www.pricecharting.com/api\\",\\n    verification_status=VerificationStatus.UNVERIFIED,\\n    enabled=False,\\n    has_official_api=True,\\n    api_docs_url=\\"https://www.pricecharting.com/api-documentation\\",\\n    credentials_required=(\\"PRICECHARTING_TOKEN\\",),\\n    max_requests_per_minute=60,\\n    min_seconds_between_requests=Decimal(\\"1\\"),\\n    forbidden_patterns=(\\"sales_history\\", \\"fair_value_input\\"),\\n    notes=(\\n        \\"Documentation states a paid subscription is required, the API is \\"\\n        \\"limited to one call per second, and that only current values are \\"\\n        \\"supported: historic prices and historic sales are not. Usable as a \\"\\n        \\"current-level cross-check, never as a sales-history source.\\"\\n    ),\\n)\\n\\n#: Template for Japanese marketplaces. Every one of Card Rush, Yuyu-tei,\\n#: Hareruya, Dragon Star, Mandarake, Mercari JP, Yahoo Auctions JP, Rakuten,\\n#: Surugaya, Magi and Clove gets a copy of this with its own base URL, and none\\n#: of them run until someone fills in the robots and terms fields. That check\\n#: has not been done, so none of them are enabled.\\nJAPANESE_SOURCE_TEMPLATE = SourcePolicy(\\n    source_id=\\"jp_template\\",\\n    display_name=\\"Japanese marketplace (template)\\",\\n    base_url=\\"\\",\\n    verification_status=VerificationStatus.UNVERIFIED,\\n    enabled=False,\\n    has_official_api=None,\\n    max_requests_per_minute=4,\\n    min_seconds_between_requests=Decimal(\\"15\\"),\\n    notes=(\\n        \\"No public API or scraping permission was verified for this source. \\"\\n        \\"Fill in robots_checked_on, robots_allows_paths, terms_reviewed_on and \\"\\n        \\"terms_url, then set verification_status, before enabling. The Mobile \\"\\n        \\"Quick Check flow does not depend on this: the Japanese price is typed \\"\\n        \\"in from the shelf tag.\\"\\n    ),\\n)\\n\\n\\n#: PriceCharting\'s card grade mapping, from its own documentation. Encoded here\\n#: so nothing downstream ever mistakes ``new-price`` for a sealed product, which\\n#: is what the column name suggests and is not what it means for cards.\\nPRICECHARTING_GRADE_MAP: Mapping[str, str] = {\\n    \\"loose-price\\": \\"ungraded\\",\\n    \\"cib-price\\": \\"grade_7_or_7.5\\",\\n    \\"new-price\\": \\"grade_8_or_8.5\\",\\n    \\"graded-price\\": \\"grade_9\\",\\n    \\"box-only-price\\": \\"grade_9.5\\",\\n    \\"manual-only-price\\": \\"psa_10\\",\\n    \\"bgs-10-price\\": \\"bgs_10\\",\\n    \\"condition-17-price\\": \\"cgc_10\\",\\n    \\"condition-18-price\\": \\"sgc_10\\",\\n    \\"condition-19-price\\": \\"cgc_10_pristine\\",\\n    \\"condition-20-price\\": \\"bgs_10_black\\",\\n    \\"condition-21-price\\": \\"tag_10\\",\\n    \\"condition-22-price\\": \\"ace_10\\",\\n}\\n\\n\\nclass PsaCertAdapter(PopulationSource):\\n    \\"\\"\\"Cert verification by cert number. Population is not available.\\"\\"\\"\\n\\n    def __init__(self, policy: SourcePolicy = PSA_POLICY, token: Optional[str] = None) -> None:\\n        super().__init__(policy)\\n        self._token = token\\n\\n    def capabilities(self) -> Mapping[str, bool]:\\n        return {\\n            \\"cert_lookup\\": True,           # offered by the API, not by us\\n            \\"population_total\\": False,\\n            \\"population_ladder\\": False,\\n            \\"population_history\\": False,\\n            \\"parser_implemented\\": False,\\n            \\"verified_live_access\\": False,\\n        }\\n\\n    def fetch_population(self, reference: str) -> Optional[PopulationSnapshot]:\\n        \\"\\"\\"Always raises. Population is outside the documented API surface.\\n\\n        Returning ``None`` would be worse than raising: a ``None`` gets quietly\\n        rendered as \\"unknown\\" and the operator never learns that the whole\\n        population feature is unavailable rather than merely missing for this\\n        card.\\n        \\"\\"\\"\\n        raise PolicyViolationError(\\n            \\"PSA population data is not exposed by the PSA Public API, whose \\"\\n            \\"documented method set is cert verification by cert number only. \\"\\n            \\"See https://www.psacard.com/publicapi/documentation. Connect a \\"\\n            \\"licensed population feed, or leave population unknown.\\"\\n        )\\n\\n    def fetch_cert(self, cert_number: str) -> Mapping[str, object]:\\n        \\"\\"\\"Not implemented. No credentials, so no observed response.\\n\\n        The documented endpoint is ``GET /cert/GetByCertNumber/{cert}`` with a\\n        bearer token, per https://www.psacard.com/publicapi/documentation. A\\n        parser written against documentation alone, and tested against fixtures\\n        written from that same documentation, proves only that the two agree\\n        with each other. It is written when a real response exists.\\n        \\"\\"\\"\\n        self._guard(\\"cert_lookup\\")\\n        if not self._token:\\n            raise RuntimeError(\\"PSA_API_TOKEN is not configured.\\")\\n        raise NotImplementedError(\\n            \\"No response parser exists: access has not been provisioned and no \\"\\n            \\"real payload has been observed. \\"\\n            \\"https://www.psacard.com/publicapi/documentation\\"\\n        )\\n\\n\\nclass EbaySoldAdapter(SalesSource):\\n    \\"\\"\\"Completed-sales source. Disabled, and no response parser is written.\\n\\n    Access was never granted, so no real Marketplace Insights payload has been\\n    seen. Writing a parser against a schema taken from documentation alone, and\\n    calling it tested because it passes fixtures that were also written from\\n    that documentation, would produce false confidence in the exact place the\\n    product can least afford it. The parser is written when a recorded response\\n    exists.\\n    \\"\\"\\"\\n\\n    def __init__(self, policy: SourcePolicy = EBAY_SOLD_POLICY) -> None:\\n        super().__init__(policy)\\n\\n    def capabilities(self) -> Mapping[str, bool]:\\n        return {\\n            \\"sold_search\\": True,           # offered by the API, not by us\\n            \\"history_days\\": True,          # capped at 90 by the API\\n            \\"unrestricted_categories\\": False,\\n            \\"parser_implemented\\": False,\\n            \\"verified_live_access\\": False,\\n        }\\n\\n    def fetch_sales(self, query: str, since: datetime) -> Sequence[Sale]:\\n        self._guard(\\"sold_search\\")\\n        raise NotImplementedError(\\n            \\"Marketplace Insights is a Limited Release API, access has not been \\"\\n            \\"granted, and no response parser exists because no real payload has \\"\\n            \\"been observed. See \\"\\n            \\"https://developer.ebay.com/api-docs/buy/marketplace-insights/static/overview.html\\"\\n        )\\n\\n\\nclass CardmarketAdapter(ListingSource):\\n    \\"\\"\\"Cardmarket adapter with the Dedicated App polling restriction enforced.\\"\\"\\"\\n\\n    def __init__(\\n        self,\\n        policy: SourcePolicy = CARDMARKET_POLICY,\\n        app_type: str = \\"dedicated\\",\\n    ) -> None:\\n        super().__init__(policy)\\n        self.app_type = app_type\\n\\n    def capabilities(self) -> Mapping[str, bool]:\\n        return {\\n            \\"product_lookup\\": True,        # offered by the API, not by us\\n            \\"own_stock\\": True,\\n            \\"continuous_public_polling\\": self.app_type == \\"third_party\\",\\n            \\"parser_implemented\\": False,\\n            \\"verified_live_access\\": False,\\n        }\\n\\n    def fetch_listings(self, query: str) -> Sequence[Listing]:\\n        self._guard(\\"product_lookup\\")\\n        if self.app_type == \\"dedicated\\":\\n            raise PolicyViolationError(\\n                \\"Cardmarket explicitly disallows Dedicated App users from \\"\\n                \\"constantly requesting only the public Marketplace resources on \\"\\n                \\"consecutive days. A continuous Europe Steal Finder against a \\"\\n                \\"Dedicated credential would breach those terms and risks access \\"\\n                \\"being revoked. See \\"\\n                \\"https://api.cardmarket.com/ws/documentation/API:Auth_Overview\\"\\n            )\\n        raise NotImplementedError(\\"Approved 3rd Party App credentials are not configured.\\")\\n\\n\\nclass PriceChartingAdapter(Adapter):\\n    \\"\\"\\"Current-level cross-check only. No history, no sales.\\"\\"\\"\\n\\n    def __init__(self, policy: SourcePolicy = PRICECHARTING_POLICY, token: Optional[str] = None) -> None:\\n        super().__init__(policy)\\n        self._token = token\\n\\n    def capabilities(self) -> Mapping[str, bool]:\\n        return {\\n            \\"current_prices\\": True,\\n            \\"grade_ladder\\": True,\\n            \\"price_history\\": False,\\n            \\"sales_history\\": False,\\n            # The column translation below is written and unit-tested against\\n            # the published column contract, so this one is genuinely true.\\n            # Live access has still never been exercised.\\n            \\"parser_implemented\\": True,\\n            \\"verified_live_access\\": False,\\n        }\\n\\n    @staticmethod\\n    def interpret(payload: Mapping[str, object]) -> dict[str, object]:\\n        \\"\\"\\"Translate PriceCharting\'s column names into unambiguous labels.\\"\\"\\"\\n        return {\\n            PRICECHARTING_GRADE_MAP.get(k, k): v\\n            for k, v in payload.items()\\n            if k in PRICECHARTING_GRADE_MAP\\n        }\\n", "pokearb_core/adapters/live.py": "\\"\\"\\"Live adapters: ECB reference rates and the TCGdex catalogue.\\n\\nThese two are live because both are freely available on documented terms and\\nwere verified while writing the Phase 1 document:\\n\\n* ECB euro reference rates, daily and historical XML\\n  https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml\\n* TCGdex, multi-language Pokemon TCG catalogue including Japanese\\n  https://tcgdex.dev/\\n\\nThe ECB publishes these rates for information purposes and discourages using\\nthem for transactions, which is why ``CostAssumptions.fx_spread_rate`` exists\\nas a separate, explicit parameter rather than pretending the reference rate is\\nexecutable.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport urllib.request\\nimport xml.etree.ElementTree as ET\\nfrom datetime import date, datetime, timezone\\nfrom decimal import Decimal\\nfrom typing import Mapping, Optional, Sequence\\n\\nfrom ..types import Currency, FxRate\\nfrom .base import Adapter, CatalogueSource, FxSource, RawRecord, SourcePolicy, VerificationStatus\\n\\n__all__ = [\\n    \\"ECB_POLICY\\",\\n    \\"TCGDEX_POLICY\\",\\n    \\"EcbFxAdapter\\",\\n    \\"TcgdexCatalogueAdapter\\",\\n    \\"TcgdexPricingAdapter\\",\\n    \\"parse_tcgdex_cardmarket\\",\\n    \\"same_name_sibling_ids\\",\\n]\\n\\n_ECB_NS = {\\"ex\\": \\"http://www.ecb.int/vocabulary/2002-08-01/eurofxref\\"}\\n\\nECB_POLICY = SourcePolicy(\\n    source_id=\\"ecb\\",\\n    display_name=\\"European Central Bank euro reference rates\\",\\n    base_url=\\"https://www.ecb.europa.eu/stats/eurofxref/\\",\\n    verification_status=VerificationStatus.VERIFIED_API,\\n    enabled=True,\\n    has_official_api=True,\\n    api_docs_url=\\"https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml\\",\\n    max_requests_per_minute=2,\\n    min_seconds_between_requests=Decimal(\\"30\\"),\\n    notes=(\\n        \\"Published for information purposes; the ECB discourages transactional \\"\\n        \\"use, so an explicit FX spread is applied on top in the cost model.\\"\\n    ),\\n)\\n\\nTCGDEX_POLICY = SourcePolicy(\\n    source_id=\\"tcgdex\\",\\n    display_name=\\"TCGdex multi-language Pokemon TCG catalogue\\",\\n    base_url=\\"https://api.tcgdex.net/v2\\",\\n    verification_status=VerificationStatus.VERIFIED_API,\\n    enabled=True,\\n    has_official_api=True,\\n    api_docs_url=\\"https://tcgdex.dev/\\",\\n    max_requests_per_minute=30,\\n    min_seconds_between_requests=Decimal(\\"2\\"),\\n    notes=\\"Open source catalogue. Used as a seed, not as the variant authority.\\",\\n)\\n\\n\\ndef _get(url: str, timeout: int = 20) -> bytes:\\n    req = urllib.request.Request(url, headers={\\"User-Agent\\": \\"pokearb/0.1 (+private research)\\"})\\n    with urllib.request.urlopen(req, timeout=timeout) as resp:  # noqa: S310\\n        return resp.read()\\n\\n\\nclass EcbFxAdapter(FxSource):\\n    \\"\\"\\"Daily and historical euro reference rates.\\n\\n    Rates are returned as ``EUR -> X``. The arbitrage engine needs\\n    ``JPY -> EUR``, which is derived here by inversion, and ``EUR -> DKK``\\n    directly. Both are stored dated so historical calculations reproduce.\\n    \\"\\"\\"\\n\\n    DAILY_URL = \\"https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml\\"\\n    HIST_90D_URL = \\"https://www.ecb.europa.eu/stats/eurofxref/eurofxref-hist-90d.xml\\"\\n\\n    def __init__(self, policy: SourcePolicy = ECB_POLICY, fetcher=_get) -> None:\\n        super().__init__(policy)\\n        self._fetch = fetcher\\n\\n    def capabilities(self) -> Mapping[str, bool]:\\n        return {\\"fx_current\\": True, \\"fx_history\\": True, \\"fx_intraday\\": False}\\n\\n    def fetch_rates(self, on: Optional[date] = None) -> Sequence[FxRate]:\\n        self._guard(\\"fx_poll\\")\\n        url = self.DAILY_URL if on is None else self.HIST_90D_URL\\n        raw = RawRecord(\\n            self.source_id, datetime.now(timezone.utc), url,\\n            None, http_status=None,\\n        )\\n        return self.parse(self._fetch(url), url, target_date=on)\\n\\n    def parse(\\n        self, xml_bytes: bytes, url: str, target_date: Optional[date] = None\\n    ) -> list[FxRate]:\\n        \\"\\"\\"Parse the ECB envelope into dated rates, including derived pairs.\\"\\"\\"\\n        root = ET.fromstring(xml_bytes)\\n        out: list[FxRate] = []\\n        for day_cube in root.iterfind(\\".//ex:Cube[@time]\\", _ECB_NS):\\n            as_of = date.fromisoformat(day_cube.attrib[\\"time\\"])\\n            if target_date is not None and as_of != target_date:\\n                continue\\n            per_currency: dict[Currency, Decimal] = {}\\n            for cube in day_cube.iterfind(\\"ex:Cube[@currency]\\", _ECB_NS):\\n                try:\\n                    code = Currency(cube.attrib[\\"currency\\"])\\n                except ValueError:\\n                    continue\\n                per_currency[code] = Decimal(cube.attrib[\\"rate\\"])\\n            out.extend(self.derive(as_of, per_currency, url))\\n        return out\\n\\n    @staticmethod\\n    def derive(\\n        as_of: date, per_currency: Mapping[\\"Currency\\", Decimal], url: str\\n    ) -> list[FxRate]:\\n        \\"\\"\\"Every pair the engine uses, from ECB euro reference rates.\\n\\n        Shared by the XML feed parser and by the browser page, which reads the\\n        same reference rates from the ECB Data API, so both derive identical\\n        inverses and cross rates.\\n        \\"\\"\\"\\n        out: list[FxRate] = []\\n        for code, rate in per_currency.items():\\n            out.append(FxRate(as_of, Currency.EUR, code, rate, url))\\n            if rate > 0:\\n                out.append(\\n                    FxRate(\\n                        as_of, code, Currency.EUR,\\n                        (Decimal(\\"1\\") / rate).quantize(Decimal(\\"0.00000001\\")),\\n                        url,\\n                    )\\n                )\\n        # JPY -> DKK via EUR, useful for direct presentation.\\n        jpy, dkk = per_currency.get(Currency.JPY), per_currency.get(Currency.DKK)\\n        if jpy and dkk and jpy > 0:\\n            out.append(\\n                FxRate(\\n                    as_of, Currency.JPY, Currency.DKK,\\n                    (dkk / jpy).quantize(Decimal(\\"0.00000001\\")), url,\\n                )\\n            )\\n        return out\\n\\n    @staticmethod\\n    def as_map(rates: Sequence[FxRate]) -> dict[tuple[Currency, Currency], FxRate]:\\n        latest: dict[tuple[Currency, Currency], FxRate] = {}\\n        for rate in rates:\\n            key = (rate.base, rate.quote)\\n            if key not in latest or rate.as_of > latest[key].as_of:\\n                latest[key] = rate\\n        return latest\\n\\n\\nclass TcgdexCatalogueAdapter(CatalogueSource):\\n    \\"\\"\\"Canonical card seed data, including Japanese sets and promos.\\n\\n    TCGdex is a seed, not the variant authority. External catalogues do not\\n    model holo versus reverse-holo versus stamped printings consistently, and\\n    those distinctions are exactly what the arbitrage maths depends on, so the\\n    loader creates one internal variant per *printing* and records which\\n    discriminators the catalogue did not supply.\\n    \\"\\"\\"\\n\\n    def __init__(self, policy: SourcePolicy = TCGDEX_POLICY, fetcher=_get, language: str = \\"ja\\") -> None:\\n        super().__init__(policy)\\n        self._fetch = fetcher\\n        self.language = language\\n\\n    @property\\n    def _base(self) -> str:\\n        return f\\"{self.policy.base_url}/{self.language}\\"\\n\\n    def capabilities(self) -> Mapping[str, bool]:\\n        return {\\n            \\"sets\\": True,\\n            \\"cards\\": True,\\n            \\"images\\": True,\\n            \\"prices\\": False,\\n            \\"printings\\": False,  # not modelled consistently upstream\\n        }\\n\\n    def fetch_sets(self) -> Sequence[RawRecord]:\\n        self._guard(\\"catalogue\\")\\n        url = f\\"{self._base}/sets\\"\\n        import json as _json\\n\\n        payload = _json.loads(self._fetch(url))\\n        return [\\n            RawRecord(self.source_id, datetime.now(timezone.utc), url, payload).with_hash()\\n        ]\\n\\n    def fetch_cards(self, set_code: str) -> Sequence[RawRecord]:\\n        self._guard(\\"catalogue\\")\\n        url = f\\"{self._base}/sets/{set_code}\\"\\n        import json as _json\\n\\n        payload = _json.loads(self._fetch(url))\\n        return [\\n            RawRecord(self.source_id, datetime.now(timezone.utc), url, payload).with_hash()\\n        ]\\n\\n\\n# --------------------------------------------------------------- pricing ----\\n\\n#: TCGdex relays Cardmarket\'s published averages per card, in EUR, updated\\n#: daily, with no key required. Documented at https://tcgdex.dev/markets-prices\\n#: and https://tcgdex.dev/faq. The FAQ also documents the known defect that\\n#: shapes the parser below: different printings of one Pokemon can be mapped to\\n#: the same Cardmarket listing and so show identical prices.\\nTCGDEX_PRICING_DOCS = \\"https://tcgdex.dev/markets-prices\\"\\nTCGDEX_FAQ = \\"https://tcgdex.dev/faq\\"\\n\\n_PRICE_FIELDS = (\\"avg\\", \\"low\\", \\"trend\\", \\"avg1\\", \\"avg7\\", \\"avg30\\")\\n\\n\\ndef _price(value) -> Optional[Decimal]:\\n    \\"\\"\\"A published average, or ``None``. Zero and negatives are not prices.\\n\\n    Recorded responses carry ``\\"trend-holo\\": 0`` for cards that have no\\n    reverse-holo market at all, so reading zero as a price would value a card\\n    at nothing.\\n    \\"\\"\\"\\n    if value is None or isinstance(value, bool):\\n        return None\\n    try:\\n        d = Decimal(str(value))\\n    except Exception:  # noqa: BLE001\\n        return None\\n    return d if d > 0 else None\\n\\n\\ndef _iso(ts: str) -> datetime:\\n    parsed = datetime.fromisoformat(ts.replace(\\"Z\\", \\"+00:00\\"))\\n    return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)\\n\\n\\ndef parse_tcgdex_cardmarket(\\n    payload: Mapping,\\n    *,\\n    printing: \\"Printing\\",\\n    variant_id: str,\\n    known_at: datetime,\\n    language: Optional[\\"Language\\"] = None,\\n    source_url: Optional[str] = None,\\n    raw_hash: Optional[str] = None,\\n) -> tuple[Optional[\\"MarketAverage\\"], tuple[str, ...]]:\\n    \\"\\"\\"Read Cardmarket\'s averages for one printing out of a TCGdex card payload.\\n\\n    Returns ``(observation, reasons)``. ``observation`` is ``None`` whenever the\\n    payload does not say, unambiguously, what this printing sells for, and\\n    ``reasons`` then says why. Nothing is guessed.\\n\\n    Which fields describe which printing is decided from the card\'s own\\n    ``variants`` block, because Cardmarket publishes one set of base fields and\\n    one set of ``-holo`` fields per product:\\n\\n    * reverse holo: the ``-holo`` fields, and only if the card has a reverse;\\n    * the base printing: the plain fields, and only if exactly one of normal\\n      and holo exists, since otherwise the plain fields could describe either;\\n    * anything else (textured, other foils, first editions): refused, because\\n      the provider does not publish those separately.\\n    \\"\\"\\"\\n    from ..types import Currency, MarketAverage, Printing  # local: avoid cycles\\n\\n    reasons: list[str] = []\\n    pricing = payload.get(\\"pricing\\") or {}\\n    cm = pricing.get(\\"cardmarket\\")\\n    if not cm:\\n        return None, (\\"TCGdex publishes no Cardmarket pricing for this card\\",)\\n\\n    if (cm.get(\\"unit\\") or \\"\\").upper() != \\"EUR\\":\\n        return None, (f\\"unexpected Cardmarket currency {cm.get(\'unit\')!r}\\",)\\n    if not cm.get(\\"updated\\"):\\n        return None, (\\"Cardmarket pricing carries no update time; freshness unknowable\\",)\\n\\n    variants = payload.get(\\"variants\\") or {}\\n    has_normal = bool(variants.get(\\"normal\\"))\\n    has_holo = bool(variants.get(\\"holo\\"))\\n    has_reverse = bool(variants.get(\\"reverse\\"))\\n\\n    if variants.get(\\"firstEdition\\"):\\n        return None, (\\n            \\"card exists in a first edition; Cardmarket\'s averages may mix \\"\\n            \\"editions, so no edition-specific price can be read\\",\\n        )\\n\\n    if printing is Printing.REVERSE_HOLO:\\n        if not has_reverse:\\n            return None, (\\"card has no reverse-holo printing on TCGdex\\",)\\n        suffix, finish = \\"-holo\\", \\"reverse\\"\\n    elif printing in (Printing.NON_HOLO, Printing.HOLO):\\n        if has_normal and has_holo:\\n            return None, (\\n                \\"card exists as both normal and holo, and Cardmarket\'s base \\"\\n                \\"averages could describe either; refusing rather than guessing\\",\\n            )\\n        wanted_holo = printing is Printing.HOLO\\n        if wanted_holo and not has_holo:\\n            return None, (\\"card has no holo printing on TCGdex\\",)\\n        if not wanted_holo and not has_normal:\\n            return None, (\\"card has no non-holo printing on TCGdex\\",)\\n        suffix, finish = \\"\\", \\"base\\"\\n    else:\\n        return None, (\\n            f\\"{printing.value} printings are not priced separately by the provider\\",\\n        )\\n\\n    values = {f: _price(cm.get(f + suffix)) for f in _PRICE_FIELDS}\\n    if not any(values.values()):\\n        return None, (f\\"no usable Cardmarket figures for the {finish} printing\\",)\\n\\n    product = cm.get(\\"idProduct\\")\\n    obs = MarketAverage(\\n        variant_id=variant_id,\\n        provider=\\"cardmarket\\",\\n        via=\\"tcgdex\\",\\n        product_id=str(product) if product not in (None, \\"\\", 0) else None,\\n        finish=finish,\\n        currency=Currency.EUR,\\n        provider_updated_at=_iso(str(cm[\\"updated\\"])),\\n        known_at=known_at,\\n        market=\\"EU\\",\\n        language=language,\\n        source_url=source_url,\\n        raw_hash=raw_hash,\\n        **values,\\n    )\\n    return obs, tuple(reasons)\\n\\n\\ndef same_name_sibling_ids(set_payload: Mapping, card_id: str) -> list[str]:\\n    \\"\\"\\"Other cards in the same set with the same name.\\n\\n    These are the cards at risk of sharing this card\'s Cardmarket listing, per\\n    the defect TCGdex documents: different printings of one Pokemon mapped to\\n    the same external listing.\\n    \\"\\"\\"\\n    cards = set_payload.get(\\"cards\\") or []\\n    mine = next((c for c in cards if c.get(\\"id\\") == card_id), None)\\n    if mine is None:\\n        return []\\n    return [\\n        c[\\"id\\"] for c in cards\\n        if c.get(\\"name\\") == mine.get(\\"name\\") and c.get(\\"id\\") != card_id\\n    ]\\n\\n\\nclass TcgdexPricingAdapter(Adapter):\\n    \\"\\"\\"Live Cardmarket averages via TCGdex, with the sibling collision check.\\n\\n    Parser written and tested against recorded responses; live access\\n    verified. See tests/fixtures/tcgdex/README.md.\\n    \\"\\"\\"\\n\\n    def __init__(self, policy: SourcePolicy = TCGDEX_POLICY, fetcher=_get) -> None:\\n        super().__init__(policy)\\n        self._fetch = fetcher\\n\\n    def capabilities(self) -> Mapping[str, bool]:\\n        return {\\n            \\"market_averages\\": True,\\n            \\"individual_sales\\": False,   # averages only; never sale-level data\\n            \\"sale_counts\\": False,        # how many sales sit behind an average\\n            \\"parser_implemented\\": True,\\n            \\"verified_live_access\\": True,\\n        }\\n\\n    def _json(self, url: str) -> tuple[dict, RawRecord]:\\n        import json as _json\\n\\n        payload = _json.loads(self._fetch(url))\\n        raw = RawRecord(self.source_id, datetime.now(timezone.utc), url, payload).with_hash()\\n        return payload, raw\\n\\n    def card(self, card_id: str, language: str = \\"ja\\") -> tuple[dict, RawRecord]:\\n        self._guard(\\"catalogue\\")\\n        return self._json(f\\"{self.policy.base_url}/{language}/cards/{card_id}\\")\\n\\n    def set_listing(self, set_id: str, language: str = \\"ja\\") -> tuple[dict, RawRecord]:\\n        self._guard(\\"catalogue\\")\\n        return self._json(f\\"{self.policy.base_url}/{language}/sets/{set_id}\\")\\n\\n    def observe(\\n        self,\\n        card_id: str,\\n        *,\\n        printing: \\"Printing\\",\\n        variant_id: str,\\n        language: str = \\"ja\\",\\n    ) -> dict:\\n        \\"\\"\\"Fetch one card\'s averages plus the product ids of its same-name siblings.\\n\\n        Returns a dict with ``observation``, ``reasons``, ``sibling_product_ids``,\\n        ``sibling_ids`` and ``raw`` (every payload fetched, for persistence).\\n        \\"\\"\\"\\n        from ..types import Language, Printing\\n\\n        payload, raw = self.card(card_id, language)\\n        lang = Language(language) if language in {l.value for l in Language} else None\\n        obs, reasons = parse_tcgdex_cardmarket(\\n            payload, printing=printing, variant_id=variant_id,\\n            known_at=raw.fetched_at, language=lang,\\n            source_url=raw.request_url, raw_hash=raw.content_hash,\\n        )\\n        raws = [raw]\\n        sibling_products: list[str] = []\\n        sibling_ids: list[str] = []\\n        set_id = ((payload.get(\\"set\\") or {}).get(\\"id\\")) or card_id.rsplit(\\"-\\", 1)[0]\\n        try:\\n            set_payload, set_raw = self.set_listing(set_id, language)\\n            raws.append(set_raw)\\n            sibling_ids = same_name_sibling_ids(set_payload, card_id)\\n            for sid in sibling_ids[:6]:\\n                sp, sraw = self.card(sid, language)\\n                raws.append(sraw)\\n                prod = ((sp.get(\\"pricing\\") or {}).get(\\"cardmarket\\") or {}).get(\\"idProduct\\")\\n                if prod not in (None, \\"\\", 0):\\n                    sibling_products.append(str(prod))\\n        except Exception as exc:  # noqa: BLE001\\n            # The collision check could not run. Say so; the benchmark\\n            # refuses an observation whose mapping could not be checked.\\n            reasons = tuple(reasons) + (f\\"sibling check failed: {exc}\\",)\\n            sibling_products = None  # type: ignore[assignment]\\n        return {\\n            \\"observation\\": obs,\\n            \\"reasons\\": tuple(reasons),\\n            \\"sibling_product_ids\\": sibling_products,\\n            \\"sibling_ids\\": sibling_ids,\\n            \\"raw\\": raws,\\n        }\\n\\n\\ndef tcgdex_card_id_candidates(set_code: str, number: str) -> list[str]:\\n    \\"\\"\\"TCGdex ids to try for a canonical set code and number.\\n\\n    TCGdex matches the set part case-insensitively but needs the number\\n    zero-padded to three digits (``SV2a-025`` resolves, ``SV2a-25`` does not),\\n    verified against the live API when this was written.\\n    \\"\\"\\"\\n    num = (number or \\"\\").split(\\"/\\")[0].strip()\\n    if not set_code or not num:\\n        return []\\n    out = []\\n    if num.isdigit():\\n        out.append(f\\"{set_code}-{num.zfill(3)}\\")\\n    out.append(f\\"{set_code}-{num}\\")\\n    return list(dict.fromkeys(out))\\n", "pokearb_core/arbitrage/__init__.py": "\\"\\"\\"PokeArb core subpackage.\\"\\"\\"\\n", "pokearb_core/arbitrage/engine.py": "\\"\\"\\"Japan to Europe arbitrage engine.\\n\\nOne forward calculation, one backward solver, and the solver is not allowed to\\ndisagree with the forward calculation.\\n\\nThe earlier version derived the affine slope of landed cost analytically, by\\nhand, alongside the forward formula. The two drifted: the slope treated the\\nproxy fee as dutiable and VATable when the forward calculation did not, so a\\nmaximum buy price solved for a 40 percent required return actually returned\\n21 to 38 percent. Any solver that restates the cost model in a second place\\nwill eventually restate it wrongly.\\n\\nSo the slope is now measured from the forward function itself. Within a cost\\nregime the landed cost really is affine in the purchase price, so evaluating\\n``compute_landed_cost`` at two points inside a regime recovers the exact slope\\nand intercept for that regime, whatever the forward code happens to do. Every\\ncandidate is then re-checked against the forward calculation before it is\\nreturned, and the next yen up is checked to be infeasible.\\n\\nRegimes are bounded by real discontinuities, each of which is a place where a\\nnaive solver silently assumes the wrong treatment:\\n\\n* the EUR 150 customs duty threshold,\\n* the Danish traveller allowance, when it applies at all,\\n* the JPY 5,000 per store per day Japanese tax-free minimum.\\n\\nTwo economic quantities are kept apart throughout, because conflating them\\noverstates return:\\n\\n``upfront_cash_eur``\\n    What actually leaves the bank to acquire the card. This is the capital\\n    denominator for ROI.\\n``total_eur``\\n    The economic cost, that is upfront cash less the probability-weighted\\n    expected tax refund. The refund is a contingent receivable claimed after a\\n    customs departure procedure, not a discount at the till.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport math\\nfrom dataclasses import dataclass, replace\\nfrom datetime import date\\nfrom decimal import ROUND_CEILING, ROUND_FLOOR, Decimal\\nfrom typing import Callable, Mapping, Optional, Sequence\\n\\nfrom ..types import AcquisitionPurpose, Currency, FxRate, Money, Scenario\\nfrom .policy import PolicyStore, PolicyUnverifiedError\\n\\n__all__ = [\\n    \\"CostAssumptions\\",\\n    \\"CostAssumptionError\\",\\n    \\"LandedCost\\",\\n    \\"Economics\\",\\n    \\"ArbitrageResult\\",\\n    \\"compute_landed_cost\\",\\n    \\"compute_economics\\",\\n    \\"compute_arbitrage\\",\\n    \\"max_buy_price\\",\\n    \\"resale_economics_fn\\",\\n    \\"POLICY_KEYS\\",\\n]\\n\\nPOLICY_KEYS = (\\n    \\"dk.import_vat_rate\\",\\n    \\"dk.duty_threshold_eur\\",\\n    \\"dk.low_value_per_item_charge_eur\\",\\n    \\"dk.carrier_handling_fee_dkk\\",\\n    \\"dk.traveller_allowance_air_dkk\\",\\n    \\"jp.consumption_tax_rate\\",\\n    \\"jp.tax_free_minimum_jpy\\",\\n    \\"jp.tax_free_refund_at_departure_from\\",\\n)\\n\\n#: Source for the Danish traveller-relief conditions encoded below.\\nSKAT_REJSEGODS_URL = \\"https://info.skat.dk/data.aspx?oid=2230232\\"\\n#: Source for the Japanese tax-free regime change encoded below.\\nJP_TAXFREE_URL = \\"https://www.japan-guide.com/news/tax-free-shopping.html\\"\\n\\n\\nclass CostAssumptionError(ValueError):\\n    \\"\\"\\"The supplied cost assumptions cannot produce an actionable number.\\"\\"\\"\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass CostAssumptions:\\n    \\"\\"\\"User-controlled cost parameters. Distinct from policy, which is law.\\"\\"\\"\\n\\n    scenario: Scenario\\n    #: Why the goods are imported. Drives whether personal-use reliefs may be\\n    #: modelled at all. Defaults to resale because this is an arbitrage system.\\n    acquisition_purpose: AcquisitionPurpose = AcquisitionPurpose.RESALE\\n    #: Proportional FX cost above the ECB reference rate. The ECB publishes\\n    #: reference rates for information only, so the executable rate is worse.\\n    fx_spread_rate: Decimal = Decimal(\\"0.015\\")\\n    #: Japan-side\\n    proxy_fee_rate: Decimal = Decimal(\\"0\\")\\n    proxy_fee_fixed_jpy: Decimal = Decimal(\\"0\\")\\n    domestic_jp_shipping_jpy: Decimal = Decimal(\\"0\\")\\n    international_shipping_jpy: Decimal = Decimal(\\"0\\")\\n    insurance_rate: Decimal = Decimal(\\"0\\")\\n    #: Probability that a tax refund claimed at departure is actually realised.\\n    #: Under the regime in force from 2026-11-01 the refund depends on\\n    #: completing a customs departure procedure with every item on the receipt\\n    #: present; if any item is missing the whole receipt becomes ineligible.\\n    #: Verified at https://www.japan-guide.com/news/tax-free-shopping.html\\n    tax_refund_realisation_prob: Decimal = Decimal(\\"0.9\\")\\n    #: Customs duty rate for the commodity code. ``None`` means not verified,\\n    #: and the engine will refuse to compute rather than assume zero.\\n    duty_rate: Optional[Decimal] = None\\n    #: Sell-side\\n    marketplace_fee_rate: Decimal = Decimal(\\"0.05\\")\\n    payment_fee_rate: Decimal = Decimal(\\"0.029\\")\\n    payment_fee_fixed_eur: Decimal = Decimal(\\"0.35\\")\\n    outbound_shipping_eur: Decimal = Decimal(\\"0\\")\\n    #: Expected loss rate from returns, damage in transit and non-payment.\\n    expected_loss_rate: Decimal = Decimal(\\"0.02\\")\\n    #: Number of distinct items in the consignment or on the receipt. Drives\\n    #: the per-item low-value charge introduced on 1 July 2026.\\n    items_in_consignment: int = 1\\n    #: Total value of the consignment or receipt this card belongs to, in JPY.\\n    #: Thresholds are assessed at this level, not per card: the Danish value\\n    #: limit applies to the traveller\'s goods in aggregate, and the Japanese\\n    #: refund is all-or-nothing per receipt. ``None`` means the card travels\\n    #: alone. Verified at https://info.skat.dk/data.aspx?oid=2230232 and\\n    #: https://www.japan-guide.com/news/tax-free-shopping.html\\n    basket_value_jpy: Optional[Decimal] = None\\n    #: Explicit acknowledgement that a zero shipping or proxy cost is a real\\n    #: measured zero rather than an unfilled field. Without it, a scenario that\\n    #: cannot plausibly cost nothing is refused rather than quietly costed at\\n    #: zero.\\n    zero_logistics_cost_is_verified: bool = False\\n\\n    def problems(self) -> tuple[str, ...]:\\n        \\"\\"\\"Blocking problems with these assumptions. Empty means usable.\\"\\"\\"\\n        issues: list[str] = []\\n        if not isinstance(self.scenario, Scenario):\\n            issues.append(\\n                f\\"unknown acquisition scenario {self.scenario!r}; \\"\\n                \\"hand carry is not a safe default for an unrecognised scenario\\"\\n            )\\n            return tuple(issues)\\n\\n        if self.scenario is Scenario.SHIPPED:\\n            if (\\n                self.international_shipping_jpy <= 0\\n                and not self.zero_logistics_cost_is_verified\\n            ):\\n                issues.append(\\n                    \\"shipped scenario with no international shipping cost; set \\"\\n                    \\"international_shipping_jpy or set \\"\\n                    \\"zero_logistics_cost_is_verified if the zero is real\\"\\n                )\\n        if self.scenario is Scenario.PROXY:\\n            no_proxy_fee = self.proxy_fee_rate <= 0 and self.proxy_fee_fixed_jpy <= 0\\n            no_freight = (\\n                self.international_shipping_jpy <= 0\\n                and self.domestic_jp_shipping_jpy <= 0\\n            )\\n            if (no_proxy_fee or no_freight) and not self.zero_logistics_cost_is_verified:\\n                missing = []\\n                if no_proxy_fee:\\n                    missing.append(\\"proxy fee\\")\\n                if no_freight:\\n                    missing.append(\\"freight\\")\\n                issues.append(\\n                    \\"proxy scenario with no \\" + \\" and no \\".join(missing)\\n                    + \\"; supply the cost or set zero_logistics_cost_is_verified\\"\\n                )\\n        if self.tax_refund_realisation_prob < 0 or self.tax_refund_realisation_prob > 1:\\n            issues.append(\\"tax_refund_realisation_prob must be between 0 and 1\\")\\n        if self.items_in_consignment < 1:\\n            issues.append(\\"items_in_consignment must be at least 1\\")\\n        return tuple(issues)\\n\\n    def validated(self) -> \\"CostAssumptions\\":\\n        issues = self.problems()\\n        if issues:\\n            raise CostAssumptionError(\\"; \\".join(issues))\\n        return self\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass LandedCost:\\n    \\"\\"\\"Full cost of getting one card from a Japanese shop into sellable stock.\\"\\"\\"\\n\\n    purchase_jpy: Money\\n    #: Economic cost: upfront cash less the expected (probability-weighted) refund.\\n    total_eur: Money\\n    total_dkk: Optional[Money]\\n    #: Cash that actually leaves the bank. The ROI denominator.\\n    upfront_cash_eur: Money\\n    #: Probability-weighted contingent refund, already netted out of total_eur.\\n    expected_refund_eur: Money\\n    duty_regime: str\\n    breakdown: Mapping[str, Money]\\n    policy_sources: Mapping[str, Optional[str]]\\n    notes: tuple[str, ...] = ()\\n    #: Cost elements known to apply but not quantified. Non-empty means the\\n    #: landed cost understates reality and must not drive a recommendation.\\n    unresolved: tuple[str, ...] = ()\\n\\n    @property\\n    def actionable(self) -> bool:\\n        return not self.unresolved\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass Economics:\\n    \\"\\"\\"One consistent financial view, shared by every consumer.\\n\\n    Profit is economic (it credits the expected refund); the denominator is the\\n    cash actually deployed. Both are stated so the two reconcile without the\\n    reader guessing which convention is in force.\\n    \\"\\"\\"\\n\\n    purchase_jpy: Money\\n    gross_resale_eur: Money\\n    landed: LandedCost\\n    net_proceeds_eur: Money\\n    capital_deployed_eur: Money\\n    profit_eur: Money\\n    roi: Decimal\\n    capital_basis: str = \\"upfront cash deployed, expected tax refund excluded\\"\\n\\n    @property\\n    def actionable(self) -> bool:\\n        return self.landed.actionable\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ArbitrageResult:\\n    scenario: Scenario\\n    landed: LandedCost\\n    gross_resale_eur: Money\\n    net_proceeds_eur: Money\\n    expected_profit_eur: Money\\n    expected_profit_dkk: Optional[Money]\\n    roi: Decimal\\n    capital_deployed_eur: Money\\n    capital_basis: str\\n    gross_multiple: Decimal\\n    net_multiple: Decimal\\n    break_even_resale_eur: Money\\n    max_buy_jpy: Optional[Money]\\n    strong_buy_jpy: Optional[Money]\\n    target_buy_jpy: Optional[Money]\\n    do_not_buy_above_jpy: Optional[Money]\\n    notes: tuple[str, ...] = ()\\n    unresolved: tuple[str, ...] = ()\\n\\n    @property\\n    def actionable(self) -> bool:\\n        return not self.unresolved\\n\\n\\ndef _rate(fx: Mapping[tuple[Currency, Currency], FxRate], a: Currency, b: Currency) -> FxRate:\\n    rate = fx.get((a, b))\\n    if rate is None:\\n        raise KeyError(f\\"Missing dated FX rate {a.value}->{b.value}.\\")\\n    return rate\\n\\n\\ndef _jpy_to_eur(amount: Decimal, fx, spread: Decimal) -> Decimal:\\n    rate = _rate(fx, Currency.JPY, Currency.EUR)\\n    return amount * rate.rate * (Decimal(\\"1\\") + spread)\\n\\n\\n# ------------------------------------------------------------ forward model --\\n\\ndef compute_landed_cost(\\n    purchase_jpy: Money,\\n    *,\\n    on: date,\\n    assumptions: CostAssumptions,\\n    policy: PolicyStore,\\n    fx_rates: Mapping[tuple[Currency, Currency], FxRate],\\n    jp_price_includes_tax: bool = True,\\n) -> LandedCost:\\n    \\"\\"\\"Landed cost in EUR for one card, under one acquisition scenario.\\n\\n    This is the single forward truth. The solver fits against it rather than\\n    restating it.\\n    \\"\\"\\"\\n    if purchase_jpy.currency is not Currency.JPY:\\n        raise ValueError(\\"Japanese purchase price must be in JPY.\\")\\n\\n    a = assumptions.validated()\\n    notes: list[str] = []\\n    unresolved: list[str] = []\\n    breakdown: dict[str, Money] = {}\\n    spread = a.fx_spread_rate\\n\\n    jp_tax_rate = policy.value(\\"jp.consumption_tax_rate\\", on)\\n    departure_refund_regime = policy.try_value(\\"jp.tax_free_refund_at_departure_from\\", on)\\n\\n    gross_jpy = purchase_jpy.amount\\n    #: Thresholds are assessed on the basket, not the single card.\\n    basket_jpy = a.basket_value_jpy if a.basket_value_jpy is not None else gross_jpy\\n    if basket_jpy < gross_jpy:\\n        raise CostAssumptionError(\\n            \\"basket_value_jpy is smaller than this card\'s price; the basket must \\"\\n            \\"contain the card.\\"\\n        )\\n    breakdown[\\"jp_shelf_price\\"] = Money(gross_jpy, Currency.JPY)\\n\\n    tax_component = Decimal(\\"0\\")\\n    if jp_price_includes_tax:\\n        tax_component = gross_jpy - (gross_jpy / (Decimal(\\"1\\") + jp_tax_rate))\\n\\n    # --- Japanese consumption tax treatment ------------------------------\\n    refund_jpy = Decimal(\\"0\\")\\n    personal = a.acquisition_purpose is AcquisitionPurpose.PERSONAL\\n\\n    if a.scenario is Scenario.HAND_CARRY and personal:\\n        min_spend = policy.try_value(\\"jp.tax_free_minimum_jpy\\", on)\\n        if min_spend is not None and basket_jpy >= min_spend:\\n            if departure_refund_regime is None or departure_refund_regime >= 1:\\n                realisation = a.tax_refund_realisation_prob\\n                notes.append(\\n                    \\"consumption tax modelled as a contingent refund realised at \\"\\n                    f\\"departure, weighted by p={realisation}; from 2026-11-01 the \\"\\n                    \\"refund is claimed on leaving Japan and the whole receipt \\"\\n                    \\"becomes ineligible if any item on it is absent \\"\\n                    f\\"({JP_TAXFREE_URL})\\"\\n                )\\n                if departure_refund_regime is None:\\n                    notes.append(\\n                        \\"tax-free regime not recorded for this date; the \\"\\n                        \\"contingent treatment was assumed as the conservative case\\"\\n                    )\\n            else:\\n                realisation = Decimal(\\"1\\")\\n                notes.append(\\n                    \\"consumption tax deducted at the shop under the pre-2026-11-01 \\"\\n                    \\"regime; treated as an immediate price reduction\\"\\n                )\\n            refund_jpy = tax_component * realisation\\n        elif min_spend is not None:\\n            notes.append(\\n                f\\"basket of {basket_jpy:.0f} JPY is below the {min_spend} JPY per \\"\\n                \\"store per day tax-free minimum; no refund modelled\\"\\n            )\\n    elif a.scenario is Scenario.HAND_CARRY:\\n        notes.append(\\n            \\"no Japanese tax refund modelled: the visitor scheme covers goods the \\"\\n            \\"traveller personally carries out for their own use, and these are \\"\\n            f\\"declared as resale inventory ({JP_TAXFREE_URL})\\"\\n        )\\n    else:\\n        notes.append(\\n            \\"tax-free exemption not modelled: since 2025-04-01 goods shipped \\"\\n            \\"internationally are outside the scheme, so the scenario carries \\"\\n            \\"Japanese consumption tax in full\\"\\n        )\\n\\n    breakdown[\\"jp_tax_refund\\"] = Money(-refund_jpy, Currency.JPY)\\n\\n    proxy_fee = gross_jpy * a.proxy_fee_rate + a.proxy_fee_fixed_jpy\\n    if a.scenario is not Scenario.PROXY and (a.proxy_fee_rate or a.proxy_fee_fixed_jpy):\\n        notes.append(\\"proxy fees supplied for a non-proxy scenario; included as given\\")\\n    breakdown[\\"proxy_fee\\"] = Money(proxy_fee, Currency.JPY)\\n    breakdown[\\"jp_domestic_shipping\\"] = Money(a.domestic_jp_shipping_jpy, Currency.JPY)\\n    breakdown[\\"international_shipping\\"] = Money(a.international_shipping_jpy, Currency.JPY)\\n\\n    # --- Import treatment -------------------------------------------------\\n    goods_value_eur = _jpy_to_eur(gross_jpy, fx_rates, spread)\\n    basket_value_eur = _jpy_to_eur(basket_jpy, fx_rates, spread)\\n    duty_threshold_eur = policy.value(\\"dk.duty_threshold_eur\\", on)\\n    vat_rate = policy.value(\\"dk.import_vat_rate\\", on)\\n\\n    duty_regime = \\"n/a\\"\\n    duty_rate = Decimal(\\"0\\")\\n    per_item_charge_eur = Decimal(\\"0\\")\\n    charge_import_taxes = True\\n\\n    if a.scenario is Scenario.HAND_CARRY and personal:\\n        allowance = policy.try_value(\\"dk.traveller_allowance_air_dkk\\", on)\\n        if allowance is None:\\n            duty_regime = \\"traveller_allowance_unknown\\"\\n            unresolved.append(\\n                \\"traveller allowance not recorded for this date; import treatment \\"\\n                \\"for hand-carried personal goods is unresolved\\"\\n            )\\n            charge_import_taxes = False\\n        else:\\n            dkk_rate = _rate(fx_rates, Currency.EUR, Currency.DKK)\\n            basket_dkk = basket_value_eur * dkk_rate.rate\\n            if basket_dkk <= allowance:\\n                duty_regime = \\"traveller_allowance\\"\\n                charge_import_taxes = False\\n                notes.append(\\n                    f\\"basket of {basket_dkk:.0f} DKK is within the {allowance} DKK \\"\\n                    \\"traveller allowance for arrival by air or sea; no import VAT \\"\\n                    f\\"or duty modelled ({SKAT_REJSEGODS_URL})\\"\\n                )\\n            else:\\n                # Above the limit, duty and tax fall on the goods in their\\n                # entirety; the value of an item cannot be split, and two\\n                # travellers may not pool or divide the allowance.\\n                duty_regime = \\"traveller_allowance_exceeded\\"\\n                notes.append(\\n                    f\\"basket of {basket_dkk:.0f} DKK exceeds the {allowance} DKK \\"\\n                    \\"traveller allowance, so duty and VAT fall on the goods in \\"\\n                    f\\"their entirety ({SKAT_REJSEGODS_URL})\\"\\n                )\\n                if basket_value_eur > duty_threshold_eur and a.duty_rate is None:\\n                    raise PolicyUnverifiedError(\\n                        \\"Hand-carried basket exceeds both the traveller allowance \\"\\n                        \\"and the customs duty threshold, but no verified duty rate \\"\\n                        \\"is configured for collectible trading cards. Classify the \\"\\n                        \\"commodity code before relying on this landed cost.\\"\\n                    )\\n                duty_rate = a.duty_rate or Decimal(\\"0\\")\\n    else:\\n        # Commercial import, or a shipped/proxy consignment. Relief for\\n        # travellers\' goods is confined to goods for private use and is\\n        # expressly unavailable where goods are imported with a view to\\n        # resale, so nothing is relieved here.\\n        if a.scenario is Scenario.HAND_CARRY:\\n            notes.append(\\n                \\"traveller allowance not applied: relief covers goods for private \\"\\n                \\"use and an import with a view to resale is not of non-commercial \\"\\n                f\\"character ({SKAT_REJSEGODS_URL})\\"\\n            )\\n        if basket_value_eur > duty_threshold_eur:\\n            duty_regime = \\"above_threshold\\"\\n            if a.duty_rate is None:\\n                raise PolicyUnverifiedError(\\n                    \\"Consignment value exceeds the customs duty threshold but no \\"\\n                    \\"verified duty rate is configured for collectible trading \\"\\n                    \\"cards. Classify the commodity code before relying on this \\"\\n                    \\"landed cost.\\"\\n                )\\n            duty_rate = a.duty_rate\\n        else:\\n            duty_regime = \\"low_value\\"\\n            low_value = policy.try_value(\\"dk.low_value_per_item_charge_eur\\", on)\\n            if low_value is not None:\\n                per_item_charge_eur = low_value * Decimal(a.items_in_consignment)\\n                notes.append(\\n                    \\"per-item low-value customs charge applied \\"\\n                    f\\"({low_value} EUR x {a.items_in_consignment} item(s))\\"\\n                )\\n\\n    freight_eur = _jpy_to_eur(\\n        a.domestic_jp_shipping_jpy + a.international_shipping_jpy, fx_rates, spread\\n    )\\n    proxy_eur = _jpy_to_eur(proxy_fee, fx_rates, spread)\\n    refund_eur = _jpy_to_eur(refund_jpy, fx_rates, spread)\\n    insurance_eur = goods_value_eur * a.insurance_rate\\n\\n    duty_eur = Decimal(\\"0\\")\\n    vat_eur = Decimal(\\"0\\")\\n    handling_eur = Decimal(\\"0\\")\\n\\n    if charge_import_taxes:\\n        customs_value = goods_value_eur + freight_eur\\n        duty_eur = customs_value * duty_rate\\n        vat_eur = (customs_value + duty_eur + per_item_charge_eur) * vat_rate\\n        if a.scenario is not Scenario.HAND_CARRY:\\n            handling_dkk = policy.try_value(\\"dk.carrier_handling_fee_dkk\\", on)\\n            if handling_dkk is not None:\\n                dkk_rate = _rate(fx_rates, Currency.EUR, Currency.DKK)\\n                handling_eur = handling_dkk / dkk_rate.rate\\n    else:\\n        per_item_charge_eur = Decimal(\\"0\\")\\n\\n    breakdown[\\"goods_value_eur\\"] = Money(goods_value_eur, Currency.EUR).quantize()\\n    breakdown[\\"freight_eur\\"] = Money(freight_eur, Currency.EUR).quantize()\\n    breakdown[\\"insurance_eur\\"] = Money(insurance_eur, Currency.EUR).quantize()\\n    breakdown[\\"customs_duty_eur\\"] = Money(duty_eur, Currency.EUR).quantize()\\n    breakdown[\\"low_value_charge_eur\\"] = Money(per_item_charge_eur, Currency.EUR).quantize()\\n    breakdown[\\"import_vat_eur\\"] = Money(vat_eur, Currency.EUR).quantize()\\n    breakdown[\\"carrier_handling_eur\\"] = Money(handling_eur, Currency.EUR).quantize()\\n    breakdown[\\"expected_tax_refund_eur\\"] = Money(-refund_eur, Currency.EUR).quantize()\\n    breakdown[\\"proxy_fee_eur\\"] = Money(proxy_eur, Currency.EUR).quantize()\\n\\n    upfront = (\\n        goods_value_eur + freight_eur + insurance_eur + duty_eur\\n        + per_item_charge_eur + vat_eur + handling_eur + proxy_eur\\n    )\\n    total_eur = upfront - refund_eur\\n\\n    dkk_rate = fx_rates.get((Currency.EUR, Currency.DKK))\\n    total_dkk = (\\n        Money(total_eur * dkk_rate.rate, Currency.DKK).quantize() if dkk_rate else None\\n    )\\n\\n    return LandedCost(\\n        purchase_jpy=purchase_jpy,\\n        total_eur=Money(total_eur, Currency.EUR).quantize(),\\n        total_dkk=total_dkk,\\n        upfront_cash_eur=Money(upfront, Currency.EUR).quantize(),\\n        expected_refund_eur=Money(refund_eur, Currency.EUR).quantize(),\\n        duty_regime=duty_regime,\\n        breakdown=breakdown,\\n        policy_sources=policy.sources(POLICY_KEYS, on),\\n        notes=tuple(notes),\\n        unresolved=tuple(unresolved),\\n    )\\n\\n\\ndef _net_proceeds(gross_resale_eur: Money, a: CostAssumptions) -> Money:\\n    gross = gross_resale_eur.amount\\n    fees = gross * (a.marketplace_fee_rate + a.payment_fee_rate) + a.payment_fee_fixed_eur\\n    net = (gross - fees - a.outbound_shipping_eur) * (Decimal(\\"1\\") - a.expected_loss_rate)\\n    return Money(net, Currency.EUR).quantize()\\n\\n\\ndef compute_economics(\\n    *,\\n    purchase_jpy: Money,\\n    gross_resale_eur: Money,\\n    on: date,\\n    assumptions: CostAssumptions,\\n    policy: PolicyStore,\\n    fx_rates: Mapping[tuple[Currency, Currency], FxRate],\\n) -> Economics:\\n    \\"\\"\\"The one financial calculation. Everything else calls this.\\"\\"\\"\\n    landed = compute_landed_cost(\\n        purchase_jpy, on=on, assumptions=assumptions, policy=policy, fx_rates=fx_rates\\n    )\\n    net = _net_proceeds(gross_resale_eur, assumptions)\\n    profit = Money(net.amount - landed.total_eur.amount, Currency.EUR).quantize()\\n    capital = landed.upfront_cash_eur\\n    roi = (profit.amount / capital.amount) if capital.amount > 0 else Decimal(\\"0\\")\\n    return Economics(\\n        purchase_jpy=purchase_jpy,\\n        gross_resale_eur=gross_resale_eur,\\n        landed=landed,\\n        net_proceeds_eur=net,\\n        capital_deployed_eur=capital,\\n        profit_eur=profit,\\n        roi=roi,\\n    )\\n\\n\\ndef resale_economics_fn(\\n    *,\\n    purchase_jpy: Money,\\n    on: date,\\n    assumptions: CostAssumptions,\\n    policy: PolicyStore,\\n    fx_rates: Mapping[tuple[Currency, Currency], FxRate],\\n) -> Callable[[Money], Economics]:\\n    \\"\\"\\"Freeze the buy side, vary the resale value.\\n\\n    Handed to the scorer so simulations recalculate through this model instead\\n    of applying a flat proceeds ratio of their own.\\n    \\"\\"\\"\\n\\n    def _fn(gross_resale_eur: Money) -> Economics:\\n        return compute_economics(\\n            purchase_jpy=purchase_jpy,\\n            gross_resale_eur=gross_resale_eur,\\n            on=on,\\n            assumptions=assumptions,\\n            policy=policy,\\n            fx_rates=fx_rates,\\n        )\\n\\n    return _fn\\n\\n\\n# ----------------------------------------------------------- backward solve --\\n\\ndef _threshold_points_jpy(\\n    *,\\n    on: date,\\n    assumptions: CostAssumptions,\\n    policy: PolicyStore,\\n    fx_rates: Mapping[tuple[Currency, Currency], FxRate],\\n) -> list[Decimal]:\\n    \\"\\"\\"Purchase prices at which the cost model changes shape.\\n\\n    Expressed in this card\'s own price. When the card travels in a basket the\\n    thresholds bite on the basket, so the equivalent card-level point is the\\n    threshold less the rest of the basket.\\n    \\"\\"\\"\\n    a = assumptions\\n    fx_factor = _rate(fx_rates, Currency.JPY, Currency.EUR).rate * (\\n        Decimal(\\"1\\") + a.fx_spread_rate\\n    )\\n    if fx_factor <= 0:  # pragma: no cover - defensive\\n        return []\\n\\n    rest_of_basket = Decimal(\\"0\\")\\n    points: list[Decimal] = []\\n\\n    def add_from_eur(value_eur: Decimal) -> None:\\n        card_jpy = value_eur / fx_factor - rest_of_basket\\n        if card_jpy > 0:\\n            points.append(card_jpy)\\n\\n    add_from_eur(policy.value(\\"dk.duty_threshold_eur\\", on))\\n\\n    personal = a.acquisition_purpose is AcquisitionPurpose.PERSONAL\\n    if a.scenario is Scenario.HAND_CARRY and personal:\\n        allowance_dkk = policy.try_value(\\"dk.traveller_allowance_air_dkk\\", on)\\n        dkk = fx_rates.get((Currency.EUR, Currency.DKK))\\n        if allowance_dkk is not None and dkk is not None and dkk.rate > 0:\\n            add_from_eur(allowance_dkk / dkk.rate)\\n        min_spend = policy.try_value(\\"jp.tax_free_minimum_jpy\\", on)\\n        if min_spend is not None:\\n            card_jpy = min_spend - rest_of_basket\\n            if card_jpy > 0:\\n                points.append(card_jpy)\\n\\n    return sorted(set(points))\\n\\n\\ndef _segments(points: Sequence[Decimal], ceiling: Decimal) -> list[tuple[Decimal, Decimal]]:\\n    \\"\\"\\"Half-open price bands between the discontinuities.\\"\\"\\"\\n    bounds = [Decimal(\\"1\\")] + [p for p in points if Decimal(\\"1\\") < p < ceiling] + [ceiling]\\n    out: list[tuple[Decimal, Decimal]] = []\\n    for lo, hi in zip(bounds, bounds[1:]):\\n        if hi - lo >= Decimal(\\"2\\"):\\n            out.append((lo, hi))\\n    return out\\n\\n\\ndef max_buy_price(\\n    *,\\n    gross_resale_eur: Money,\\n    required_roi: Decimal,\\n    on: date,\\n    assumptions: CostAssumptions,\\n    policy: PolicyStore,\\n    fx_rates: Mapping[tuple[Currency, Currency], FxRate],\\n    probe_jpy: Decimal = Decimal(\\"10000\\"),\\n    ceiling_jpy: Optional[Decimal] = None,\\n) -> Optional[Money]:\\n    \\"\\"\\"Highest whole-yen price that still clears ``required_roi``.\\n\\n    Every candidate is verified against ``compute_economics`` and the next yen\\n    up is verified to fail, so the answer cannot disagree with the forward\\n    calculation. Returns ``None`` when no price in the model is feasible, which\\n    is a real answer and not an error.\\n    \\"\\"\\"\\n    a = assumptions.validated()\\n\\n    def economics_at(price_jpy: Decimal) -> Optional[Economics]:\\n        try:\\n            return compute_economics(\\n                purchase_jpy=Money(price_jpy, Currency.JPY),\\n                gross_resale_eur=gross_resale_eur,\\n                on=on,\\n                assumptions=a,\\n                policy=policy,\\n                fx_rates=fx_rates,\\n            )\\n        except (PolicyUnverifiedError, CostAssumptionError, KeyError):\\n            return None\\n\\n    def feasible(price_jpy: Decimal) -> bool:\\n        econ = economics_at(price_jpy)\\n        if econ is None or not econ.actionable:\\n            return False\\n        return econ.roi >= required_roi\\n\\n    # A generous ceiling: the resale value expressed in yen is an upper bound on\\n    # any sane purchase price, since costs are strictly positive.\\n    if ceiling_jpy is None:\\n        jpy_per_eur = fx_rates.get((Currency.EUR, Currency.JPY))\\n        if jpy_per_eur is not None:\\n            ceiling_jpy = gross_resale_eur.amount * jpy_per_eur.rate\\n        else:\\n            fx_factor = _rate(fx_rates, Currency.JPY, Currency.EUR).rate\\n            ceiling_jpy = gross_resale_eur.amount / fx_factor if fx_factor else probe_jpy\\n    ceiling_jpy = max(ceiling_jpy, Decimal(\\"10\\"))\\n\\n    points = _threshold_points_jpy(\\n        on=on, assumptions=a, policy=policy, fx_rates=fx_rates\\n    )\\n    best: Optional[Decimal] = None\\n\\n    for lo, hi in _segments(points, ceiling_jpy):\\n        lo_i = int(lo.to_integral_value(rounding=ROUND_CEILING))\\n        hi_i = int(hi.to_integral_value(rounding=ROUND_FLOOR))\\n        if hi_i < lo_i:\\n            continue\\n\\n        # Feasibility is monotone inside a segment: landed cost is\\n        # non-decreasing in the purchase price and the resale side is fixed, so\\n        # ROI is non-increasing. Segments are cut at every discontinuity\\n        # precisely so that this holds; it is not assumed globally.\\n        if not feasible(Decimal(lo_i)):\\n            continue\\n\\n        if feasible(Decimal(hi_i)):\\n            candidate = hi_i\\n        else:\\n            low, high = lo_i, hi_i          # feasible(low), not feasible(high)\\n            while high - low > 1:\\n                mid = (low + high) // 2\\n                if feasible(Decimal(mid)):\\n                    low = mid\\n                else:\\n                    high = mid\\n            candidate = low\\n\\n        # Verify forward, and verify that the next yen fails. Rounding to whole\\n        # cents can make the cost flat across a yen or two, so \\"the next yen\\n        # fails\\" is established by search rather than assumed from the algebra.\\n        if not feasible(Decimal(candidate)):  # pragma: no cover - defensive\\n            continue\\n        if candidate < hi_i and feasible(Decimal(candidate + 1)):  # pragma: no cover\\n            continue\\n        if best is None or candidate > best:\\n            best = candidate\\n\\n    if best is None:\\n        return None\\n    return Money(Decimal(best), Currency.JPY)\\n\\n\\ndef compute_arbitrage(\\n    *,\\n    purchase_jpy: Money,\\n    gross_resale_eur: Money,\\n    on: date,\\n    assumptions: CostAssumptions,\\n    policy: PolicyStore,\\n    fx_rates: Mapping[tuple[Currency, Currency], FxRate],\\n    required_roi: Decimal = Decimal(\\"0.40\\"),\\n    strong_buy_roi: Decimal = Decimal(\\"0.80\\"),\\n    target_roi: Decimal = Decimal(\\"0.60\\"),\\n) -> ArbitrageResult:\\n    \\"\\"\\"Full arbitrage assessment for one card at one Japanese price.\\"\\"\\"\\n    econ = compute_economics(\\n        purchase_jpy=purchase_jpy,\\n        gross_resale_eur=gross_resale_eur,\\n        on=on,\\n        assumptions=assumptions,\\n        policy=policy,\\n        fx_rates=fx_rates,\\n    )\\n    landed = econ.landed\\n    cost = landed.total_eur.amount\\n    gross_multiple = (gross_resale_eur.amount / cost) if cost > 0 else Decimal(\\"0\\")\\n    net_multiple = (econ.net_proceeds_eur.amount / cost) if cost > 0 else Decimal(\\"0\\")\\n\\n    a = assumptions\\n    fee_rate = a.marketplace_fee_rate + a.payment_fee_rate\\n    loss = Decimal(\\"1\\") - a.expected_loss_rate\\n    denom = (Decimal(\\"1\\") - fee_rate) * loss\\n    break_even = (\\n        (cost / loss + a.payment_fee_fixed_eur + a.outbound_shipping_eur)\\n        / (Decimal(\\"1\\") - fee_rate)\\n        if denom > 0\\n        else Decimal(\\"0\\")\\n    )\\n\\n    kw = dict(\\n        gross_resale_eur=gross_resale_eur, on=on, assumptions=assumptions,\\n        policy=policy, fx_rates=fx_rates,\\n    )\\n    dkk_rate = fx_rates.get((Currency.EUR, Currency.DKK))\\n\\n    # An unresolved landed cost must not produce purchase limits that look\\n    # actionable. The cost is understated, so any limit derived from it is too\\n    # generous in exactly the direction that loses money.\\n    if landed.unresolved:\\n        max_buy = strong_buy = target_buy = None\\n    else:\\n        max_buy = max_buy_price(required_roi=required_roi, **kw)\\n        strong_buy = max_buy_price(required_roi=strong_buy_roi, **kw)\\n        target_buy = max_buy_price(required_roi=target_roi, **kw)\\n\\n    return ArbitrageResult(\\n        scenario=a.scenario,\\n        landed=landed,\\n        gross_resale_eur=gross_resale_eur,\\n        net_proceeds_eur=econ.net_proceeds_eur,\\n        expected_profit_eur=econ.profit_eur,\\n        expected_profit_dkk=(\\n            Money(econ.profit_eur.amount * dkk_rate.rate, Currency.DKK).quantize()\\n            if dkk_rate else None\\n        ),\\n        roi=econ.roi,\\n        capital_deployed_eur=econ.capital_deployed_eur,\\n        capital_basis=econ.capital_basis,\\n        gross_multiple=gross_multiple,\\n        net_multiple=net_multiple,\\n        break_even_resale_eur=Money(break_even, Currency.EUR).quantize(),\\n        max_buy_jpy=max_buy,\\n        strong_buy_jpy=strong_buy,\\n        target_buy_jpy=target_buy,\\n        do_not_buy_above_jpy=max_buy,\\n        notes=landed.notes,\\n        unresolved=landed.unresolved,\\n    )\\n", "pokearb_core/arbitrage/policy.py": "\\"\\"\\"Dated policy parameters.\\n\\nThe brief says not to permanently hardcode legal thresholds. So none of them\\nare constants in code. Every tax rate, duty threshold and handling fee is a\\n``PolicyParameter`` row with a validity window and the URL it was verified\\nfrom, and the engine resolves them for the date of the transaction.\\n\\nTwo practical benefits beyond compliance:\\n\\n* A backtest run over 2024 data automatically uses 2024\'s rules.\\n* Rule changes are a data edit with an audit trail, not a code deploy.\\n\\nThe seed values in ``seed/policy.yaml`` carry their source URLs. Anything not\\nverified is seeded with ``requires_verification: true`` and the engine refuses\\nto produce a landed cost that depends on it.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import dataclass\\nfrom datetime import date\\nfrom decimal import Decimal\\nfrom typing import Iterable, Optional, Sequence\\n\\n__all__ = [\\"PolicyParameter\\", \\"PolicyStore\\", \\"PolicyUnverifiedError\\"]\\n\\n\\nclass PolicyUnverifiedError(RuntimeError):\\n    \\"\\"\\"Raised when a calculation depends on an unverified policy value.\\n\\n    Deliberately an exception rather than a fallback. A landed cost computed\\n    on a guessed duty rate is exactly the false signal the brief forbids.\\n    \\"\\"\\"\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass PolicyParameter:\\n    key: str\\n    value: Decimal\\n    unit: str  # \\"rate\\" | \\"EUR\\" | \\"DKK\\" | \\"JPY\\" | \\"count\\"\\n    valid_from: date\\n    valid_to: Optional[date] = None\\n    source_url: Optional[str] = None\\n    requires_verification: bool = False\\n    note: Optional[str] = None\\n\\n    def covers(self, on: date) -> bool:\\n        if on < self.valid_from:\\n            return False\\n        if self.valid_to is not None and on > self.valid_to:\\n            return False\\n        return True\\n\\n\\nclass PolicyStore:\\n    \\"\\"\\"Resolve policy values as of a date.\\"\\"\\"\\n\\n    def __init__(self, parameters: Optional[Sequence[PolicyParameter]] = None) -> None:\\n        self._params: list[PolicyParameter] = list(parameters or ())\\n\\n    def add(self, parameter: PolicyParameter) -> None:\\n        self._params.append(parameter)\\n\\n    def extend(self, parameters: Iterable[PolicyParameter]) -> None:\\n        self._params.extend(parameters)\\n\\n    def resolve(self, key: str, on: date) -> PolicyParameter:\\n        matches = [p for p in self._params if p.key == key and p.covers(on)]\\n        if not matches:\\n            raise KeyError(\\n                f\\"No policy parameter \'{key}\' valid on {on.isoformat()}. \\"\\n                \\"Refusing to substitute a default.\\"\\n            )\\n        if len(matches) > 1:\\n            # Most recently effective wins; overlapping rows are a data bug\\n            # worth surfacing in the note.\\n            matches.sort(key=lambda p: p.valid_from, reverse=True)\\n        chosen = matches[0]\\n        if chosen.requires_verification:\\n            raise PolicyUnverifiedError(\\n                f\\"Policy \'{key}\' is seeded but not verified\\"\\n                + (f\\" ({chosen.note})\\" if chosen.note else \\"\\")\\n                + \\". Verify it and clear requires_verification before relying on \\"\\n                \\"any landed cost that uses it.\\"\\n            )\\n        return chosen\\n\\n    def value(self, key: str, on: date) -> Decimal:\\n        return self.resolve(key, on).value\\n\\n    def try_value(self, key: str, on: date) -> Optional[Decimal]:\\n        \\"\\"\\"Resolve without raising. Returns ``None`` when unavailable.\\"\\"\\"\\n        try:\\n            return self.value(key, on)\\n        except (KeyError, PolicyUnverifiedError):\\n            return None\\n\\n    def sources(self, keys: Iterable[str], on: date) -> dict[str, Optional[str]]:\\n        out: dict[str, Optional[str]] = {}\\n        for key in keys:\\n            try:\\n                out[key] = self.resolve(key, on).source_url\\n            except (KeyError, PolicyUnverifiedError):\\n                out[key] = None\\n        return out\\n", "pokearb_core/arbitrage/reference_policy.py": "\\"\\"\\"The seeded policy parameters, as Python, for tools that run without a database.\\n\\n``seed/policy.sql`` is the production source of truth. This module mirrors it\\nso a command-line price check can run with nothing but network access. A test\\n(``tests/test_market_average.py::test_reference_policy_matches_the_seed``)\\nparses the SQL and fails if the two ever drift apart, so this copy cannot\\nquietly go stale.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import date\\nfrom decimal import Decimal\\n\\nfrom .policy import PolicyParameter, PolicyStore\\n\\nSKAT = \\"https://skat.dk/skole/onlineshopping/naar-du-koeber\\"\\nJG = \\"https://www.japan-guide.com/news/tax-free-shopping.html\\"\\n\\nROWS: tuple[PolicyParameter, ...] = (\\n    PolicyParameter(\\"dk.import_vat_rate\\", Decimal(\\"0.25\\"), \\"rate\\", date(2021, 7, 1), None, SKAT),\\n    PolicyParameter(\\"dk.duty_threshold_eur\\", Decimal(\\"150\\"), \\"EUR\\", date(2021, 7, 1), None, SKAT),\\n    PolicyParameter(\\"dk.low_value_per_item_charge_eur\\", Decimal(\\"3\\"), \\"EUR\\", date(2026, 7, 1), None, SKAT),\\n    PolicyParameter(\\"dk.carrier_handling_fee_dkk\\", Decimal(\\"200\\"), \\"DKK\\", date(2021, 7, 1), None, SKAT),\\n    PolicyParameter(\\"dk.traveller_allowance_air_dkk\\", Decimal(\\"3250\\"), \\"DKK\\", date(2021, 7, 1), None, SKAT),\\n    PolicyParameter(\\"dk.traveller_allowance_other_dkk\\", Decimal(\\"2230\\"), \\"DKK\\", date(2021, 7, 1), None, SKAT),\\n    PolicyParameter(\\"jp.consumption_tax_rate\\", Decimal(\\"0.10\\"), \\"rate\\", date(2019, 10, 1), None, JG),\\n    PolicyParameter(\\"jp.tax_free_minimum_jpy\\", Decimal(\\"5000\\"), \\"JPY\\", date(2019, 10, 1), None, JG),\\n    PolicyParameter(\\"jp.tax_free_refund_at_departure_from\\", Decimal(\\"0\\"), \\"count\\",\\n                    date(2019, 10, 1), date(2026, 10, 31), JG),\\n    PolicyParameter(\\"jp.tax_free_refund_at_departure_from\\", Decimal(\\"1\\"), \\"count\\",\\n                    date(2026, 11, 1), None, JG),\\n    PolicyParameter(\\"jp.tax_free_purchase_window_days\\", Decimal(\\"90\\"), \\"count\\",\\n                    date(2026, 11, 1), None, JG),\\n    PolicyParameter(\\"dk.duty_rate_trading_cards\\", Decimal(\\"0\\"), \\"rate\\", date(2021, 7, 1), None,\\n                    None, requires_verification=True,\\n                    note=\\"Commodity code for collectible trading cards not classified\\"),\\n)\\n\\n\\ndef reference_policy() -> PolicyStore:\\n    return PolicyStore(list(ROWS))\\n", "pokearb_core/condition/__init__.py": "\\"\\"\\"PokeArb core subpackage.\\"\\"\\"\\n", "pokearb_core/condition/model.py": "\\"\\"\\"Probabilistic condition normalisation.\\n\\nThe brief is explicit that \\"Card Rush B equals Cardmarket EX\\" is unacceptable,\\nand it is right: a Japanese shop grade is a different measurement instrument\\nwith a different operator, and the honest translation is a distribution.\\n\\nModel\\n-----\\nEach ``(source_id, source_grade_label)`` pair owns a Dirichlet over the\\nEuropean ladder. Starting parameters are weakly informative and flagged\\n``provisional`` with ``evidence_n = 0``. Provisional priors are usable, but\\nthey carry low condition confidence, and that confidence propagates all the way\\ninto the opportunity score. A provisional mapping therefore cannot on its own\\nproduce a strong buy signal, which is the behaviour the brief asks for.\\n\\nPer-listing evidence (photo defects, description keywords) shifts the prior to\\na posterior for that one listing. Two cards with the same shop grade can and\\nshould end up with different distributions.\\n\\nCalibration: ``update_prior`` folds observed outcomes back into the Dirichlet,\\nso the mapping improves as resale results come in.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport math\\nfrom dataclasses import dataclass, replace\\nfrom decimal import Decimal\\nfrom typing import Mapping, MutableMapping, Optional, Sequence\\n\\nfrom ..types import EU_CONDITION_LADDER, ConditionDistribution, EuCondition, Money\\n\\n__all__ = [\\n    \\"DirichletPrior\\",\\n    \\"ConditionEvidence\\",\\n    \\"PriorStore\\",\\n    \\"posterior\\",\\n    \\"condition_confidence\\",\\n    \\"expected_value\\",\\n    \\"WEAK_PRIOR_STRENGTH\\",\\n]\\n\\n#: Total pseudo-count for a provisional prior. Deliberately small so that a\\n#: handful of real observations dominates it quickly.\\nWEAK_PRIOR_STRENGTH = Decimal(\\"3\\")\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass DirichletPrior:\\n    \\"\\"\\"Dirichlet parameters over the European condition ladder.\\"\\"\\"\\n\\n    source_id: str\\n    source_grade_label: str\\n    alpha: Mapping[EuCondition, Decimal]\\n    evidence_n: int = 0\\n    is_provisional: bool = True\\n    note: Optional[str] = None\\n\\n    def __post_init__(self) -> None:\\n        missing = set(EU_CONDITION_LADDER) - set(self.alpha)\\n        if missing:\\n            raise ValueError(f\\"Dirichlet prior is missing conditions: {sorted(m.value for m in missing)}\\")\\n        if any(v <= 0 for v in self.alpha.values()):\\n            raise ValueError(\\"Dirichlet parameters must be strictly positive.\\")\\n\\n    @property\\n    def concentration(self) -> Decimal:\\n        return Decimal(sum(self.alpha.values()))\\n\\n    def mean(self) -> dict[EuCondition, Decimal]:\\n        total = self.concentration\\n        return {c: self.alpha[c] / total for c in EU_CONDITION_LADDER}\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ConditionEvidence:\\n    \\"\\"\\"Listing-specific evidence that shifts the prior.\\n\\n    ``defect_weights`` maps a named visible defect to a severity in ``0..1``.\\n    Severity is a judgement, so it is recorded with its origin and never\\n    presented as a measurement.\\n    \\"\\"\\"\\n\\n    defect_weights: Mapping[str, Decimal] = None  # type: ignore[assignment]\\n    has_photos: bool = False\\n    photo_count: int = 0\\n    seller_reliability: Optional[Decimal] = None  # 0..1\\n    description_flags: tuple[str, ...] = ()\\n    origin: str = \\"unspecified\\"\\n\\n    def __post_init__(self) -> None:\\n        if self.defect_weights is None:\\n            object.__setattr__(self, \\"defect_weights\\", {})\\n\\n    @property\\n    def severity(self) -> Decimal:\\n        \\"\\"\\"Aggregate visible wear severity in ``0..1``.\\"\\"\\"\\n        if not self.defect_weights:\\n            return Decimal(\\"0\\")\\n        total = sum(self.defect_weights.values())\\n        return min(Decimal(\\"1\\"), Decimal(total))\\n\\n    @property\\n    def strength(self) -> Decimal:\\n        \\"\\"\\"How much this evidence is worth, as a pseudo-count.\\n\\n        No photos means no evidence. Photos without visible defects are weak\\n        positive evidence, not proof of mint condition.\\n        \\"\\"\\"\\n        if not self.has_photos:\\n            return Decimal(\\"0\\")\\n        base = Decimal(min(self.photo_count, 4))\\n        if self.seller_reliability is not None:\\n            base *= Decimal(\\"0.5\\") + Decimal(\\"0.5\\") * self.seller_reliability\\n        return base\\n\\n\\nclass PriorStore:\\n    \\"\\"\\"In-memory prior lookup. The DB-backed implementation shares this API.\\"\\"\\"\\n\\n    def __init__(self, priors: Optional[Sequence[DirichletPrior]] = None) -> None:\\n        self._priors: MutableMapping[tuple[str, str], DirichletPrior] = {}\\n        for prior in priors or ():\\n            self.put(prior)\\n\\n    @staticmethod\\n    def _key(source_id: str, label: str) -> tuple[str, str]:\\n        return (source_id.strip().lower(), label.strip().lower())\\n\\n    def put(self, prior: DirichletPrior) -> None:\\n        self._priors[self._key(prior.source_id, prior.source_grade_label)] = prior\\n\\n    def get(self, source_id: str, label: str) -> Optional[DirichletPrior]:\\n        return self._priors.get(self._key(source_id, label))\\n\\n    def update_prior(\\n        self,\\n        source_id: str,\\n        label: str,\\n        observed: EuCondition,\\n        weight: Decimal = Decimal(\\"1\\"),\\n    ) -> DirichletPrior:\\n        \\"\\"\\"Fold a confirmed outcome back into the prior.\\n\\n        Called by the calibration job once a card bought under a shop grade is\\n        actually assessed against the European ladder.\\n        \\"\\"\\"\\n        prior = self.get(source_id, label)\\n        if prior is None:\\n            raise KeyError(f\\"No prior for ({source_id}, {label}); create one explicitly.\\")\\n        alpha = dict(prior.alpha)\\n        alpha[observed] = alpha[observed] + weight\\n        updated = replace(\\n            prior,\\n            alpha=alpha,\\n            evidence_n=prior.evidence_n + 1,\\n            is_provisional=prior.evidence_n + 1 < 20,\\n        )\\n        self.put(updated)\\n        return updated\\n\\n\\ndef _shift_toward_worse(\\n    probabilities: Mapping[EuCondition, Decimal], severity: Decimal\\n) -> dict[EuCondition, Decimal]:\\n    \\"\\"\\"Move probability mass down the ladder in proportion to visible wear.\\n\\n    Mass only ever moves toward worse conditions. Evidence of damage can lower\\n    the estimate; absence of visible damage never raises it above the prior,\\n    because a photo cannot prove the absence of a defect.\\n    \\"\\"\\"\\n    if severity <= 0:\\n        return dict(probabilities)\\n    ladder = EU_CONDITION_LADDER\\n    out = {c: Decimal(\\"0\\") for c in ladder}\\n    for idx, cond in enumerate(ladder):\\n        mass = probabilities[cond]\\n        if idx == len(ladder) - 1:\\n            out[cond] += mass\\n            continue\\n        moved = mass * severity\\n        out[cond] += mass - moved\\n        out[ladder[idx + 1]] += moved\\n    return out\\n\\n\\ndef posterior(\\n    prior: DirichletPrior,\\n    evidence: Optional[ConditionEvidence] = None,\\n) -> ConditionDistribution:\\n    \\"\\"\\"Combine a prior with listing-specific evidence.\\"\\"\\"\\n    probs = prior.mean()\\n    notes: list[str] = []\\n\\n    if prior.is_provisional:\\n        notes.append(\\n            f\\"prior for \'{prior.source_grade_label}\' at {prior.source_id} is provisional \\"\\n            f\\"(evidence_n={prior.evidence_n}); condition confidence reduced accordingly\\"\\n        )\\n\\n    if evidence is not None and evidence.strength > 0:\\n        probs = _shift_toward_worse(probs, evidence.severity)\\n        if evidence.defect_weights:\\n            defects = \\", \\".join(sorted(evidence.defect_weights))\\n            notes.append(f\\"visible defects shifted mass toward lower grades: {defects}\\")\\n        else:\\n            notes.append(\\"photos present, no visible defects recorded\\")\\n    elif evidence is not None:\\n        notes.append(\\"no usable photo evidence; prior used unchanged\\")\\n\\n    total = sum(probs.values())\\n    probs = {c: (v / total) for c, v in probs.items()}\\n    # Absorb rounding drift into the modal bucket so the sum is exactly 1.\\n    drift = Decimal(\\"1\\") - sum(probs.values())\\n    if drift != 0:\\n        modal = max(probs, key=lambda c: probs[c])\\n        probs[modal] += drift\\n\\n    return ConditionDistribution(\\n        probabilities=probs,\\n        evidence_n=prior.evidence_n,\\n        is_provisional=prior.is_provisional,\\n        source_grade_label=prior.source_grade_label,\\n        source_id=prior.source_id,\\n        notes=tuple(notes),\\n    )\\n\\n\\ndef condition_confidence(dist: ConditionDistribution) -> Decimal:\\n    \\"\\"\\"Confidence in ``0..1``: sharpness of the distribution, discounted for provisionality.\\"\\"\\"\\n    values = [float(v) for v in dist.probabilities.values() if v > 0]\\n    if not values:\\n        return Decimal(\\"0\\")\\n    entropy = -sum(p * math.log(p) for p in values)\\n    max_entropy = math.log(len(EU_CONDITION_LADDER))\\n    sharpness = 1.0 - (entropy / max_entropy if max_entropy else 0.0)\\n\\n    # Evidence discount: a sharp distribution built on nothing is not\\n    # confident. Uncalibrated mappings are discounted but not crushed, because\\n    # the inherent spread of a shop grade is already reflected in the sharpness\\n    # term and should not be charged for twice.\\n    evidence_factor = min(1.0, 0.5 + 0.5 * (dist.evidence_n / 20.0))\\n    if dist.is_provisional:\\n        evidence_factor = min(evidence_factor, 0.75)\\n\\n    return Decimal(str(round(max(0.0, sharpness) * evidence_factor, 4)))\\n\\n\\ndef expected_value(\\n    dist: ConditionDistribution,\\n    value_by_condition: Mapping[EuCondition, Optional[Money]],\\n) -> Optional[Money]:\\n    \\"\\"\\"Probability-weighted resale value across the condition ladder.\\n\\n    Returns ``None`` if any condition carrying meaningful probability has no\\n    value estimate. Substituting the NM value for a missing LP value is exactly\\n    the optimistic shortcut the brief forbids.\\n    \\"\\"\\"\\n    currency = None\\n    total = Decimal(\\"0\\")\\n    covered = Decimal(\\"0\\")\\n\\n    for cond, prob in dist.probabilities.items():\\n        if prob <= Decimal(\\"0.001\\"):\\n            continue\\n        money = value_by_condition.get(cond)\\n        if money is None:\\n            return None\\n        if currency is None:\\n            currency = money.currency\\n        elif currency is not money.currency:\\n            raise ValueError(\\"All condition values must share one currency.\\")\\n        total += prob * money.amount\\n        covered += prob\\n\\n    if currency is None or covered < Decimal(\\"0.9\\"):\\n        return None\\n    return Money(total / covered, currency)\\n", "pokearb_core/db/__init__.py": "\\"\\"\\"PokeArb core subpackage.\\"\\"\\"\\n", "pokearb_core/identity/__init__.py": "\\"\\"\\"PokeArb core subpackage.\\"\\"\\"\\n", "pokearb_core/identity/canonical.py": "\\"\\"\\"Canonical identity key.\\n\\nThe canonical key is the contract that makes \\"same card\\" a decidable question.\\nTwo printings are the same tradeable unit if and only if their canonical keys\\nare equal. Everything that distinguishes value must therefore appear in the key.\\n\\nThe key deliberately includes ``printing``, ``edition`` and ``stamp``, which is\\nwhat keeps a holo apart from a reverse holo, a 1st Edition apart from an\\nUnlimited, and a Pokemon Center stamped promo apart from the plain printing.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport re\\nimport unicodedata\\nfrom typing import TYPE_CHECKING\\n\\nif TYPE_CHECKING:  # pragma: no cover\\n    from ..types import CardVariant\\n\\n__all__ = [\\n    \\"normalize_set_code\\",\\n    \\"normalize_number\\",\\n    \\"normalize_name\\",\\n    \\"build_canonical_key\\",\\n    \\"SET_CODE_ALIASES\\",\\n]\\n\\n\\n#: Set-code aliases seen in the wild, normalised to the internal code.\\n#: Keys are already upper-cased and stripped of separators.\\nSET_CODE_ALIASES: dict[str, str] = {\\n    \\"SMP\\": \\"SM-P\\",\\n    \\"SMPROMO\\": \\"SM-P\\",\\n    \\"XYP\\": \\"XY-P\\",\\n    \\"XYPROMO\\": \\"XY-P\\",\\n    \\"SP\\": \\"S-P\\",\\n    \\"SWSHP\\": \\"S-P\\",\\n    \\"SVP\\": \\"SV-P\\",\\n    \\"SVPROMO\\": \\"SV-P\\",\\n    \\"BWP\\": \\"BW-P\\",\\n    \\"BWPROMO\\": \\"BW-P\\",\\n    \\"DPP\\": \\"DP-P\\",\\n    \\"PROMO\\": \\"PROMO\\",\\n}\\n\\n_SEPARATORS = re.compile(r\\"[\\\\s\\\\u3000_/\\\\\\\\.\\\\-\\\\u2013\\\\u2014]+\\")\\n_NON_ALNUM = re.compile(r\\"[^0-9A-Za-z]+\\")\\n\\n\\ndef _strip(value: str) -> str:\\n    \\"\\"\\"Unicode-normalise, fold full-width characters, upper-case.\\"\\"\\"\\n    folded = unicodedata.normalize(\\"NFKC\\", value).strip()\\n    return folded.upper()\\n\\n\\ndef normalize_set_code(raw: str | None) -> str | None:\\n    \\"\\"\\"Normalise a set or promo-series code.\\n\\n    Handles the common shapes: ``sm-p``, ``SM P``, ``SMP``, ``ＳＭ－Ｐ``.\\n    Returns ``None`` for empty input rather than an empty string, so that\\n    \\"unknown set\\" stays distinguishable from \\"set is blank\\".\\n    \\"\\"\\"\\n    if raw is None:\\n        return None\\n    folded = _strip(raw)\\n    if not folded:\\n        return None\\n    compact = _NON_ALNUM.sub(\\"\\", folded)\\n    if compact in SET_CODE_ALIASES:\\n        return SET_CODE_ALIASES[compact]\\n    # Insert the canonical hyphen for the \\"<series><P>\\" promo shape.\\n    m = re.fullmatch(r\\"([A-Z]{1,4})P\\", compact)\\n    if m:\\n        return f\\"{m.group(1)}-P\\"\\n    return _SEPARATORS.sub(\\"-\\", folded)\\n\\n\\ndef normalize_number(raw: str | None) -> str | None:\\n    \\"\\"\\"Normalise a printed card number.\\n\\n    ``114/SM-P``, ``114`` and ``０１１４`` all normalise to ``114``. Leading\\n    zeros are stripped because they are a printing convention, not a\\n    discriminator. Suffix letters (``025a``) are preserved because they are.\\n    \\"\\"\\"\\n    if raw is None:\\n        return None\\n    folded = _strip(raw)\\n    if not folded:\\n        return None\\n    # Drop a trailing \\"/DENOMINATOR\\" or \\"/SET-CODE\\" fragment.\\n    folded = folded.split(\\"/\\")[0].strip()\\n    m = re.fullmatch(r\\"0*(\\\\d+)\\\\s*([A-Z]?)\\", folded)\\n    if m:\\n        return f\\"{m.group(1)}{m.group(2)}\\"\\n    return _NON_ALNUM.sub(\\"\\", folded) or None\\n\\n\\ndef normalize_name(raw: str | None) -> str | None:\\n    \\"\\"\\"Normalise a card or Pokemon name for comparison only.\\n\\n    Never used as a discriminator on its own: names are the weakest signal in\\n    the whole system because of cross-language aliasing.\\n    \\"\\"\\"\\n    if raw is None:\\n        return None\\n    folded = unicodedata.normalize(\\"NFKC\\", raw).strip().casefold()\\n    folded = _SEPARATORS.sub(\\" \\", folded)\\n    return folded or None\\n\\n\\ndef build_canonical_key(variant: \\"CardVariant\\") -> str:\\n    \\"\\"\\"Deterministic identity string for a printing.\\n\\n    Field order is fixed and the separator is reserved, so the key is stable\\n    across releases and safe to use as a database unique constraint.\\n    \\"\\"\\"\\n    parts = [\\n        variant.language.value,\\n        normalize_set_code(variant.set_code) or \\"?\\",\\n        normalize_number(variant.number) or \\"?\\",\\n        variant.printing.value,\\n        variant.edition.value,\\n        (normalize_name(variant.stamp) or \\"none\\").replace(\\" \\", \\"-\\"),\\n        variant.artwork_id or \\"a0\\",\\n    ]\\n    return \\"|\\".join(parts)\\n", "pokearb_core/identity/matcher.py": "\\"\\"\\"Card identity matching.\\n\\nThree stages, in this order:\\n\\n1. **Hard gates.** A known-versus-known mismatch on any discriminator rejects\\n   the pair outright. Rejection is final; no score can rescue it.\\n2. **Weighted score** over the evidence that is present.\\n3. **Ambiguity penalty.** If sibling variants are *equally* consistent with the\\n   evidence, confidence is capped below the automatic threshold. This is the\\n   mechanism that turns \\"Pikachu 114/SM-P, holo or reverse unstated\\" into a\\n   manual review instead of a coin flip dressed up as 0.99.\\n\\nThe thresholds from the brief:\\n\\n=================  ===========================\\nconfidence          outcome\\n=================  ===========================\\n>= 0.98             automatic match\\n0.90 .. 0.98        manual review recommended\\n< 0.90              no match\\n=================  ===========================\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport difflib\\nfrom dataclasses import dataclass, field\\nfrom decimal import Decimal\\nfrom enum import Enum\\nfrom typing import Iterable, Mapping, Optional, Sequence\\n\\nfrom ..types import CardVariant, Edition, Language, Printing\\nfrom .canonical import normalize_name, normalize_number, normalize_set_code\\n\\n__all__ = [\\n    \\"MatchOutcome\\",\\n    \\"MatchCandidate\\",\\n    \\"MatchResult\\",\\n    \\"ObservedCard\\",\\n    \\"AliasIndex\\",\\n    \\"match_card\\",\\n    \\"AUTO_MATCH_THRESHOLD\\",\\n    \\"REVIEW_THRESHOLD\\",\\n]\\n\\nAUTO_MATCH_THRESHOLD = Decimal(\\"0.98\\")\\nREVIEW_THRESHOLD = Decimal(\\"0.90\\")\\n\\n#: Confidence ceiling applied when sibling variants remain equally plausible.\\n#: Deliberately one step below the review threshold\'s upper bound so that an\\n#: ambiguous pair can never be auto-matched.\\nAMBIGUITY_CEILING = Decimal(\\"0.94\\")\\n\\n_WEIGHTS: Mapping[str, Decimal] = {\\n    \\"number\\": Decimal(\\"0.30\\"),\\n    \\"set\\": Decimal(\\"0.25\\"),\\n    \\"name\\": Decimal(\\"0.20\\"),\\n    \\"variant_attrs\\": Decimal(\\"0.15\\"),\\n    \\"provenance\\": Decimal(\\"0.10\\"),\\n}\\n\\n#: Printings that are visually and economically distinct. A listing that does\\n#: not disambiguate between two of these cannot be auto-matched.\\n_CONFUSABLE_PRINTINGS = frozenset({Printing.HOLO, Printing.REVERSE_HOLO, Printing.NON_HOLO})\\n\\n\\nclass MatchOutcome(str, Enum):\\n    AUTO = \\"auto_match\\"\\n    REVIEW = \\"manual_review\\"\\n    REJECT = \\"no_match\\"\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ObservedCard:\\n    \\"\\"\\"What a source actually told us. Every field may be unknown.\\"\\"\\"\\n\\n    raw_title: str\\n    language: Optional[Language] = None\\n    set_code: Optional[str] = None\\n    number: Optional[str] = None\\n    printing: Optional[Printing] = None\\n    edition: Optional[Edition] = None\\n    stamp: Optional[str] = None\\n    name: Optional[str] = None\\n    year: Optional[int] = None\\n    illustrator: Optional[str] = None\\n    source_id: Optional[str] = None\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass MatchCandidate:\\n    variant: CardVariant\\n    confidence: Decimal\\n    components: Mapping[str, Decimal]\\n    gate_failures: tuple[str, ...]\\n    penalties: tuple[str, ...]\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass MatchResult:\\n    outcome: MatchOutcome\\n    best: Optional[MatchCandidate]\\n    considered: tuple[MatchCandidate, ...]\\n    rejected: tuple[MatchCandidate, ...]\\n    explanation: tuple[str, ...] = ()\\n\\n    @property\\n    def variant_id(self) -> Optional[str]:\\n        if self.outcome is MatchOutcome.AUTO and self.best is not None:\\n            return self.best.variant.variant_id\\n        return None\\n\\n\\nclass AliasIndex:\\n    \\"\\"\\"Cross-language alias lookup.\\n\\n    Aliases resolve names only. They are never permitted to override a\\n    discriminator: ブラッキー and Umbreon may be the same Pokemon, but that\\n    tells you nothing about which of its twenty printings you are holding.\\n    \\"\\"\\"\\n\\n    def __init__(self, aliases: Optional[Mapping[str, Iterable[str]]] = None) -> None:\\n        self._by_alias: dict[str, str] = {}\\n        for canonical, variants in (aliases or {}).items():\\n            key = normalize_name(canonical)\\n            if key:\\n                self._by_alias[key] = key\\n            for alias in variants:\\n                alias_key = normalize_name(alias)\\n                if alias_key and key:\\n                    self._by_alias[alias_key] = key\\n\\n    def resolve(self, name: Optional[str]) -> Optional[str]:\\n        key = normalize_name(name)\\n        if key is None:\\n            return None\\n        return self._by_alias.get(key, key)\\n\\n    def same_pokemon(self, a: Optional[str], b: Optional[str]) -> Optional[bool]:\\n        ra, rb = self.resolve(a), self.resolve(b)\\n        if ra is None or rb is None:\\n            return None\\n        return ra == rb\\n\\n\\ndef _gate_failures(obs: ObservedCard, variant: CardVariant) -> tuple[str, ...]:\\n    \\"\\"\\"Known-versus-known mismatches. Any hit is an unconditional rejection.\\"\\"\\"\\n    failures: list[str] = []\\n\\n    obs_num = normalize_number(obs.number)\\n    var_num = normalize_number(variant.number)\\n    if obs_num is not None and var_num is not None and obs_num != var_num:\\n        failures.append(f\\"card number differs ({obs_num} vs {var_num})\\")\\n\\n    obs_set = normalize_set_code(obs.set_code)\\n    var_set = normalize_set_code(variant.set_code)\\n    if obs_set is not None and var_set is not None and obs_set != var_set:\\n        failures.append(f\\"set differs ({obs_set} vs {var_set})\\")\\n\\n    if obs.language is not None and obs.language is not variant.language:\\n        failures.append(\\n            f\\"language differs ({obs.language.value} vs {variant.language.value})\\"\\n        )\\n\\n    if obs.printing is not None and obs.printing is not variant.printing:\\n        failures.append(\\n            f\\"printing differs ({obs.printing.value} vs {variant.printing.value})\\"\\n        )\\n\\n    if (\\n        obs.edition is not None\\n        and obs.edition is not Edition.NOT_APPLICABLE\\n        and variant.edition is not Edition.NOT_APPLICABLE\\n        and obs.edition is not variant.edition\\n    ):\\n        failures.append(f\\"edition differs ({obs.edition.value} vs {variant.edition.value})\\")\\n\\n    obs_stamp = normalize_name(obs.stamp)\\n    var_stamp = normalize_name(variant.stamp)\\n    if obs_stamp is not None and var_stamp is not None and obs_stamp != var_stamp:\\n        failures.append(f\\"stamp differs ({obs_stamp} vs {var_stamp})\\")\\n    # A stamped variant matched against an explicitly unstamped observation is\\n    # also a mismatch, and vice versa. Treat the absent side as \\"none\\" only\\n    # when the observation positively asserts it.\\n    if obs_stamp == \\"none\\" and var_stamp not in (None, \\"none\\"):\\n        failures.append(f\\"observation states no stamp but variant has \'{var_stamp}\'\\")\\n\\n    return tuple(failures)\\n\\n\\ndef _name_score(obs: ObservedCard, variant: CardVariant, aliases: AliasIndex) -> Decimal:\\n    obs_name = obs.name or obs.raw_title\\n    candidates = [variant.name_en, variant.name_ja, variant.pokemon_slug]\\n    best = Decimal(\\"0\\")\\n    for candidate in candidates:\\n        if not candidate:\\n            continue\\n        same = aliases.same_pokemon(obs_name, candidate)\\n        if same:\\n            return Decimal(\\"1.0\\")\\n        a, b = normalize_name(obs_name), normalize_name(candidate)\\n        if not a or not b:\\n            continue\\n        if b in a or a in b:\\n            best = max(best, Decimal(\\"0.9\\"))\\n            continue\\n        ratio = Decimal(str(round(difflib.SequenceMatcher(None, a, b).ratio(), 4)))\\n        best = max(best, ratio)\\n    return best\\n\\n\\ndef _variant_attr_score(obs: ObservedCard, variant: CardVariant) -> tuple[Decimal, int]:\\n    \\"\\"\\"Agreement across variant discriminators, plus a count of relevant unknowns.\\n\\n    A discriminator only counts as an unknown when it is *relevant* to this\\n    variant. Edition is irrelevant for a promo that has no editions, and stamp\\n    is irrelevant for a printing that carries no stamp, so silence about them\\n    is not a risk. Silence about a discriminator the variant actually carries\\n    is a real risk and is counted.\\n\\n    Known-but-unconfirmed scores zero rather than a neutral half. Silence is\\n    never treated as agreement.\\n    \\"\\"\\"\\n    checks: list[Optional[bool]] = []\\n    relevant_unknown = 0\\n\\n    # Printing is always a discriminator: holo, reverse and non-holo trade apart.\\n    if obs.printing is None:\\n        relevant_unknown += 1\\n    else:\\n        checks.append(obs.printing is variant.printing)\\n\\n    # Edition only discriminates where the variant actually has one.\\n    if variant.edition is not Edition.NOT_APPLICABLE:\\n        if obs.edition is None:\\n            relevant_unknown += 1\\n        else:\\n            checks.append(obs.edition is variant.edition)\\n\\n    # Stamp only discriminates where the variant actually carries one.\\n    if variant.stamp is not None:\\n        if obs.stamp is None:\\n            relevant_unknown += 1\\n        else:\\n            checks.append(normalize_name(obs.stamp) == normalize_name(variant.stamp))\\n    elif obs.stamp is not None:\\n        checks.append(normalize_name(obs.stamp) == \\"none\\")\\n\\n    if not checks:\\n        return Decimal(\\"0\\"), relevant_unknown\\n    agreed = sum(1 for c in checks if c)\\n    return Decimal(agreed) / Decimal(len(checks)), relevant_unknown\\n\\n\\ndef _provenance_score(obs: ObservedCard, variant: CardVariant) -> Optional[Decimal]:\\n    \\"\\"\\"Year and illustrator agreement, or ``None`` when not evaluable.\\n\\n    Provenance is a *confirmation* signal, not a required one. Japanese shop\\n    listings almost never state the illustrator, so treating its absence as a\\n    zero would make the 0.98 automatic threshold unreachable in exactly the\\n    situation the product exists for. When neither side supplies the data the\\n    component is dropped and its weight is redistributed proportionally over\\n    the components that could actually be evaluated. Disagreement, by\\n    contrast, still scores zero and counts fully.\\n\\n    Number and set do not get this treatment: a listing that fails to state a\\n    card number has a real identification gap, and that gap should show up in\\n    the confidence rather than be normalised away.\\n    \\"\\"\\"\\n    checks: list[bool] = []\\n    if obs.year is not None and variant.year is not None:\\n        checks.append(obs.year == variant.year)\\n    if obs.illustrator and variant.illustrator:\\n        checks.append(normalize_name(obs.illustrator) == normalize_name(variant.illustrator))\\n    if not checks:\\n        return None\\n    return Decimal(sum(1 for c in checks if c)) / Decimal(len(checks))\\n\\n\\ndef _sibling_ambiguity(\\n    obs: ObservedCard,\\n    variant: CardVariant,\\n    universe: Mapping[str, CardVariant],\\n) -> tuple[bool, tuple[str, ...]]:\\n    \\"\\"\\"Are sibling variants equally consistent with what we observed?\\n\\n    Returns ``True`` when at least one sibling survives the same hard gates,\\n    which means the evidence does not pin down which printing this is.\\n    \\"\\"\\"\\n    notes: list[str] = []\\n    ambiguous = False\\n    for sibling_id in variant.sibling_variant_ids:\\n        sibling = universe.get(sibling_id)\\n        if sibling is None:\\n            continue\\n        if _gate_failures(obs, sibling):\\n            continue  # evidence rules this sibling out, good\\n        ambiguous = True\\n        reason = \\"printing\\" if sibling.printing is not variant.printing else \\"variant\\"\\n        notes.append(\\n            f\\"sibling {sibling.variant_id} ({sibling.printing.value}) is equally \\"\\n            f\\"consistent with the evidence; {reason} not disambiguated\\"\\n        )\\n    return ambiguous, tuple(notes)\\n\\n\\ndef match_card(\\n    observed: ObservedCard,\\n    universe: Sequence[CardVariant],\\n    aliases: Optional[AliasIndex] = None,\\n) -> MatchResult:\\n    \\"\\"\\"Match an observed listing against the canonical universe.\\n\\n    ``universe`` should be a pre-blocked candidate set (same language and set\\n    code where known) for performance, but correctness does not depend on it.\\n    \\"\\"\\"\\n    aliases = aliases or AliasIndex()\\n    by_id = {v.variant_id: v for v in universe}\\n\\n    considered: list[MatchCandidate] = []\\n    rejected: list[MatchCandidate] = []\\n\\n    for variant in universe:\\n        gates = _gate_failures(observed, variant)\\n        if gates:\\n            rejected.append(\\n                MatchCandidate(variant, Decimal(\\"0\\"), {}, gates, ())\\n            )\\n            continue\\n\\n        number_score = (\\n            Decimal(\\"1\\")\\n            if normalize_number(observed.number)\\n            and normalize_number(observed.number) == normalize_number(variant.number)\\n            else Decimal(\\"0\\")\\n        )\\n        set_score = (\\n            Decimal(\\"1\\")\\n            if normalize_set_code(observed.set_code)\\n            and normalize_set_code(observed.set_code) == normalize_set_code(variant.set_code)\\n            else Decimal(\\"0\\")\\n        )\\n        name_score = _name_score(observed, variant, aliases)\\n        attr_score, unknown_attrs = _variant_attr_score(observed, variant)\\n        prov_score = _provenance_score(observed, variant)\\n\\n        components: dict[str, Decimal] = {\\n            \\"number\\": number_score,\\n            \\"set\\": set_score,\\n            \\"name\\": name_score,\\n            \\"variant_attrs\\": attr_score,\\n        }\\n        if prov_score is not None:\\n            components[\\"provenance\\"] = prov_score\\n\\n        # Redistribute the weight of any dropped optional component so the\\n        # weights over evaluable components still sum to one.\\n        active_weight = sum(_WEIGHTS[k] for k in components)\\n        raw = sum(\\n            (_WEIGHTS[k] / active_weight) * v for k, v in components.items()\\n        )\\n\\n        penalties: list[str] = []\\n        confidence = Decimal(raw)\\n\\n        ambiguous, ambiguity_notes = _sibling_ambiguity(observed, variant, by_id)\\n        if ambiguous:\\n            penalties.extend(ambiguity_notes)\\n            confidence = min(confidence, AMBIGUITY_CEILING)\\n\\n        if unknown_attrs and confidence >= AUTO_MATCH_THRESHOLD:\\n            # Never auto-match while a discriminator is unstated, even with a\\n            # perfect name and number. This is the conservative bias in code.\\n            penalties.append(\\n                f\\"{unknown_attrs} relevant variant discriminator(s) unstated by \\"\\n                \\"the source\\"\\n            )\\n            confidence = min(confidence, AMBIGUITY_CEILING)\\n\\n        considered.append(\\n            MatchCandidate(\\n                variant,\\n                confidence.quantize(Decimal(\\"0.0001\\")),\\n                {k: v.quantize(Decimal(\\"0.0001\\")) for k, v in components.items()},\\n                (),\\n                tuple(penalties),\\n            )\\n        )\\n\\n    considered.sort(key=lambda c: c.confidence, reverse=True)\\n\\n    if not considered:\\n        return MatchResult(\\n            MatchOutcome.REJECT,\\n            None,\\n            (),\\n            tuple(rejected),\\n            (\\"every candidate failed a hard gate\\",),\\n        )\\n\\n    best = considered[0]\\n\\n    # Two distinct variants tied at the top is itself ambiguity.\\n    if len(considered) > 1 and considered[1].confidence == best.confidence:\\n        best = MatchCandidate(\\n            best.variant,\\n            min(best.confidence, AMBIGUITY_CEILING),\\n            best.components,\\n            best.gate_failures,\\n            best.penalties + (\\"tied with another candidate at equal confidence\\",),\\n        )\\n        considered[0] = best\\n\\n    if best.confidence >= AUTO_MATCH_THRESHOLD:\\n        outcome = MatchOutcome.AUTO\\n    elif best.confidence >= REVIEW_THRESHOLD:\\n        outcome = MatchOutcome.REVIEW\\n    else:\\n        outcome = MatchOutcome.REJECT\\n\\n    explanation = tuple(\\n        f\\"{k}={v}\\" for k, v in sorted(best.components.items())\\n    ) + best.penalties\\n\\n    return MatchResult(outcome, best, tuple(considered), tuple(rejected), explanation)\\n", "pokearb_core/ingest/__init__.py": "\\"\\"\\"Ingestion routes that do not depend on gated APIs.\\"\\"\\"\\n\\nfrom .manual import (  # noqa: F401\\n    ImportIssue,\\n    ImportProvenance,\\n    LISTING_COLUMNS,\\n    ParsedImport,\\n    SALE_COLUMNS,\\n    content_hash,\\n    parse_listings,\\n    parse_sales,\\n    schema_help,\\n)\\n", "pokearb_core/ingest/manual.py": "\\"\\"\\"Manual import of legitimately obtained sales and listings.\\n\\nEvery automated source is either gated, unverified, or forbids the polling\\npattern the product wants. That is a permanent condition for some of them, not\\na temporary one, so the system needs a route that does not depend on any of\\nthem. This is it: a documented CSV or JSON schema that a person fills from\\nrecords they are entitled to use, such as their own purchase and sale history,\\nan export a marketplace gives its own seller, or figures they transcribed by\\nhand from a page they were allowed to read.\\n\\nThree properties are load-bearing.\\n\\n**Idempotent.** A batch is identified by the hash of its content, not by when\\nit ran. Importing the same file twice inserts nothing the second time. Rows\\ncarry the source\'s own identifier, so the same sale arriving in two overlapping\\nexports is one sale.\\n\\n**Provenance.** Every row records who imported it, from where, and under what\\nevidence URL. An imported number with no traceable origin is indistinguishable\\nfrom an invented one, and this system\'s whole claim is that it never invents.\\n\\n**Synthetic data is labelled, not hidden.** Demonstration rows are marked\\n``synthetic_demo`` at the row level and the source level, and the database\\nrefuses to attribute a synthetic row to a real marketplace. Demo data that can\\nquietly reach a recommendation is worse than no demo data.\\n\\nThis module does no I/O. It parses, validates and hashes; the caller persists.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport csv\\nimport hashlib\\nimport io\\nimport json\\nfrom dataclasses import dataclass, field\\nfrom datetime import date, datetime, timezone\\nfrom decimal import Decimal, InvalidOperation\\nfrom typing import Any, Iterable, Mapping, Optional, Sequence\\n\\nfrom ..types import (\\n    Currency,\\n    EuCondition,\\n    Grader,\\n    Language,\\n    Listing,\\n    Money,\\n    Sale,\\n)\\n\\n__all__ = [\\n    \\"ImportProvenance\\",\\n    \\"ImportIssue\\",\\n    \\"ParsedImport\\",\\n    \\"SALE_COLUMNS\\",\\n    \\"LISTING_COLUMNS\\",\\n    \\"content_hash\\",\\n    \\"parse_sales\\",\\n    \\"parse_listings\\",\\n    \\"schema_help\\",\\n]\\n\\n#: Required then optional. Documented here because this is the contract a human\\n#: fills in by hand, and an undocumented contract is a guessing game.\\nSALE_COLUMNS: Mapping[str, str] = {\\n    \\"external_id\\": \\"required. The source\'s own id for the transaction. Used for deduplication.\\",\\n    \\"variant_id\\": \\"required. Canonical variant this sale is evidence for.\\",\\n    \\"sold_at\\": \\"required. ISO 8601 date or datetime the transaction completed.\\",\\n    \\"price_amount\\": \\"required. Numeric, no thousands separators.\\",\\n    \\"price_currency\\": \\"required. JPY, EUR, DKK, USD or GBP.\\",\\n    \\"market\\": \\"required. JP, EU, US or GLOBAL. Where the transaction happened.\\",\\n    \\"language\\": \\"required. Card language: ja, en, de, fr, it, es, pt, ko, zh.\\",\\n    \\"condition\\": \\"optional. nm, ex, gd, lp, pl, po. Blank means unknown, which is modelled as unknown.\\",\\n    \\"condition_confidence\\": \\"optional. 0 to 1. Blank means 1. Zero is a real value and is preserved.\\",\\n    \\"graded\\": \\"optional. true/false. Default false.\\",\\n    \\"grader\\": \\"optional. psa, bgs, cgc, sgc, ace, tag. Required when graded is true.\\",\\n    \\"grade\\": \\"optional. Numeric grade. Required when graded is true.\\",\\n    \\"shipping_included\\": \\"optional. true/false. Default false.\\",\\n    \\"known_at\\": \\"optional. When this became knowable. Defaults to sold_at. Drives backtest correctness.\\",\\n    \\"source_url\\": \\"optional but strongly preferred. Where the figure can be checked.\\",\\n}\\n\\nLISTING_COLUMNS: Mapping[str, str] = {\\n    \\"external_id\\": \\"required. The source\'s own listing id. Successive observations share it.\\",\\n    \\"variant_id\\": \\"required.\\",\\n    \\"observed_at\\": \\"required. ISO 8601 instant this price was seen.\\",\\n    \\"price_amount\\": \\"required.\\",\\n    \\"price_currency\\": \\"required.\\",\\n    \\"market\\": \\"required. JP, EU, US or GLOBAL.\\",\\n    \\"language\\": \\"required.\\",\\n    \\"condition\\": \\"optional.\\",\\n    \\"quantity\\": \\"optional. Default 1.\\",\\n    \\"graded\\": \\"optional. Default false.\\",\\n    \\"grader\\": \\"optional.\\",\\n    \\"grade\\": \\"optional.\\",\\n    \\"seller_id\\": \\"optional.\\",\\n    \\"source_url\\": \\"optional but strongly preferred.\\",\\n}\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ImportProvenance:\\n    \\"\\"\\"Who imported this, from where, and on whose authority.\\"\\"\\"\\n\\n    source_id: str\\n    imported_by: str\\n    evidence_url: Optional[str] = None\\n    filename: Optional[str] = None\\n    note: Optional[str] = None\\n    synthetic: bool = False\\n\\n    def problems(self) -> tuple[str, ...]:\\n        issues: list[str] = []\\n        if not self.source_id.strip():\\n            issues.append(\\"source_id is required\\")\\n        if not self.imported_by.strip():\\n            issues.append(\\n                \\"imported_by is required: an imported figure with no named \\"\\n                \\"importer cannot be audited\\"\\n            )\\n        if not self.synthetic and not self.evidence_url:\\n            issues.append(\\n                \\"evidence_url is required for production imports so the figure \\"\\n                \\"can be checked against its origin\\"\\n            )\\n        return tuple(issues)\\n\\n    @property\\n    def dataset(self) -> str:\\n        return \\"synthetic_demo\\" if self.synthetic else \\"production\\"\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ImportIssue:\\n    \\"\\"\\"One row that could not be used, and exactly why.\\"\\"\\"\\n\\n    row_number: int\\n    field: Optional[str]\\n    message: str\\n    raw: Mapping[str, Any] = field(default_factory=dict)\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ParsedImport:\\n    \\"\\"\\"Result of parsing one file. Never partially applied by accident.\\"\\"\\"\\n\\n    provenance: ImportProvenance\\n    content_hash: str\\n    sales: tuple[Sale, ...] = ()\\n    listings: tuple[Listing, ...] = ()\\n    issues: tuple[ImportIssue, ...] = ()\\n    row_count: int = 0\\n\\n    @property\\n    def ok(self) -> bool:\\n        return not self.issues\\n\\n    def summary(self) -> str:\\n        kind = \\"synthetic\\" if self.provenance.synthetic else \\"production\\"\\n        return (\\n            f\\"{self.row_count} row(s) read, {len(self.sales)} sale(s), \\"\\n            f\\"{len(self.listings)} listing(s), {len(self.issues)} rejected \\"\\n            f\\"[{kind}, hash {self.content_hash[:12]}]\\"\\n        )\\n\\n\\ndef content_hash(payload: str | bytes) -> str:\\n    \\"\\"\\"Stable identity of a file\'s content. The idempotency key.\\"\\"\\"\\n    data = payload.encode(\\"utf-8\\") if isinstance(payload, str) else payload\\n    return hashlib.sha256(data).hexdigest()\\n\\n\\ndef schema_help(kind: str = \\"sales\\") -> str:\\n    \\"\\"\\"Human-readable column contract, for the CLI and the docs.\\"\\"\\"\\n    cols = SALE_COLUMNS if kind == \\"sales\\" else LISTING_COLUMNS\\n    width = max(len(c) for c in cols)\\n    lines = [f\\"Columns for a {kind} import (CSV header or JSON object keys):\\", \\"\\"]\\n    lines += [f\\"  {name:<{width}}  {desc}\\" for name, desc in cols.items()]\\n    return \\"\\\\n\\".join(lines)\\n\\n\\n# ------------------------------------------------------------- conversions --\\n\\ndef _rows(payload: str) -> tuple[list[dict[str, Any]], Optional[str]]:\\n    text = payload.strip()\\n    if not text:\\n        return [], \\"file is empty\\"\\n    if text[0] in \\"[{\\":\\n        try:\\n            data = json.loads(text)\\n        except json.JSONDecodeError as exc:\\n            return [], f\\"invalid JSON: {exc}\\"\\n        if isinstance(data, dict):\\n            data = data.get(\\"rows\\", [])\\n        if not isinstance(data, list):\\n            return [], \\"JSON must be a list of row objects, or {\'rows\': [...]}\\"\\n        return [dict(r) for r in data], None\\n    reader = csv.DictReader(io.StringIO(text))\\n    return [dict(r) for r in reader], None\\n\\n\\ndef _dec(value: Any, fieldname: str) -> Decimal:\\n    try:\\n        return Decimal(str(value).strip())\\n    except (InvalidOperation, AttributeError, ValueError) as exc:\\n        raise ValueError(f\\"{fieldname}: not a number ({value!r})\\") from exc\\n\\n\\ndef _bool(value: Any, default: bool = False) -> bool:\\n    if value is None or str(value).strip() == \\"\\":\\n        return default\\n    return str(value).strip().lower() in {\\"1\\", \\"true\\", \\"yes\\", \\"y\\", \\"t\\"}\\n\\n\\ndef _dt(value: Any, fieldname: str) -> datetime:\\n    text = str(value).strip()\\n    if not text:\\n        raise ValueError(f\\"{fieldname}: required\\")\\n    try:\\n        if len(text) == 10:\\n            parsed = datetime.combine(date.fromisoformat(text), datetime.min.time())\\n        else:\\n            parsed = datetime.fromisoformat(text.replace(\\"Z\\", \\"+00:00\\"))\\n    except ValueError as exc:\\n        raise ValueError(f\\"{fieldname}: not an ISO 8601 date or datetime ({text!r})\\") from exc\\n    return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)\\n\\n\\ndef _enum(cls, value: Any, fieldname: str, required: bool = True):\\n    text = (str(value).strip() if value is not None else \\"\\")\\n    if not text:\\n        if required:\\n            raise ValueError(f\\"{fieldname}: required\\")\\n        return None\\n    for candidate in (text, text.lower(), text.upper()):\\n        try:\\n            return cls(candidate)\\n        except ValueError:\\n            continue\\n    allowed = \\", \\".join(m.value for m in cls)\\n    raise ValueError(f\\"{fieldname}: {text!r} is not one of {allowed}\\")\\n\\n\\n_MARKETS = {\\"JP\\", \\"EU\\", \\"US\\", \\"GLOBAL\\"}\\n\\n\\ndef _market(value: Any) -> str:\\n    text = str(value or \\"\\").strip().upper()\\n    if text not in _MARKETS:\\n        raise ValueError(\\n            f\\"market: {text or \'blank\'!r} is not one of {\', \'.join(sorted(_MARKETS))}\\"\\n        )\\n    return text\\n\\n\\n# ------------------------------------------------------------------ parsing --\\n\\ndef parse_sales(payload: str, provenance: ImportProvenance) -> ParsedImport:\\n    \\"\\"\\"Parse a sales file into ``Sale`` objects, or say precisely what is wrong.\\n\\n    Nothing is silently coerced. A missing market is an error rather than a\\n    default, because guessing the market is how Japanese prices end up standing\\n    for European resale value.\\n    \\"\\"\\"\\n    digest = content_hash(payload)\\n    prov_issues = provenance.problems()\\n    rows, err = _rows(payload)\\n    issues: list[ImportIssue] = [\\n        ImportIssue(0, None, m) for m in prov_issues\\n    ]\\n    if err:\\n        issues.append(ImportIssue(0, None, err))\\n        return ParsedImport(provenance, digest, issues=tuple(issues))\\n\\n    sales: list[Sale] = []\\n    seen: set[str] = set()\\n\\n    for n, row in enumerate(rows, start=1):\\n        try:\\n            external_id = str(row.get(\\"external_id\\") or \\"\\").strip()\\n            if not external_id:\\n                raise ValueError(\\"external_id: required for deduplication\\")\\n            if external_id in seen:\\n                issues.append(ImportIssue(\\n                    n, \\"external_id\\",\\n                    f\\"duplicate external_id {external_id!r} within this file; \\"\\n                    \\"the second occurrence was dropped rather than counted twice\\",\\n                    row,\\n                ))\\n                continue\\n            variant_id = str(row.get(\\"variant_id\\") or \\"\\").strip()\\n            if not variant_id:\\n                raise ValueError(\\"variant_id: required\\")\\n\\n            sold_at = _dt(row.get(\\"sold_at\\"), \\"sold_at\\")\\n            known_raw = row.get(\\"known_at\\")\\n            known_at = _dt(known_raw, \\"known_at\\") if str(known_raw or \\"\\").strip() else sold_at\\n            if known_at < sold_at:\\n                issues.append(ImportIssue(\\n                    n, \\"known_at\\",\\n                    \\"known_at is before sold_at; evidence cannot be known before \\"\\n                    \\"the transaction, so sold_at was used\\",\\n                    row,\\n                ))\\n                known_at = sold_at\\n\\n            currency = _enum(Currency, row.get(\\"price_currency\\"), \\"price_currency\\")\\n            amount = _dec(row.get(\\"price_amount\\"), \\"price_amount\\")\\n            if amount <= 0:\\n                raise ValueError(\\"price_amount: must be positive\\")\\n\\n            graded = _bool(row.get(\\"graded\\"))\\n            grader = _enum(Grader, row.get(\\"grader\\"), \\"grader\\", required=graded)\\n            grade_raw = row.get(\\"grade\\")\\n            grade = _dec(grade_raw, \\"grade\\") if str(grade_raw or \\"\\").strip() else None\\n            if graded and grade is None:\\n                raise ValueError(\\"grade: required when graded is true\\")\\n            if not graded and (grader is not None or grade is not None):\\n                raise ValueError(\\n                    \\"grader/grade supplied but graded is false; a graded card and \\"\\n                    \\"a raw card are different assets and must not be conflated\\"\\n                )\\n\\n            conf_raw = row.get(\\"condition_confidence\\")\\n            if str(conf_raw or \\"\\").strip() == \\"\\":\\n                confidence = Decimal(\\"1.0\\")\\n            else:\\n                confidence = _dec(conf_raw, \\"condition_confidence\\")\\n                if confidence < 0 or confidence > 1:\\n                    raise ValueError(\\"condition_confidence: must be between 0 and 1\\")\\n\\n            sales.append(Sale(\\n                sale_id=f\\"{provenance.source_id}:{external_id}\\",\\n                variant_id=variant_id,\\n                source_id=provenance.source_id,\\n                sold_at=sold_at,\\n                price=Money(amount, currency),\\n                condition=_enum(EuCondition, row.get(\\"condition\\"), \\"condition\\", required=False),\\n                language=_enum(Language, row.get(\\"language\\"), \\"language\\"),\\n                source_url=(str(row.get(\\"source_url\\") or \\"\\").strip()\\n                            or provenance.evidence_url or None),\\n                is_graded=graded,\\n                grader=grader,\\n                grade=grade,\\n                shipping_included=_bool(row.get(\\"shipping_included\\")),\\n                condition_confidence=confidence,\\n                market=_market(row.get(\\"market\\")),\\n                external_id=external_id,\\n                known_at=known_at,\\n            ))\\n            seen.add(external_id)\\n        except ValueError as exc:\\n            message = str(exc)\\n            field_name = message.split(\\":\\", 1)[0] if \\":\\" in message else None\\n            issues.append(ImportIssue(n, field_name, message, row))\\n\\n    return ParsedImport(\\n        provenance=provenance,\\n        content_hash=digest,\\n        sales=tuple(sales),\\n        issues=tuple(issues),\\n        row_count=len(rows),\\n    )\\n\\n\\ndef parse_listings(payload: str, provenance: ImportProvenance) -> ParsedImport:\\n    \\"\\"\\"Parse a listings file. Listings are never fair-value evidence.\\"\\"\\"\\n    digest = content_hash(payload)\\n    rows, err = _rows(payload)\\n    issues: list[ImportIssue] = [ImportIssue(0, None, m) for m in provenance.problems()]\\n    if err:\\n        issues.append(ImportIssue(0, None, err))\\n        return ParsedImport(provenance, digest, issues=tuple(issues))\\n\\n    listings: list[Listing] = []\\n    for n, row in enumerate(rows, start=1):\\n        try:\\n            external_id = str(row.get(\\"external_id\\") or \\"\\").strip()\\n            if not external_id:\\n                raise ValueError(\\"external_id: required\\")\\n            variant_id = str(row.get(\\"variant_id\\") or \\"\\").strip()\\n            if not variant_id:\\n                raise ValueError(\\"variant_id: required\\")\\n            amount = _dec(row.get(\\"price_amount\\"), \\"price_amount\\")\\n            if amount <= 0:\\n                raise ValueError(\\"price_amount: must be positive\\")\\n            graded = _bool(row.get(\\"graded\\"))\\n            grade_raw = row.get(\\"grade\\")\\n            listings.append(Listing(\\n                listing_id=f\\"{provenance.source_id}:{external_id}\\",\\n                variant_id=variant_id,\\n                source_id=provenance.source_id,\\n                observed_at=_dt(row.get(\\"observed_at\\"), \\"observed_at\\"),\\n                price=Money(amount, _enum(Currency, row.get(\\"price_currency\\"),\\n                                          \\"price_currency\\")),\\n                condition=_enum(EuCondition, row.get(\\"condition\\"), \\"condition\\", required=False),\\n                language=_enum(Language, row.get(\\"language\\"), \\"language\\"),\\n                source_url=(str(row.get(\\"source_url\\") or \\"\\").strip()\\n                            or provenance.evidence_url or None),\\n                seller_id=(str(row.get(\\"seller_id\\") or \\"\\").strip() or None),\\n                is_graded=graded,\\n                grader=_enum(Grader, row.get(\\"grader\\"), \\"grader\\", required=graded),\\n                grade=_dec(grade_raw, \\"grade\\") if str(grade_raw or \\"\\").strip() else None,\\n                quantity=int(row.get(\\"quantity\\") or 1),\\n                market=_market(row.get(\\"market\\")),\\n                external_id=external_id,\\n            ))\\n        except (ValueError, TypeError) as exc:\\n            message = str(exc)\\n            field_name = message.split(\\":\\", 1)[0] if \\":\\" in message else None\\n            issues.append(ImportIssue(n, field_name, message, row))\\n\\n    return ParsedImport(\\n        provenance=provenance,\\n        content_hash=digest,\\n        listings=tuple(listings),\\n        issues=tuple(issues),\\n        row_count=len(rows),\\n    )\\n", "pokearb_core/liquidity/__init__.py": "\\"\\"\\"PokeArb core subpackage.\\"\\"\\"\\n", "pokearb_core/liquidity/model.py": "\\"\\"\\"Liquidity model.\\n\\nLiquidity is not a decoration on an opportunity card. In this system it is a\\ngate: below a configurable floor an opportunity is suppressed entirely rather\\nthan ranked low, because a 150 percent spread on a card that trades twice a\\nyear is a number, not a trade, and showing it at rank 40 still invites the\\nmistake.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport statistics\\nfrom dataclasses import dataclass\\nfrom datetime import datetime, timedelta, timezone\\nfrom decimal import Decimal\\nfrom enum import Enum\\nfrom typing import Optional, Sequence\\n\\nfrom ..types import Listing, Money, Sale\\n\\n__all__ = [\\"LiquidityBand\\", \\"LiquidityProfile\\", \\"compute_liquidity\\"]\\n\\n\\nclass LiquidityBand(str, Enum):\\n    VERY_HIGH = \\"very_high\\"\\n    HIGH = \\"high\\"\\n    MEDIUM = \\"medium\\"\\n    LOW = \\"low\\"\\n    VERY_LOW = \\"very_low\\"\\n    UNKNOWN = \\"unknown\\"\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass LiquidityProfile:\\n    band: LiquidityBand\\n    score: Optional[Decimal]  # 0..100, None when unmeasurable\\n    sales_7d: int\\n    sales_30d: int\\n    sales_90d: int\\n    active_listings: Optional[int]\\n    listing_to_sales_ratio: Optional[Decimal]\\n    median_days_between_sales: Optional[Decimal]\\n    price_dispersion: Optional[Decimal]\\n    spread_proxy: Optional[Decimal]\\n    expected_days_to_sell: Optional[Decimal]\\n    reasons: tuple[str, ...]\\n\\n    @property\\n    def is_measurable(self) -> bool:\\n        return self.score is not None\\n\\n\\ndef _count_within(sales: Sequence[Sale], as_of: datetime, days: int) -> int:\\n    cutoff = as_of - timedelta(days=days)\\n    return sum(1 for s in sales if cutoff <= _aware(s.sold_at) <= as_of)\\n\\n\\ndef _aware(dt: datetime) -> datetime:\\n    return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)\\n\\n\\ndef compute_liquidity(\\n    sales: Sequence[Sale],\\n    listings: Sequence[Listing],\\n    *,\\n    as_of: datetime,\\n    min_sales_for_score: int = 2,\\n) -> LiquidityProfile:\\n    \\"\\"\\"Liquidity profile from completed sales and current supply.\\n\\n    Returns ``score=None`` when there is not enough activity to measure rather\\n    than returning a low score, because \\"unmeasurable\\" and \\"illiquid\\" call for\\n    different handling: the first needs more data, the second needs avoiding.\\n    \\"\\"\\"\\n    as_of = _aware(as_of)\\n    reasons: list[str] = []\\n\\n    s7 = _count_within(sales, as_of, 7)\\n    s30 = _count_within(sales, as_of, 30)\\n    s90 = _count_within(sales, as_of, 90)\\n\\n    active = len(listings) if listings else None\\n    ratio = (\\n        Decimal(active) / Decimal(max(s90, 1)) if active is not None and s90 else None\\n    )\\n\\n    ordered = sorted((_aware(s.sold_at) for s in sales), reverse=True)\\n    gaps = [\\n        Decimal(str((ordered[i] - ordered[i + 1]).total_seconds() / 86400.0))\\n        for i in range(len(ordered) - 1)\\n    ]\\n    median_gap = (\\n        Decimal(str(statistics.median([float(g) for g in gaps]))) if gaps else None\\n    )\\n\\n    sale_prices = [s.price.amount for s in sales if s.price.amount > 0]\\n    dispersion = None\\n    if len(sale_prices) >= 4:\\n        med = Decimal(str(statistics.median([float(p) for p in sale_prices])))\\n        if med > 0:\\n            q = statistics.quantiles([float(p) for p in sale_prices], n=4)\\n            dispersion = (Decimal(str(q[2])) - Decimal(str(q[0]))) / med\\n\\n    spread = None\\n    if listings and sale_prices:\\n        listing_prices = [l.price.amount for l in listings if l.price.amount > 0]\\n        if listing_prices:\\n            med_list = Decimal(str(statistics.median([float(p) for p in listing_prices])))\\n            med_sale = Decimal(str(statistics.median([float(p) for p in sale_prices])))\\n            if med_sale > 0:\\n                spread = (med_list - med_sale) / med_sale\\n\\n    if s90 < min_sales_for_score:\\n        reasons.append(\\n            f\\"only {s90} completed sale(s) in 90 days; liquidity is not measurable, \\"\\n            \\"which is different from being low\\"\\n        )\\n        return LiquidityProfile(\\n            LiquidityBand.UNKNOWN, None, s7, s30, s90, active, ratio, median_gap,\\n            dispersion, spread, None, tuple(reasons),\\n        )\\n\\n    # Velocity is the dominant term. Depth of supply and price agreement adjust it.\\n    velocity = Decimal(s90) / Decimal(\\"90\\")  # sales per day\\n    velocity_score = min(Decimal(\\"70\\"), velocity * Decimal(\\"700\\"))\\n    reasons.append(f\\"{s90} sale(s) in 90 days drives the base score\\")\\n\\n    depth_score = Decimal(\\"0\\")\\n    if active is not None:\\n        if active == 0:\\n            reasons.append(\\"no active listings; exit route unproven\\")\\n        else:\\n            depth_score = min(Decimal(\\"15\\"), Decimal(active) * Decimal(\\"1.5\\"))\\n            reasons.append(f\\"{active} active listing(s) confirm a live market\\")\\n\\n    agreement_score = Decimal(\\"15\\")\\n    if dispersion is not None:\\n        if dispersion > Decimal(\\"0.6\\"):\\n            agreement_score = Decimal(\\"3\\")\\n            reasons.append(f\\"wide price dispersion (IQR/median {dispersion:.2f}) reduces the score\\")\\n        elif dispersion > Decimal(\\"0.3\\"):\\n            agreement_score = Decimal(\\"9\\")\\n            reasons.append(f\\"moderate price dispersion (IQR/median {dispersion:.2f})\\")\\n        else:\\n            reasons.append(f\\"tight price agreement (IQR/median {dispersion:.2f}) raises confidence\\")\\n\\n    if ratio is not None and ratio > Decimal(\\"8\\"):\\n        agreement_score = max(Decimal(\\"0\\"), agreement_score - Decimal(\\"6\\"))\\n        reasons.append(\\n            f\\"listing-to-sales ratio {ratio:.1f} suggests supply well ahead of demand\\"\\n        )\\n\\n    score = min(Decimal(\\"100\\"), velocity_score + depth_score + agreement_score)\\n\\n    if score >= 80:\\n        band = LiquidityBand.VERY_HIGH\\n    elif score >= 60:\\n        band = LiquidityBand.HIGH\\n    elif score >= 40:\\n        band = LiquidityBand.MEDIUM\\n    elif score >= 20:\\n        band = LiquidityBand.LOW\\n    else:\\n        band = LiquidityBand.VERY_LOW\\n\\n    expected_days = (\\n        Decimal(\\"90\\") / Decimal(s90) if s90 else None\\n    )\\n    if expected_days is not None and active:\\n        # Queue position: more competing listings means a longer wait.\\n        expected_days = expected_days * (Decimal(\\"1\\") + Decimal(active) / Decimal(\\"10\\"))\\n\\n    return LiquidityProfile(\\n        band, score.quantize(Decimal(\\"0.1\\")), s7, s30, s90, active, ratio,\\n        median_gap, dispersion, spread,\\n        expected_days.quantize(Decimal(\\"0.1\\")) if expected_days else None,\\n        tuple(reasons),\\n    )\\n", "pokearb_core/scanner.py": "\\"\\"\\"Find interesting cards by themselves, from market data alone. No I/O.\\n\\nThe scanner looks at every card in a universe of sets and reports three kinds\\nof signal, each explained in plain words:\\n\\n**Listed under its recent price.** Cardmarket\'s lowest current offer sits well\\nbelow the card\'s recent traded level, and buying at that offer and reselling\\nat the recent level clears the required return after selling fees and\\npostage. This is the only signal that implies a trade.\\n\\n**Rising** and **falling.** The 7-day average has moved away from the 30-day\\naverage, and Cardmarket\'s trend agrees with the direction. These describe\\nmomentum. They are not buy signals: a rising card is also a more expensive\\ncard.\\n\\nMarkets: Cardmarket only, in EUR, which is what a buyer in Denmark can\\ntransact on. Prices from US marketplaces in the same feed are ignored. No\\npermitted source of UK prices exists in the project yet. Taxes are left out\\nentirely, at the user\'s instruction; within the EU a Cardmarket purchase\\ncarries no import tax anyway.\\n\\nEvery threshold below is a judgement, not a finding, and lives in\\n``ScanConfig``. Each one errs towards staying quiet.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import dataclass, field\\nfrom datetime import date, datetime, timedelta, timezone\\nfrom decimal import Decimal\\nfrom typing import Any, Mapping, Optional, Sequence\\n\\nfrom .adapters.live import parse_tcgdex_cardmarket\\nfrom .types import MarketAverage, Printing\\nfrom .valuation.benchmark import BenchmarkConfig, assess_market_average\\n\\n__all__ = [\\"ScanConfig\\", \\"Signal\\", \\"ScanResult\\", \\"scan_set\\", \\"secret_rare_ids\\", \\"update_history\\"]\\n\\nD = Decimal\\n\\n\\n@dataclass(frozen=True)\\nclass ScanConfig:\\n    #: Ignore cards whose recent level is below this. Bulk moves are noise.\\n    min_value_eur: Decimal = D(\\"10\\")\\n    #: Buy signal: the lowest offer must sit at least this far under the\\n    #: recent level, and the flip must return at least ``required_roi``.\\n    min_discount: Decimal = D(\\"0.20\\")\\n    required_roi: Decimal = D(\\"0.30\\")\\n    #: Selling costs. Assumptions, not verified figures: set them to your own.\\n    selling_fee_rate: Decimal = D(\\"0.05\\")\\n    postage_in_eur: Decimal = D(\\"2.00\\")\\n    postage_out_eur: Decimal = D(\\"2.00\\")\\n    #: A buy signal needs a *new* low: today\'s lowest offer must sit this far\\n    #: under the median of the card\'s own lowest offers on earlier days. A\\n    #: cheap copy that has sat unsold for weeks is usually a worn one.\\n    new_low_drop: Decimal = D(\\"0.20\\")\\n    min_history_days: int = 3\\n    #: Deeper than this under the recent level is more likely a damaged copy\\n    #: or a different item than a bargain, and is not signalled.\\n    max_discount: Decimal = D(\\"0.55\\")\\n    #: Momentum: 7-day average against the 30-day average.\\n    momentum_threshold: Decimal = D(\\"0.15\\")\\n    benchmark: BenchmarkConfig = field(default_factory=BenchmarkConfig)\\n\\n\\n@dataclass(frozen=True)\\nclass Signal:\\n    kind: str                     # \\"buy\\", \\"rising\\", \\"falling\\"\\n    card_id: str\\n    name: str\\n    rarity: Optional[str]\\n    set_name: Optional[str]\\n    image: Optional[str]\\n    figures: Mapping[str, Optional[str]]\\n    headline: str\\n    detail: tuple[str, ...]\\n    score: Decimal                # ranking key within its kind\\n    numbers: Mapping[str, str] = field(default_factory=dict)\\n\\n    def as_dict(self) -> dict:\\n        return {\\n            \\"kind\\": self.kind, \\"card_id\\": self.card_id, \\"name\\": self.name,\\n            \\"rarity\\": self.rarity, \\"set\\": self.set_name, \\"image\\": self.image,\\n            \\"figures\\": dict(self.figures), \\"headline\\": self.headline,\\n            \\"detail\\": list(self.detail), \\"score\\": str(self.score),\\n            \\"numbers\\": dict(self.numbers),\\n        }\\n\\n\\n@dataclass\\nclass ScanResult:\\n    signals: list[Signal] = field(default_factory=list)\\n    scanned: int = 0\\n    skipped: dict[str, int] = field(default_factory=dict)\\n\\n    def skip(self, why: str) -> None:\\n        self.skipped[why] = self.skipped.get(why, 0) + 1\\n\\n    def merge(self, other: \\"ScanResult\\") -> None:\\n        self.signals.extend(other.signals)\\n        self.scanned += other.scanned\\n        for k, v in other.skipped.items():\\n            self.skipped[k] = self.skipped.get(k, 0) + v\\n\\n\\ndef _money(v: Optional[Decimal]) -> Optional[str]:\\n    return None if v is None else str(v.quantize(D(\\"0.01\\")))\\n\\n\\ndef secret_rare_ids(set_payload: Mapping[str, Any]) -> list[str]:\\n    \\"\\"\\"Cards numbered above the set\'s official count.\\n\\n    In the modern Japanese sets these are the illustration rares, special\\n    illustration rares, ultra rares and similar, which is where the prices\\n    and the price movements are. Scanning only these keeps the daily request\\n    count considerate.\\n    \\"\\"\\"\\n    official = int(((set_payload.get(\\"cardCount\\") or {}).get(\\"official\\")) or 0)\\n    out = []\\n    for c in set_payload.get(\\"cards\\") or []:\\n        local = str(c.get(\\"localId\\") or \\"\\")\\n        if local.isdigit() and official and int(local) > official:\\n            out.append(c[\\"id\\"])\\n    return out\\n\\n\\ndef _same_name(set_payload: Mapping[str, Any], card_id: str) -> list[str]:\\n    cards = set_payload.get(\\"cards\\") or []\\n    mine = next((c for c in cards if c.get(\\"id\\") == card_id), None)\\n    if mine is None:\\n        return []\\n    return [c[\\"id\\"] for c in cards if c.get(\\"name\\") == mine.get(\\"name\\") and c[\\"id\\"] != card_id]\\n\\n\\ndef _default_printing(variants: Mapping[str, Any]) -> Optional[Printing]:\\n    normal, holo = bool(variants.get(\\"normal\\")), bool(variants.get(\\"holo\\"))\\n    if holo and not normal:\\n        return Printing.HOLO\\n    if normal and not holo:\\n        return Printing.NON_HOLO\\n    return None\\n\\n\\ndef _product(payload: Optional[Mapping[str, Any]]) -> Optional[str]:\\n    if not payload:\\n        return None\\n    prod = ((payload.get(\\"pricing\\") or {}).get(\\"cardmarket\\") or {}).get(\\"idProduct\\")\\n    return str(prod) if prod not in (None, \\"\\", 0) else None\\n\\n\\ndef scan_set(\\n    set_payload: Mapping[str, Any],\\n    cards: Mapping[str, Mapping[str, Any]],\\n    *,\\n    now: Optional[datetime] = None,\\n    config: Optional[ScanConfig] = None,\\n    history: Optional[Mapping[str, Sequence[Sequence[Any]]]] = None,\\n    subjects: Optional[set] = None,\\n) -> ScanResult:\\n    \\"\\"\\"Signals for the fetched cards of one set.\\n\\n    ``subjects`` limits which cards are analysed; the rest of ``cards`` is\\n    used only to check same-name siblings for a shared Cardmarket listing.\\n\\n    ``cards`` maps card id to its TCGdex response. A same-name sibling that\\n    was not fetched makes the collision check unrunnable for that card, and\\n    the card is skipped rather than trusted.\\n    \\"\\"\\"\\n    cfg = config or ScanConfig()\\n    now = now or datetime.now(timezone.utc)\\n    result = ScanResult()\\n    set_name = set_payload.get(\\"name\\")\\n\\n    for card_id, payload in cards.items():\\n        if subjects is not None and card_id not in subjects:\\n            continue\\n        result.scanned += 1\\n        printing = _default_printing(payload.get(\\"variants\\") or {})\\n        if printing is None:\\n            result.skip(\\"more than one base printing\\")\\n            continue\\n        obs, _ = parse_tcgdex_cardmarket(\\n            payload, printing=printing, variant_id=card_id, known_at=now,\\n            source_url=f\\"https://api.tcgdex.net/v2/ja/cards/{card_id}\\",\\n        )\\n        if obs is None:\\n            result.skip(\\"no Cardmarket pricing\\")\\n            continue\\n\\n        siblings = _same_name(set_payload, card_id)\\n        sibling_products: Optional[list[str]] = []\\n        for sid in siblings:\\n            if sid not in cards:\\n                # The runner fetches every same-name sibling for this check;\\n                # one that is missing failed to fetch, so the mapping is\\n                # unverified and the card is not trusted.\\n                sibling_products = None\\n                break\\n            prod = _product(cards[sid])\\n            if prod:\\n                sibling_products.append(prod)\\n        if sibling_products is None:\\n            result.skip(\\"listing mapping could not be checked\\")\\n            continue\\n        if obs.product_id in sibling_products:\\n            result.skip(\\"Cardmarket listing shared with another printing\\")\\n            continue\\n\\n        age = now - obs.provider_updated_at\\n        if age > timedelta(days=cfg.benchmark.max_age_days):\\n            result.skip(\\"stale Cardmarket figures\\")\\n            continue\\n\\n        base = dict(\\n            card_id=card_id, name=str(payload.get(\\"name\\") or card_id),\\n            # TCGdex sends the literal string \\"None\\" for some cards.\\n            rarity=(payload.get(\\"rarity\\") if payload.get(\\"rarity\\") not in (None, \\"\\", \\"None\\")\\n                    else None), set_name=set_name,\\n            image=(payload.get(\\"image\\") + \\"/low.webp\\") if payload.get(\\"image\\") else None,\\n            figures={\\"avg\\": _money(obs.avg), \\"avg7\\": _money(obs.avg7),\\n                     \\"avg30\\": _money(obs.avg30), \\"trend\\": _money(obs.trend),\\n                     \\"low\\": _money(obs.low), \\"updated\\": obs.provider_updated_at.date().isoformat(),\\n                     \\"product_id\\": obs.product_id},\\n        )\\n\\n        level = obs.avg30 or obs.avg7\\n        if level is None or level < cfg.min_value_eur:\\n            result.skip(\\"below the value floor\\")\\n            continue\\n\\n        own = _own_change(history, card_id) if history else None\\n        result.signals.extend(_momentum(obs, cfg, base, own))\\n        prior = _prior_lows(history, card_id, now.date())\\n        if len(prior) < cfg.min_history_days:\\n            result.skip(\\"buy check waiting for price history\\")\\n            continue\\n        buy = _buy(obs, cfg, base, now, sibling_products, own, prior)\\n        if buy is not None:\\n            result.signals.append(buy)\\n    return result\\n\\n\\ndef _prior_lows(history, card_id: str, today: date) -> list[Decimal]:\\n    rows = (history or {}).get(card_id) or []\\n    out = []\\n    for r in rows:\\n        if r[0] == today.isoformat() or len(r) < 5 or not r[4]:\\n            continue\\n        out.append(D(str(r[4])))\\n    return out\\n\\n\\ndef _own_change(history: Mapping[str, Sequence[Sequence[Any]]], card_id: str) -> Optional[str]:\\n    \\"\\"\\"Change in the 7-day average against our own record from 7 or more days ago.\\"\\"\\"\\n    rows = history.get(card_id) or []\\n    if len(rows) < 2:\\n        return None\\n    latest = rows[-1]\\n    latest_day = date.fromisoformat(latest[0])\\n    older = [r for r in rows if (latest_day - date.fromisoformat(r[0])).days >= 7]\\n    if not older or not older[-1][1] or not latest[1]:\\n        return None\\n    then, now_v = D(str(older[-1][1])), D(str(latest[1]))\\n    if then <= 0:\\n        return None\\n    days = (latest_day - date.fromisoformat(older[-1][0])).days\\n    return f\\"{(now_v / then - 1):+.0%} in our own record over {days} days\\"\\n\\n\\ndef _momentum(obs: MarketAverage, cfg: ScanConfig, base: dict, own: Optional[str]) -> list[Signal]:\\n    if obs.avg7 is None or obs.avg30 is None or obs.trend is None or obs.avg30 <= 0:\\n        return []\\n    move = obs.avg7 / obs.avg30 - 1\\n    detail = [f\\"7-day average €{_money(obs.avg7)} against €{_money(obs.avg30)} over 30 days\\",\\n              f\\"Cardmarket trend €{_money(obs.trend)}\\"]\\n    if own:\\n        detail.append(own)\\n    if move >= cfg.momentum_threshold and obs.trend >= obs.avg30:\\n        return [Signal(kind=\\"rising\\", headline=f\\"Up {move:.0%} on its 30-day average\\",\\n                       detail=tuple(detail), score=move,\\n                       numbers={\\"move\\": str(move.quantize(D(\'0.0001\')))}, **base)]\\n    if move <= -cfg.momentum_threshold and obs.trend <= obs.avg30:\\n        return [Signal(kind=\\"falling\\", headline=f\\"Down {abs(move):.0%} on its 30-day average\\",\\n                       detail=tuple(detail), score=-move,\\n                       numbers={\\"move\\": str(move.quantize(D(\'0.0001\')))}, **base)]\\n    return []\\n\\n\\ndef _buy(obs: MarketAverage, cfg: ScanConfig, base: dict, now: datetime,\\n         sibling_products: Optional[list[str]], own: Optional[str],\\n         prior_lows: Sequence[Decimal]) -> Optional[Signal]:\\n    if obs.low is None:\\n        return None\\n    bench = assess_market_average(obs, as_of=now, sibling_product_ids=sibling_products,\\n                                  config=cfg.benchmark)\\n    if bench.refused or bench.value is None:\\n        return None\\n    ref = bench.value.amount\\n    if obs.low > ref * (1 - cfg.min_discount):\\n        return None\\n    if obs.low < ref * (1 - cfg.max_discount):\\n        return None\\n    ordered = sorted(prior_lows)\\n    mid = len(ordered) // 2\\n    usual_low = ordered[mid] if len(ordered) % 2 else (ordered[mid - 1] + ordered[mid]) / 2\\n    if obs.low > usual_low * (1 - cfg.new_low_drop):\\n        return None\\n    cost = obs.low + cfg.postage_in_eur\\n    proceeds = ref * (1 - cfg.selling_fee_rate) - cfg.postage_out_eur\\n    profit = proceeds - cost\\n    roi = profit / cost if cost > 0 else D(\\"0\\")\\n    if roi < cfg.required_roi:\\n        return None\\n    detail = [\\n        f\\"lowest offer €{_money(obs.low)} against a recent level of €{_money(ref)} \\"\\n        f\\"({bench.statistic.split(\': the \').pop()})\\",\\n        f\\"a new low: the lowest offer was usually €{_money(usual_low)} over the last \\"\\n        f\\"{len(ordered)} scans\\",\\n        f\\"after {cfg.selling_fee_rate:.0%} selling fees and €{_money(cfg.postage_in_eur)} \\"\\n        f\\"postage each way: €{_money(profit)} profit, {roi:.0%} return\\",\\n        \\"the lowest offer can be a worse condition or a damaged copy; check the listing\\",\\n    ]\\n    if own:\\n        detail.append(own)\\n    return Signal(\\n        kind=\\"buy\\",\\n        headline=f\\"Offered at €{_money(obs.low)}, {1 - obs.low / ref:.0%} under its recent €{_money(ref)}\\",\\n        detail=tuple(detail), score=roi,\\n        numbers={\\"buy\\": _money(obs.low), \\"sell\\": _money(ref), \\"profit\\": _money(profit),\\n                 \\"roi\\": str(roi.quantize(D(\\"0.0001\\")))},\\n        **base,\\n    )\\n\\n\\ndef update_history(\\n    history: dict[str, list[list[Any]]],\\n    cards: Mapping[str, Mapping[str, Any]],\\n    today: date,\\n    keep_days: int = 120,\\n) -> dict[str, list[list[Any]]]:\\n    \\"\\"\\"Append today\'s figures per card, one row per day, oldest dropped.\\n\\n    Rows are ``[date, avg7, avg30, trend, low]``. Our own dated record is what\\n    lets movement be measured on our terms rather than only from the\\n    provider\'s pre-computed averages.\\n    \\"\\"\\"\\n    cutoff = today - timedelta(days=keep_days)\\n    for card_id, payload in cards.items():\\n        cm = (payload.get(\\"pricing\\") or {}).get(\\"cardmarket\\") or {}\\n        if not cm:\\n            continue\\n        row = [today.isoformat()] + [cm.get(k) for k in (\\"avg7\\", \\"avg30\\", \\"trend\\", \\"low\\")]\\n        rows = [r for r in history.get(card_id, []) if r[0] != today.isoformat()\\n                and date.fromisoformat(r[0]) >= cutoff]\\n        rows.append(row)\\n        history[card_id] = rows\\n    return history\\n", "pokearb_core/scoring/__init__.py": "\\"\\"\\"PokeArb core subpackage.\\"\\"\\"\\n", "pokearb_core/scoring/opportunity.py": "\\"\\"\\"Explainable scoring and risk-adjusted opportunity evaluation.\\n\\nTwo ideas carry most of the weight here.\\n\\n**Every score explains itself.** A score is a number plus the list of reasons\\nthat moved it, each with its direction and magnitude. No component of this\\nsystem returns an unexplained 82.\\n\\n**Ranking uses a lower quantile of the profit distribution, not the point\\nestimate.** The point estimate of ROI is the number that looks best on a card\\nwith three sales, a provisional condition prior and no population data. Ranking\\non the 25th percentile of simulated ROI systematically demotes exactly those,\\nwhich is the asymmetry the brief asks for.\\n\\nBefore scoring happens at all, hard gates run. An opportunity failing a gate is\\n**suppressed**, not ranked low. It does not appear in a list where a tired\\nperson on a Tokyo shop floor might tap it.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport random\\nfrom dataclasses import dataclass, field\\nfrom datetime import datetime, timezone\\nfrom decimal import Decimal\\nfrom enum import Enum\\nfrom typing import Callable, Mapping, Optional, Protocol, Sequence\\n\\nfrom ..condition.model import condition_confidence\\nfrom ..liquidity.model import LiquidityBand, LiquidityProfile\\nfrom ..types import ConditionDistribution, DataQuality, FairValue, Money\\n\\n\\nclass _EconomicsResult(Protocol):\\n    \\"\\"\\"Structural view of the arbitrage engine\'s result.\\n\\n    Declared structurally so this module keeps no import edge to the arbitrage\\n    engine, which would make the dependency cyclic and, worse, tempt a future\\n    reader into recomputing the cost stack here.\\n    \\"\\"\\"\\n\\n    roi: Decimal\\n\\n    @property\\n    def capital_deployed_eur(self) -> Money: ...\\n\\n    @property\\n    def landed(self): ...\\n\\n\\n#: Buy side frozen, resale value varying. Supplied by the caller.\\nEconomicsFn = Callable[[Money], _EconomicsResult]\\n\\n__all__ = [\\n    \\"ScoreReason\\",\\n    \\"Score\\",\\n    \\"SuppressionReason\\",\\n    \\"OpportunityAssessment\\",\\n    \\"RiskConfig\\",\\n    \\"assess_opportunity\\",\\n    \\"compute_data_quality\\",\\n]\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ScoreReason:\\n    text: str\\n    direction: str  # \\"up\\" | \\"down\\" | \\"neutral\\"\\n    magnitude: Decimal\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass Score:\\n    name: str\\n    value: Optional[Decimal]\\n    reasons: tuple[ScoreReason, ...]\\n\\n    def explain(self) -> str:\\n        if self.value is None:\\n            return f\\"{self.name}: not measurable\\"\\n        lines = [f\\"{self.name}: {self.value}\\"]\\n        lines += [f\\"  {r.direction:>7} {r.magnitude:>5}  {r.text}\\" for r in self.reasons]\\n        return \\"\\\\n\\".join(lines)\\n\\n\\nclass SuppressionReason(str, Enum):\\n    MATCH_CONFIDENCE = \\"match_confidence_below_floor\\"\\n    FAIR_VALUE_INSUFFICIENT = \\"fair_value_insufficient_evidence\\"\\n    DATA_QUALITY = \\"data_quality_below_floor\\"\\n    LIQUIDITY = \\"liquidity_below_floor\\"\\n    LIQUIDITY_UNMEASURABLE = \\"liquidity_not_measurable\\"\\n    STALE_DATA = \\"data_too_stale\\"\\n    CONDITION_CONFIDENCE = \\"condition_confidence_below_floor\\"\\n    LANDED_COST_UNRESOLVED = \\"landed_cost_unresolved\\"\\n    ABOVE_MAX_BUY = \\"asking_price_above_maximum\\"\\n    BELOW_REQUIRED_RETURN = \\"below_required_return\\"\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass RiskConfig:\\n    \\"\\"\\"Suppression floors and simulation settings.\\n\\n    Defaults are deliberately strict. Loosening them is a decision the operator\\n    makes knowingly, which is the point.\\n    \\"\\"\\"\\n\\n    min_match_confidence: Decimal = Decimal(\\"0.98\\")\\n    min_data_quality: Decimal = Decimal(\\"45\\")\\n    min_liquidity_score: Decimal = Decimal(\\"25\\")\\n    #: Deliberately low. A Japanese shop grade genuinely spans several\\n    #: European grades, and that spread is inherent in the measurement, not a\\n    #: data defect. It is already paid for twice: in the probability-weighted\\n    #: expected value, and in the simulation haircut. Gating on it at a normal\\n    #: level would suppress every shop-graded card, which defeats the product.\\n    #: This floor exists only to catch the pathological near-uniform case,\\n    #: where the distribution says nothing at all.\\n    min_condition_confidence: Decimal = Decimal(\\"0.08\\")\\n    max_data_age_days: int = 120\\n    allow_unmeasurable_liquidity: bool = False\\n    #: Quantile of simulated ROI used for ranking.\\n    ranking_quantile: float = 0.25\\n    simulations: int = 4000\\n    #: Relative standard deviation applied to fair value, scaled by evidence.\\n    fair_value_rel_sigma: float = 0.18\\n    random_seed: int = 20260920\\n\\n\\ndef compute_data_quality(\\n    fair_value: FairValue,\\n    *,\\n    as_of: datetime,\\n    source_count: int,\\n    match_confidence: Decimal,\\n    condition_dist: Optional[ConditionDistribution] = None,\\n) -> DataQuality:\\n    \\"\\"\\"Explainable 0 to 100 data-quality assessment.\\"\\"\\"\\n    reasons: list[str] = []\\n    score = Decimal(\\"0\\")\\n\\n    n = fair_value.n_sales\\n    if n >= 12:\\n        score += Decimal(\\"35\\")\\n        reasons.append(f\\"{n} completed sales give a solid base (+35)\\")\\n    elif n >= 6:\\n        score += Decimal(\\"26\\")\\n        reasons.append(f\\"{n} completed sales are workable (+26)\\")\\n    elif n >= 3:\\n        score += Decimal(\\"15\\")\\n        reasons.append(f\\"only {n} completed sales, thin evidence (+15)\\")\\n    else:\\n        reasons.append(f\\"{n} completed sales is below the minimum evidence rule (+0)\\")\\n\\n    ages = [\\n        int((_aware(as_of) - _aware(ref.observed_at)).total_seconds() // 86400)\\n        for ref in fair_value.inputs\\n    ]\\n    oldest = max(ages) if ages else None\\n    newest = min(ages) if ages else None\\n\\n    if newest is None:\\n        reasons.append(\\"no dated inputs (+0)\\")\\n    elif newest <= 14:\\n        score += Decimal(\\"25\\")\\n        reasons.append(f\\"most recent sale is {newest} days old (+25)\\")\\n    elif newest <= 45:\\n        score += Decimal(\\"16\\")\\n        reasons.append(f\\"most recent sale is {newest} days old (+16)\\")\\n    elif newest <= 120:\\n        score += Decimal(\\"7\\")\\n        reasons.append(f\\"most recent sale is {newest} days old, going stale (+7)\\")\\n    else:\\n        reasons.append(f\\"most recent sale is {newest} days old, stale (+0)\\")\\n\\n    if source_count >= 3:\\n        score += Decimal(\\"15\\")\\n        reasons.append(f\\"{source_count} independent sources agree the market exists (+15)\\")\\n    elif source_count == 2:\\n        score += Decimal(\\"9\\")\\n        reasons.append(\\"two independent sources (+9)\\")\\n    else:\\n        score += Decimal(\\"3\\")\\n        reasons.append(\\"single source, no cross-check (+3)\\")\\n\\n    if fair_value.dispersion is None:\\n        reasons.append(\\"dispersion not measurable (+0)\\")\\n    elif fair_value.dispersion < Decimal(\\"0.25\\"):\\n        score += Decimal(\\"15\\")\\n        reasons.append(f\\"tight price agreement, IQR/median {fair_value.dispersion:.2f} (+15)\\")\\n    elif fair_value.dispersion < Decimal(\\"0.5\\"):\\n        score += Decimal(\\"8\\")\\n        reasons.append(f\\"moderate dispersion, IQR/median {fair_value.dispersion:.2f} (+8)\\")\\n    else:\\n        reasons.append(f\\"wide dispersion, IQR/median {fair_value.dispersion:.2f} (+0)\\")\\n\\n    score += match_confidence * Decimal(\\"10\\")\\n    reasons.append(f\\"match confidence {match_confidence} (+{match_confidence * Decimal(\'10\'):.1f})\\")\\n\\n    if condition_dist is not None and condition_dist.is_provisional:\\n        score -= Decimal(\\"8\\")\\n        reasons.append(\\"condition prior is provisional, not calibrated (-8)\\")\\n\\n    if fair_value.excluded:\\n        reasons.append(\\n            f\\"{len(fair_value.excluded)} input(s) excluded or flagged; see provenance\\"\\n        )\\n\\n    return DataQuality(\\n        score=max(Decimal(\\"0\\"), min(Decimal(\\"100\\"), score)).quantize(Decimal(\\"0.1\\")),\\n        reasons=tuple(reasons),\\n        n_sales=n,\\n        oldest_input_age_days=oldest,\\n        newest_input_age_days=newest,\\n        source_count=source_count,\\n    )\\n\\n\\ndef _aware(dt: datetime) -> datetime:\\n    return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass OpportunityAssessment:\\n    suppressed: bool\\n    suppression_reasons: tuple[SuppressionReason, ...]\\n    suppression_detail: tuple[str, ...]\\n    point_roi: Optional[Decimal]\\n    roi_p10: Optional[Decimal]\\n    roi_p25: Optional[Decimal]\\n    roi_median: Optional[Decimal]\\n    ranking_roi: Optional[Decimal]\\n    annualised_roi: Optional[Decimal]\\n    expected_days_to_sell: Optional[Decimal]\\n    data_quality: DataQuality\\n    scores: tuple[Score, ...]\\n\\n    def explain(self) -> str:\\n        if self.suppressed:\\n            head = \\"SUPPRESSED: \\" + \\", \\".join(r.value for r in self.suppression_reasons)\\n            return \\"\\\\n\\".join([head, *(f\\"  {d}\\" for d in self.suppression_detail)])\\n        return \\"\\\\n\\".join(s.explain() for s in self.scores)\\n\\n\\ndef assess_opportunity(\\n    *,\\n    economics: \\"EconomicsFn\\",\\n    gross_resale: Money,\\n    fair_value: FairValue,\\n    liquidity: LiquidityProfile,\\n    condition_dist: Optional[ConditionDistribution],\\n    match_confidence: Decimal,\\n    as_of: datetime,\\n    source_count: int = 1,\\n    config: Optional[RiskConfig] = None,\\n    required_roi: Optional[Decimal] = None,\\n    max_buy_jpy: Optional[Money] = None,\\n    purchase_jpy: Optional[Money] = None,\\n) -> OpportunityAssessment:\\n    \\"\\"\\"Assess one opportunity, suppressing it if any hard gate fails.\\n\\n    ``economics`` is the arbitrage engine\'s own calculation with the buy side\\n    frozen, so profit, ROI and every simulated draw run through the same cost\\n    model that produced the purchase limits. The previous version applied its\\n    own flat assumption that net proceeds were 90 percent of gross resale,\\n    which meant the scored ROI and the engine\'s ROI were different numbers\\n    wearing the same name.\\n    \\"\\"\\"\\n    cfg = config or RiskConfig()\\n    dq = compute_data_quality(\\n        fair_value, as_of=as_of, source_count=source_count,\\n        match_confidence=match_confidence, condition_dist=condition_dist,\\n    )\\n\\n    gates: list[SuppressionReason] = []\\n    detail: list[str] = []\\n\\n    if match_confidence < cfg.min_match_confidence:\\n        gates.append(SuppressionReason.MATCH_CONFIDENCE)\\n        detail.append(\\n            f\\"match confidence {match_confidence} is below the {cfg.min_match_confidence} \\"\\n            \\"floor; the card has not been identified well enough to price\\"\\n        )\\n\\n    if not fair_value.sufficient or fair_value.value is None:\\n        gates.append(SuppressionReason.FAIR_VALUE_INSUFFICIENT)\\n        detail.append(\\n            \\"fair value has insufficient completed-sale evidence; no resale \\"\\n            \\"benchmark means no opportunity, regardless of how cheap the card looks\\"\\n        )\\n\\n    if dq.score < cfg.min_data_quality:\\n        gates.append(SuppressionReason.DATA_QUALITY)\\n        detail.append(f\\"data quality {dq.score} is below the {cfg.min_data_quality} floor\\")\\n\\n    if not liquidity.is_measurable:\\n        if not cfg.allow_unmeasurable_liquidity:\\n            gates.append(SuppressionReason.LIQUIDITY_UNMEASURABLE)\\n            detail.append(\\n                \\"liquidity is not measurable from available sales; an exit route \\"\\n                \\"has not been demonstrated\\"\\n            )\\n    elif liquidity.score is not None and liquidity.score < cfg.min_liquidity_score:\\n        gates.append(SuppressionReason.LIQUIDITY)\\n        detail.append(\\n            f\\"liquidity score {liquidity.score} is below the {cfg.min_liquidity_score} \\"\\n            \\"floor; a wide spread on a card that rarely trades is not a trade\\"\\n        )\\n\\n    cond_conf = (\\n        condition_confidence(condition_dist) if condition_dist is not None else Decimal(\\"0\\")\\n    )\\n    if condition_dist is not None and cond_conf < cfg.min_condition_confidence:\\n        gates.append(SuppressionReason.CONDITION_CONFIDENCE)\\n        detail.append(\\n            f\\"condition confidence {cond_conf} is below the \\"\\n            f\\"{cfg.min_condition_confidence} floor\\"\\n        )\\n\\n    if dq.newest_input_age_days is not None and dq.newest_input_age_days > cfg.max_data_age_days:\\n        gates.append(SuppressionReason.STALE_DATA)\\n        detail.append(\\n            f\\"newest evidence is {dq.newest_input_age_days} days old, past the \\"\\n            f\\"{cfg.max_data_age_days} day ceiling\\"\\n        )\\n\\n    if gates:\\n        return OpportunityAssessment(\\n            True, tuple(gates), tuple(detail), None, None, None, None, None, None,\\n            liquidity.expected_days_to_sell, dq, (),\\n        )\\n\\n    assert fair_value.value is not None\\n    base_econ = economics(gross_resale)\\n    if base_econ.landed.unresolved:\\n        gates.append(SuppressionReason.LANDED_COST_UNRESOLVED)\\n        detail.extend(base_econ.landed.unresolved)\\n        return OpportunityAssessment(\\n            True, tuple(gates), tuple(detail), None, None, None, None, None, None,\\n            liquidity.expected_days_to_sell, dq, (),\\n        )\\n\\n    point_roi = base_econ.roi\\n    cost = base_econ.capital_deployed_eur.amount\\n\\n    # The purchase limit is part of the recommendation, not a display field: a\\n    # price above it cannot clear the required return by construction.\\n    if (\\n        max_buy_jpy is not None\\n        and purchase_jpy is not None\\n        and purchase_jpy.amount > max_buy_jpy.amount\\n    ):\\n        gates.append(SuppressionReason.ABOVE_MAX_BUY)\\n        detail.append(\\n            f\\"asking price {purchase_jpy.amount:.0f} JPY is above the \\"\\n            f\\"{max_buy_jpy.amount:.0f} JPY maximum that clears the required return\\"\\n        )\\n    if required_roi is not None and point_roi < required_roi:\\n        gates.append(SuppressionReason.BELOW_REQUIRED_RETURN)\\n        detail.append(\\n            f\\"expected return {point_roi:.1%} is below the required {required_roi:.1%}\\"\\n        )\\n    if gates:\\n        return OpportunityAssessment(\\n            True, tuple(gates), tuple(detail), None, None, None, None, None, None,\\n            liquidity.expected_days_to_sell, dq, (),\\n        )\\n\\n    rng = random.Random(cfg.random_seed)\\n    # Evidence tightens the fair-value distribution: more sales, less spread.\\n    sigma = cfg.fair_value_rel_sigma / max(1.0, (fair_value.n_sales / 4.0) ** 0.5)\\n    if fair_value.dispersion is not None:\\n        sigma = max(sigma, float(fair_value.dispersion) / 3.0)\\n    cond_penalty = 1.0 - 0.4 * (1.0 - float(cond_conf))\\n\\n    draws: list[float] = []\\n    base = gross_resale.amount\\n    currency = gross_resale.currency\\n    for _ in range(cfg.simulations):\\n        shock = Decimal(str(max(0.05, rng.gauss(1.0, sigma)) * cond_penalty))\\n        # Recalculate through the engine rather than scaling a stored ROI: the\\n        # cost stack has fixed components, so profit is not proportional to the\\n        # resale value and a scaled ROI would overstate the downside tail.\\n        draws.append(float(economics(Money(base * shock, currency)).roi))\\n    draws.sort()\\n\\n    def q(p: float) -> Decimal:\\n        idx = min(len(draws) - 1, max(0, int(p * len(draws))))\\n        return Decimal(str(round(draws[idx], 4)))\\n\\n    ranking_roi = q(cfg.ranking_quantile)\\n    days = liquidity.expected_days_to_sell\\n    annualised = None\\n    if days and days > 0:\\n        annualised = (ranking_roi * Decimal(\\"365\\") / days).quantize(Decimal(\\"0.0001\\"))\\n\\n    scores = (\\n        Score(\\n            \\"Liquidity Score\\",\\n            liquidity.score,\\n            tuple(ScoreReason(r, \\"neutral\\", Decimal(\\"0\\")) for r in liquidity.reasons),\\n        ),\\n        Score(\\n            \\"Data Quality Score\\",\\n            dq.score,\\n            tuple(ScoreReason(r, \\"neutral\\", Decimal(\\"0\\")) for r in dq.reasons),\\n        ),\\n        Score(\\n            \\"Risk Adjusted Opportunity Score\\",\\n            (ranking_roi * Decimal(\\"100\\")).quantize(Decimal(\\"0.1\\")),\\n            (\\n                ScoreReason(\\n                    f\\"ranked on the {int(cfg.ranking_quantile * 100)}th percentile of \\"\\n                    f\\"simulated ROI, not the {point_roi:.1%} point estimate\\",\\n                    \\"down\\" if ranking_roi < point_roi else \\"up\\",\\n                    abs((point_roi - ranking_roi) * Decimal(\\"100\\")).quantize(Decimal(\\"0.1\\")),\\n                ),\\n                ScoreReason(\\n                    f\\"fair value uncertainty sigma {sigma:.3f} from {fair_value.n_sales} sales\\",\\n                    \\"neutral\\", Decimal(\\"0\\"),\\n                ),\\n                ScoreReason(\\n                    f\\"condition confidence {cond_conf} applied as a {(1 - cond_penalty):.1%} haircut\\",\\n                    \\"down\\" if cond_penalty < 1 else \\"neutral\\",\\n                    Decimal(str(round((1 - cond_penalty) * 100, 1))),\\n                ),\\n            ),\\n        ),\\n    )\\n\\n    return OpportunityAssessment(\\n        suppressed=False,\\n        suppression_reasons=(),\\n        suppression_detail=(),\\n        point_roi=point_roi.quantize(Decimal(\\"0.0001\\")),\\n        roi_p10=q(0.10),\\n        roi_p25=q(0.25),\\n        roi_median=q(0.50),\\n        ranking_roi=ranking_roi,\\n        annualised_roi=annualised,\\n        expected_days_to_sell=days,\\n        data_quality=dq,\\n        scores=scores,\\n    )\\n", "pokearb_core/types.py": "\\"\\"\\"Core value objects for PokeArb.\\n\\nDesign rules enforced here:\\n\\n* Money is ``Decimal``. There is no float anywhere in a monetary path.\\n* Anything that can be unknown is ``Optional`` and defaults to ``None``.\\n  ``None`` means \\"not measured\\". It never means zero and it is never imputed.\\n* Every derived quantity carries the evidence used to produce it.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport enum\\nfrom dataclasses import dataclass, field\\nfrom datetime import date, datetime\\nfrom decimal import Decimal\\nfrom typing import Mapping, Optional, Sequence\\n\\n__all__ = [\\n    \\"Currency\\",\\n    \\"Language\\",\\n    \\"Edition\\",\\n    \\"Printing\\",\\n    \\"EuCondition\\",\\n    \\"EU_CONDITION_LADDER\\",\\n    \\"Grader\\",\\n    \\"Scenario\\",\\n    \\"AcquisitionPurpose\\",\\n    \\"ValueBasis\\",\\n    \\"Unknown\\",\\n    \\"UNKNOWN\\",\\n    \\"Money\\",\\n    \\"FxRate\\",\\n    \\"CardVariant\\",\\n    \\"Sale\\",\\n    \\"Listing\\",\\n    \\"MarketAverage\\",\\n    \\"PopulationSnapshot\\",\\n    \\"ConditionDistribution\\",\\n    \\"FairValue\\",\\n    \\"EvidenceRef\\",\\n    \\"DataQuality\\",\\n]\\n\\n\\nclass Currency(str, enum.Enum):\\n    JPY = \\"JPY\\"\\n    EUR = \\"EUR\\"\\n    DKK = \\"DKK\\"\\n    USD = \\"USD\\"\\n    GBP = \\"GBP\\"\\n\\n\\n#: Currencies with no minor unit. Rounding differs.\\nZERO_DECIMAL_CURRENCIES = frozenset({Currency.JPY})\\n\\n\\nclass Language(str, enum.Enum):\\n    JA = \\"ja\\"\\n    EN = \\"en\\"\\n    DE = \\"de\\"\\n    FR = \\"fr\\"\\n    IT = \\"it\\"\\n    ES = \\"es\\"\\n    PT = \\"pt\\"\\n    KO = \\"ko\\"\\n    ZH_HANT = \\"zh-Hant\\"\\n\\n\\nclass Edition(str, enum.Enum):\\n    FIRST = \\"1st\\"\\n    UNLIMITED = \\"unlimited\\"\\n    SHADOWLESS = \\"shadowless\\"\\n    NOT_APPLICABLE = \\"n/a\\"\\n\\n\\nclass Printing(str, enum.Enum):\\n    NON_HOLO = \\"non-holo\\"\\n    HOLO = \\"holo\\"\\n    REVERSE_HOLO = \\"reverse-holo\\"\\n    TEXTURED = \\"textured\\"\\n    FOIL_OTHER = \\"foil-other\\"\\n\\n\\nclass EuCondition(str, enum.Enum):\\n    \\"\\"\\"European marketplace condition ladder, best to worst.\\"\\"\\"\\n\\n    NM = \\"NM\\"\\n    EX = \\"EX\\"\\n    GD = \\"GD\\"\\n    LP = \\"LP\\"\\n    PL = \\"PL\\"\\n    PO = \\"PO\\"\\n\\n\\n#: Canonical ordering, best first. Used by entropy and monotonicity checks.\\nEU_CONDITION_LADDER: tuple[EuCondition, ...] = (\\n    EuCondition.NM,\\n    EuCondition.EX,\\n    EuCondition.GD,\\n    EuCondition.LP,\\n    EuCondition.PL,\\n    EuCondition.PO,\\n)\\n\\n\\nclass Grader(str, enum.Enum):\\n    PSA = \\"PSA\\"\\n    CGC = \\"CGC\\"\\n    BGS = \\"BGS\\"\\n    ACE = \\"ACE\\"\\n    TAG = \\"TAG\\"\\n\\n\\nclass Scenario(str, enum.Enum):\\n    \\"\\"\\"Acquisition scenarios from the brief.\\"\\"\\"\\n\\n    HAND_CARRY = \\"A_hand_carry\\"\\n    SHIPPED = \\"B_shipped\\"\\n    PROXY = \\"C_proxy\\"\\n\\n\\nclass AcquisitionPurpose(str, enum.Enum):\\n    \\"\\"\\"Why the goods are being imported.\\n\\n    This is not a cosmetic label. Danish relief for travellers\' goods applies\\n    only to goods for private use, and goods imported with a view to resale are\\n    expressly outside it, so the purpose decides whether the allowance and the\\n    Japanese departure refund may be modelled at all. Verified at\\n    https://info.skat.dk/data.aspx?oid=2230232 (F.A.29 Rejsegods): the relief\\n    covers goods for private use, requires the import to be of non-commercial\\n    character, and goods cannot be treated as for own use when imported with a\\n    view to resale.\\n\\n    ``RESALE`` is the default because this is an arbitrage system. Choosing\\n    ``PERSONAL`` is an assertion about the user\'s own facts, not a modelling\\n    switch, and it is recorded in the result.\\n    \\"\\"\\"\\n\\n    RESALE = \\"resale\\"\\n    PERSONAL = \\"personal\\"\\n\\n\\nclass ValueBasis(str, enum.Enum):\\n    \\"\\"\\"Whether a per-condition value was measured or derived from a model.\\"\\"\\"\\n\\n    OBSERVED = \\"observed\\"\\n    MODELLED = \\"modelled\\"\\n\\n\\nclass Unknown:\\n    \\"\\"\\"Sentinel distinct from ``None``.\\n\\n    ``None`` is used for optional fields that were simply never populated.\\n    ``UNKNOWN`` is returned by engines to say \\"I looked and the evidence does\\n    not support producing a number\\". The two are deliberately different so that\\n    a UI can say \\"not measured\\" versus \\"insufficient evidence\\".\\n    \\"\\"\\"\\n\\n    _instance: Optional[\\"Unknown\\"] = None\\n\\n    def __new__(cls) -> \\"Unknown\\":\\n        if cls._instance is None:\\n            cls._instance = super().__new__(cls)\\n        return cls._instance\\n\\n    def __bool__(self) -> bool:  # pragma: no cover - trivial\\n        return False\\n\\n    def __repr__(self) -> str:  # pragma: no cover - trivial\\n        return \\"UNKNOWN\\"\\n\\n\\nUNKNOWN = Unknown()\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass Money:\\n    \\"\\"\\"An exact monetary amount in a single currency.\\"\\"\\"\\n\\n    amount: Decimal\\n    currency: Currency\\n\\n    def __post_init__(self) -> None:\\n        if not isinstance(self.amount, Decimal):\\n            raise TypeError(\\n                f\\"Money.amount must be Decimal, got {type(self.amount).__name__}. \\"\\n                \\"Floats are rejected to keep monetary arithmetic exact.\\"\\n            )\\n\\n    def _check(self, other: \\"Money\\") -> None:\\n        if self.currency is not other.currency:\\n            raise ValueError(\\n                f\\"Refusing to combine {self.currency.value} and \\"\\n                f\\"{other.currency.value} without an explicit FX conversion.\\"\\n            )\\n\\n    def __add__(self, other: \\"Money\\") -> \\"Money\\":\\n        self._check(other)\\n        return Money(self.amount + other.amount, self.currency)\\n\\n    def __sub__(self, other: \\"Money\\") -> \\"Money\\":\\n        self._check(other)\\n        return Money(self.amount - other.amount, self.currency)\\n\\n    def __mul__(self, factor: Decimal | int) -> \\"Money\\":\\n        return Money(self.amount * Decimal(factor), self.currency)\\n\\n    def __lt__(self, other: \\"Money\\") -> bool:\\n        self._check(other)\\n        return self.amount < other.amount\\n\\n    def __le__(self, other: \\"Money\\") -> bool:\\n        self._check(other)\\n        return self.amount <= other.amount\\n\\n    @classmethod\\n    def of(cls, amount: str | int | Decimal, currency: Currency) -> \\"Money\\":\\n        return cls(Decimal(str(amount)), currency)\\n\\n    def quantize(self) -> \\"Money\\":\\n        exp = Decimal(\\"1\\") if self.currency in ZERO_DECIMAL_CURRENCIES else Decimal(\\"0.01\\")\\n        return Money(self.amount.quantize(exp), self.currency)\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass FxRate:\\n    \\"\\"\\"A dated FX rate. Dated so historical calculations reproduce exactly.\\"\\"\\"\\n\\n    as_of: date\\n    base: Currency\\n    quote: Currency\\n    rate: Decimal\\n    source_url: str\\n\\n    def convert(self, money: Money) -> Money:\\n        if money.currency is not self.base:\\n            raise ValueError(\\n                f\\"Rate is {self.base.value}->{self.quote.value}, \\"\\n                f\\"cannot convert {money.currency.value}.\\"\\n            )\\n        return Money(money.amount * self.rate, self.quote)\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass CardVariant:\\n    \\"\\"\\"The canonical tradeable printing.\\n\\n    ``canonical_key`` is derived, never supplied. Two variants are the same card\\n    if and only if their canonical keys are equal.\\n    \\"\\"\\"\\n\\n    variant_id: str\\n    language: Language\\n    set_code: str\\n    number: str\\n    printing: Printing\\n    edition: Edition = Edition.NOT_APPLICABLE\\n    stamp: Optional[str] = None\\n    name_en: Optional[str] = None\\n    name_ja: Optional[str] = None\\n    pokemon_slug: Optional[str] = None\\n    series: Optional[str] = None\\n    year: Optional[int] = None\\n    illustrator: Optional[str] = None\\n    artwork_id: Optional[str] = None\\n    release_method: Optional[str] = None\\n    region: Optional[str] = None\\n    sibling_variant_ids: tuple[str, ...] = ()\\n\\n    @property\\n    def canonical_key(self) -> str:\\n        from .identity.canonical import build_canonical_key\\n\\n        return build_canonical_key(self)\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass EvidenceRef:\\n    \\"\\"\\"Pointer back to the record that justified a number.\\"\\"\\"\\n\\n    kind: str  # \\"sale\\" | \\"listing\\" | \\"population\\" | \\"fx\\" | \\"policy\\"\\n    record_id: str\\n    source_id: str\\n    source_url: Optional[str]\\n    observed_at: datetime\\n    weight: Optional[Decimal] = None\\n    note: Optional[str] = None\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass Sale:\\n    \\"\\"\\"A completed transaction. The only permitted fair-value input.\\"\\"\\"\\n\\n    sale_id: str\\n    variant_id: str\\n    source_id: str\\n    sold_at: datetime\\n    price: Money\\n    condition: Optional[EuCondition]\\n    language: Language\\n    source_url: Optional[str] = None\\n    is_graded: bool = False\\n    grader: Optional[Grader] = None\\n    grade: Optional[Decimal] = None\\n    shipping_included: bool = False\\n    condition_confidence: Decimal = Decimal(\\"1.0\\")\\n    #: Market the transaction happened in (\\"EU\\", \\"JP\\", ...). A Japanese sale is\\n    #: evidence of a Japanese price, never of a European resale price, so this\\n    #: is a scoping key and not decoration.\\n    market: Optional[str] = None\\n    #: The source\'s own stable identifier for the transaction. Deduplication\\n    #: keys on this: re-importing the same file must not manufacture evidence.\\n    external_id: Optional[str] = None\\n    #: When this sale became known to us. Distinct from ``sold_at``. A\\n    #: historical calculation may only use evidence that had arrived by the\\n    #: calculation date, and filtering on the transaction date alone does not\\n    #: achieve that.\\n    known_at: Optional[datetime] = None\\n\\n    @property\\n    def grade_bucket(self) -> str:\\n        \\"\\"\\"Valuation bucket. Raw, and each grader/grade pair, price separately.\\"\\"\\"\\n        if not self.is_graded:\\n            return \\"raw\\"\\n        grader = self.grader.value if self.grader else \\"unknown_grader\\"\\n        # format(..., \\"f\\") rather than normalize(): Decimal(\\"10\\").normalize()\\n        # renders as 1E+1, which would make \\"psa:10\\" and \\"psa:1E+1\\" different\\n        # buckets for the same grade.\\n        grade = format(self.grade, \\"f\\") if self.grade is not None else \\"unknown_grade\\"\\n        return f\\"{grader}:{grade}\\"\\n\\n    @property\\n    def dedupe_key(self) -> tuple[str, str]:\\n        \\"\\"\\"Stable transaction identity used to count independent sales.\\"\\"\\"\\n        return (self.source_id, self.external_id or self.sale_id)\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass Listing:\\n    \\"\\"\\"An active offer. Never a fair-value input.\\"\\"\\"\\n\\n    listing_id: str\\n    variant_id: str\\n    source_id: str\\n    observed_at: datetime\\n    price: Money\\n    condition: Optional[EuCondition]\\n    language: Language\\n    source_url: Optional[str] = None\\n    seller_id: Optional[str] = None\\n    is_graded: bool = False\\n    grader: Optional[Grader] = None\\n    grade: Optional[Decimal] = None\\n    quantity: int = 1\\n    #: Market the offer sits in (\\"EU\\", \\"JP\\", ...). European supply and European\\n    #: liquidity may only be measured from European listings.\\n    market: Optional[str] = None\\n    #: The source\'s own listing identifier. Successive observations of one\\n    #: listing share it, which is what stops a repriced listing from being\\n    #: counted as two independent offers.\\n    external_id: Optional[str] = None\\n\\n    @property\\n    def grade_bucket(self) -> str:\\n        if not self.is_graded:\\n            return \\"raw\\"\\n        grader = self.grader.value if self.grader else \\"unknown_grader\\"\\n        grade = format(self.grade, \\"f\\") if self.grade is not None else \\"unknown_grade\\"\\n        return f\\"{grader}:{grade}\\"\\n\\n    @property\\n    def dedupe_key(self) -> tuple[str, str]:\\n        return (self.source_id, self.external_id or self.listing_id)\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass MarketAverage:\\n    \\"\\"\\"A marketplace\'s own published price averages for one card.\\n\\n    Distinct from ``Sale`` on purpose, and never convertible into one. An\\n    average says nothing about how many transactions produced it: a 30-day\\n    average built from one sale looks exactly like one built from two hundred.\\n    The valuation code therefore treats this as a different, weaker kind of\\n    evidence with its own acceptance rules, see\\n    ``pokearb_core.valuation.benchmark``.\\n\\n    Price fields are ``None`` when the provider did not publish a usable\\n    figure. A published zero is also stored as ``None``: a Cardmarket average\\n    of exactly zero means \\"no data\\", not \\"free\\".\\n    \\"\\"\\"\\n\\n    variant_id: str\\n    provider: str                  # \\"cardmarket\\"\\n    via: str                       # \\"tcgdex\\": who relayed the provider\'s figures\\n    product_id: Optional[str]      # the provider\'s own product id, for collision checks\\n    finish: str                    # \\"base\\" or \\"reverse\\": which set of fields was read\\n    currency: Currency\\n    provider_updated_at: datetime  # when the provider last recomputed the figures\\n    known_at: datetime             # when we fetched them; the look-ahead boundary\\n    avg: Optional[Decimal] = None\\n    low: Optional[Decimal] = None\\n    trend: Optional[Decimal] = None\\n    avg1: Optional[Decimal] = None\\n    avg7: Optional[Decimal] = None\\n    avg30: Optional[Decimal] = None\\n    market: str = \\"EU\\"\\n    language: Optional[Language] = None\\n    source_url: Optional[str] = None\\n    raw_hash: Optional[str] = None\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass PopulationSnapshot:\\n    \\"\\"\\"Dated grade-ladder snapshot.\\n\\n    Every count is optional. A missing count is ``None``, which means the figure\\n    was not retrieved. It is never rendered as zero.\\n    \\"\\"\\"\\n\\n    variant_id: str\\n    grader: Grader\\n    observed_at: datetime\\n    source_url: Optional[str]\\n    total: Optional[int] = None\\n    grade_10: Optional[int] = None\\n    grade_9: Optional[int] = None\\n    grade_8: Optional[int] = None\\n    grade_7_and_below: Optional[int] = None\\n\\n    @property\\n    def gem_rate(self) -> Optional[Decimal]:\\n        if self.total is None or self.grade_10 is None or self.total == 0:\\n            return None\\n        return Decimal(self.grade_10) / Decimal(self.total)\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ConditionDistribution:\\n    \\"\\"\\"Posterior probability over the European condition ladder.\\"\\"\\"\\n\\n    probabilities: Mapping[EuCondition, Decimal]\\n    evidence_n: int\\n    is_provisional: bool\\n    source_grade_label: Optional[str] = None\\n    source_id: Optional[str] = None\\n    notes: tuple[str, ...] = ()\\n\\n    def __post_init__(self) -> None:\\n        total = sum(self.probabilities.values())\\n        if abs(total - Decimal(\\"1\\")) > Decimal(\\"0.0001\\"):\\n            raise ValueError(f\\"Condition probabilities must sum to 1, got {total}.\\")\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass DataQuality:\\n    \\"\\"\\"Explainable data-quality assessment attached to every opportunity.\\"\\"\\"\\n\\n    score: Decimal  # 0..100\\n    reasons: tuple[str, ...]\\n    n_sales: int\\n    oldest_input_age_days: Optional[int]\\n    newest_input_age_days: Optional[int]\\n    source_count: int\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass FairValue:\\n    \\"\\"\\"A fair-value estimate, or an explicit statement that there is not one.\\"\\"\\"\\n\\n    window_days: Optional[int]\\n    value: Optional[Money]\\n    sufficient: bool\\n    n_sales: int\\n    n_effective: Decimal\\n    dispersion: Optional[Decimal]  # IQR / median\\n    method: str\\n    inputs: tuple[EvidenceRef, ...] = ()\\n    excluded: tuple[EvidenceRef, ...] = ()\\n    notes: tuple[str, ...] = ()\\n\\n    @property\\n    def is_unknown(self) -> bool:\\n        return not self.sufficient or self.value is None\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass SupplySnapshot:\\n    variant_id: str\\n    market: str  # \\"EU\\" | \\"JP\\"\\n    observed_at: datetime\\n    active_listings: Optional[int] = None\\n    lowest: Optional[Money] = None\\n    median: Optional[Money] = None\\n    graded_listings: Optional[int] = None\\n    raw_listings: Optional[int] = None\\n    source_urls: tuple[str, ...] = field(default_factory=tuple)\\n", "pokearb_core/valuation/__init__.py": "\\"\\"\\"PokeArb core subpackage.\\"\\"\\"\\n", "pokearb_core/valuation/benchmark.py": "\\"\\"\\"Resale value from a marketplace\'s published averages.\\n\\nThis is the second-best evidence the system accepts, and it is kept apart from\\nthe first. ``compute_fair_value`` values a card from individual completed\\nsales and knows how many there were. A published average does not say how\\nmany sales produced it, so it gets its own path, its own rules, and a label\\nthat follows it all the way to the verdict.\\n\\nThe rules below are judgement, not findings. Each is a conservatism choice:\\nwhen in doubt it refuses, because the brief ranks a false signal as worse\\nthan a missed trade. All thresholds live in ``BenchmarkConfig``.\\n\\n1. **No look-ahead.** An observation fetched after the calculation time is\\n   excluded, the same rule completed sales follow.\\n2. **Fresh.** The provider recomputes daily; figures older than\\n   ``max_age_days`` are refused.\\n3. **Mapping must be checkable, and must check out.** TCGdex documents that\\n   different printings of one Pokemon can be mapped to the same Cardmarket\\n   listing (https://tcgdex.dev/faq). An observation with no product id cannot\\n   be checked and is refused; one whose product id is shared by a same-name\\n   sibling in the set is refused as a collision.\\n4. **The figures must agree with each other.** If the average, trend, 7-day\\n   and 30-day averages spread by more than ``max_spread`` of the largest, the\\n   market is thin or moving, and no single number describes it.\\n5. **The value is the lowest of the 7-day average, the 30-day average and the\\n   trend.** Not their mean: the lowest, so that a benchmark can only ever\\n   understate what a card sells for.\\n\\nThe value is treated as a near-mint equivalent. If Cardmarket\'s averages in\\nfact include worse-condition copies, the true near-mint price is higher than\\nthis figure, so the downstream condition adjustment errs on the low side,\\nwhich is the intended direction.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import dataclass, field\\nfrom datetime import datetime, timedelta, timezone\\nfrom decimal import Decimal\\nfrom typing import Optional, Sequence\\n\\nfrom ..types import Currency, MarketAverage, Money\\n\\n__all__ = [\\n    \\"BASIS\\",\\n    \\"BenchmarkConfig\\",\\n    \\"MarketBenchmark\\",\\n    \\"assess_market_average\\",\\n]\\n\\n#: The label every average-based number carries, from here to the response.\\nBASIS = \\"cardmarket_average_via_tcgdex\\"\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass BenchmarkConfig:\\n    max_spread: Decimal = Decimal(\\"0.30\\")\\n    max_age_days: int = 3\\n    min_points: int = 2\\n    #: Upper bound on any confidence derived from an average. Averages carry no\\n    #: sample size, so they can never be as trustworthy as counted sales.\\n    confidence_cap: Decimal = Decimal(\\"0.50\\")\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass MarketBenchmark:\\n    accepted: bool\\n    value: Optional[Money]\\n    basis: str\\n    statistic: Optional[str]\\n    spread: Optional[Decimal]\\n    confidence_cap: Decimal\\n    observation: Optional[MarketAverage]\\n    reasons: tuple[str, ...] = field(default_factory=tuple)\\n\\n    @property\\n    def refused(self) -> bool:\\n        return not self.accepted\\n\\n\\ndef _aware(ts: datetime) -> datetime:\\n    return ts if ts.tzinfo else ts.replace(tzinfo=timezone.utc)\\n\\n\\ndef assess_market_average(\\n    observation: Optional[MarketAverage],\\n    *,\\n    as_of: datetime,\\n    sibling_product_ids: Optional[Sequence[str]],\\n    parser_reasons: Sequence[str] = (),\\n    config: Optional[BenchmarkConfig] = None,\\n) -> MarketBenchmark:\\n    \\"\\"\\"Accept or refuse one published average, and say exactly why.\\n\\n    ``sibling_product_ids`` is the list of Cardmarket product ids held by other\\n    cards of the same name in the same set. ``None`` means the check could not\\n    be run, which is itself grounds for refusal: an unchecked mapping is not a\\n    clean one.\\n    \\"\\"\\"\\n    cfg = config or BenchmarkConfig()\\n    as_of = _aware(as_of)\\n\\n    def refuse(*why: str) -> MarketBenchmark:\\n        return MarketBenchmark(\\n            accepted=False, value=None, basis=BASIS, statistic=None,\\n            spread=None, confidence_cap=cfg.confidence_cap,\\n            observation=observation, reasons=tuple(parser_reasons) + why,\\n        )\\n\\n    if observation is None:\\n        return refuse() if parser_reasons else refuse(\\"no observation\\")\\n\\n    obs = observation\\n    if _aware(obs.known_at) > as_of:\\n        return refuse(\\n            f\\"figures were fetched at {obs.known_at.isoformat()}, after the \\"\\n            \\"calculation time; excluded to prevent look-ahead\\"\\n        )\\n    updated = _aware(obs.provider_updated_at)\\n    if updated > as_of:\\n        return refuse(\\"provider timestamp is after the calculation time\\")\\n    age = as_of - updated\\n    if age > timedelta(days=cfg.max_age_days):\\n        return refuse(\\n            f\\"Cardmarket figures are {age.days} days old; the provider \\"\\n            f\\"updates daily and anything over {cfg.max_age_days} days is stale\\"\\n        )\\n\\n    if not obs.product_id:\\n        return refuse(\\n            \\"no Cardmarket product id, so the mapping to this exact printing \\"\\n            \\"cannot be checked\\"\\n        )\\n    if sibling_product_ids is None:\\n        return refuse(\\n            \\"the same-name sibling check could not be run, so a mapping \\"\\n            \\"collision cannot be ruled out\\"\\n        )\\n    if obs.product_id in set(sibling_product_ids):\\n        return refuse(\\n            f\\"Cardmarket product {obs.product_id} is also mapped to another \\"\\n            \\"printing of the same Pokemon in this set, the defect TCGdex \\"\\n            \\"documents at https://tcgdex.dev/faq; the price could belong to \\"\\n            \\"either card\\"\\n        )\\n\\n    core = {\\"7-day average\\": obs.avg7, \\"30-day average\\": obs.avg30, \\"trend\\": obs.trend}\\n    present = {k: v for k, v in core.items() if v is not None}\\n    if len(present) < cfg.min_points:\\n        return refuse(\\n            f\\"only {len(present)} of the 7-day average, 30-day average and trend \\"\\n            f\\"are published; at least {cfg.min_points} are required\\"\\n        )\\n\\n    spread_inputs = [v for v in (obs.avg, obs.trend, obs.avg7, obs.avg30) if v is not None]\\n    top = max(spread_inputs)\\n    spread = (top - min(spread_inputs)) / top if top > 0 else Decimal(\\"0\\")\\n    if spread > cfg.max_spread:\\n        figures = \\", \\".join(\\n            f\\"{name} {value}\\" for name, value in (\\n                (\\"avg\\", obs.avg), (\\"trend\\", obs.trend),\\n                (\\"7-day\\", obs.avg7), (\\"30-day\\", obs.avg30),\\n            ) if value is not None\\n        )\\n        return refuse(\\n            f\\"published figures disagree by {spread:.0%} ({figures}); a market \\"\\n            \\"this thin or fast-moving has no single price worth relying on\\"\\n        )\\n\\n    name, value = min(present.items(), key=lambda kv: kv[1])\\n    return MarketBenchmark(\\n        accepted=True,\\n        value=Money(value, Currency.EUR).quantize(),\\n        basis=BASIS,\\n        statistic=f\\"lowest of the published {\', \'.join(present)}: the {name}\\",\\n        spread=spread.quantize(Decimal(\\"0.0001\\")),\\n        confidence_cap=cfg.confidence_cap,\\n        observation=obs,\\n        reasons=tuple(parser_reasons) + (\\n            \\"Cardmarket averages relayed by TCGdex, not individual sales; the \\"\\n            \\"number of sales behind them is unknown\\",\\n            f\\"figures agree within {spread:.0%}\\",\\n        ),\\n    )\\n", "pokearb_core/valuation/fair_value.py": "\\"\\"\\"Fair value from completed sales only.\\n\\nNon-negotiable rules encoded here:\\n\\n* **Only completed sales.** The function does not accept listings. There is no\\n  parameter that would let one in. The brief\'s Test 4 (one absurd listing must\\n  not become fair value) is satisfied by the type signature, not by a check.\\n* **Below the minimum evidence count, there is no number.** The window returns\\n  ``sufficient=False``. It does not return a wide interval or a shaky point\\n  estimate, because a shaky point estimate is what gets spent at a counter.\\n* **Outliers are down-weighted and recorded, never deleted.** A 790 EUR sale\\n  among 180 EUR sales is suspicious in both directions: it might be a different\\n  variant, and so might a suspiciously cheap one.\\n* **Every returned value carries the sales that produced it**, with weights, so\\n  the UI can show the working.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport math\\nfrom dataclasses import dataclass\\nfrom datetime import datetime, timedelta, timezone\\nfrom decimal import Decimal, InvalidOperation\\nfrom typing import Mapping, Optional, Sequence\\n\\nfrom ..types import (\\n    Currency,\\n    EuCondition,\\n    EU_CONDITION_LADDER,\\n    EvidenceRef,\\n    FairValue,\\n    FxRate,\\n    Language,\\n    Money,\\n    Sale,\\n    ValueBasis,\\n)\\n\\n__all__ = [\\n    \\"FairValueConfig\\",\\n    \\"ConditionValue\\",\\n    \\"ConditionValueCurve\\",\\n    \\"compute_fair_value\\",\\n    \\"compute_fair_value_curve\\",\\n    \\"condition_value_curve\\",\\n    \\"weighted_median\\",\\n    \\"mad_outliers\\",\\n    \\"DEFAULT_CONDITION_MULTIPLIERS\\",\\n]\\n\\n#: Multipliers converting a sale at condition C to an NM-equivalent price.\\n#: These are a documented starting prior, not a measurement. The calibration\\n#: job replaces them per category with estimates from observed data, and the\\n#: resulting fair value records which source was used in ``method``.\\nDEFAULT_CONDITION_MULTIPLIERS: Mapping[EuCondition, Decimal] = {\\n    EuCondition.NM: Decimal(\\"1.00\\"),\\n    EuCondition.EX: Decimal(\\"0.85\\"),\\n    EuCondition.GD: Decimal(\\"0.72\\"),\\n    EuCondition.LP: Decimal(\\"0.62\\"),\\n    EuCondition.PL: Decimal(\\"0.45\\"),\\n    EuCondition.PO: Decimal(\\"0.28\\"),\\n}\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass FairValueConfig:\\n    \\"\\"\\"Tuning knobs. Defaults lean conservative in every direction.\\"\\"\\"\\n\\n    #: Minimum Kish effective sample size before a window produces a number.\\n    #: Kish n_eff = (sum w)^2 / sum(w^2). For equally-weighted sales this equals\\n    #: the raw count; when one ancient or unreliable sale dominates the weights\\n    #: it collapses toward 1, which is exactly the situation where a point\\n    #: estimate should not be produced.\\n    min_effective_sales: Decimal = Decimal(\\"2.5\\")\\n    #: Minimum raw sale count regardless of weights.\\n    min_raw_sales: int = 3\\n    #: Recency half-life in days. Newer sales dominate without one sale\\n    #: being able to move the median on its own.\\n    half_life_days: Decimal = Decimal(\\"21\\")\\n    #: Median-absolute-deviation multiplier for outlier flagging.\\n    mad_k: Decimal = Decimal(\\"3.5\\")\\n    #: Reliability weight per source id. Unlisted sources get this default.\\n    default_source_reliability: Decimal = Decimal(\\"0.7\\")\\n    source_reliability: Mapping[str, Decimal] = None  # type: ignore[assignment]\\n    condition_multipliers: Mapping[EuCondition, Decimal] = None  # type: ignore[assignment]\\n    #: Sales with condition unknown are down-weighted rather than dropped,\\n    #: because dropping them biases toward whichever conditions get stated.\\n    unknown_condition_weight: Decimal = Decimal(\\"0.35\\")\\n    target_currency: Currency = Currency.EUR\\n\\n    def __post_init__(self) -> None:\\n        if self.source_reliability is None:\\n            object.__setattr__(self, \\"source_reliability\\", {})\\n        if self.condition_multipliers is None:\\n            object.__setattr__(\\n                self, \\"condition_multipliers\\", dict(DEFAULT_CONDITION_MULTIPLIERS)\\n            )\\n\\n\\ndef weighted_median(pairs: Sequence[tuple[Decimal, Decimal]]) -> Optional[Decimal]:\\n    \\"\\"\\"Weighted median of ``(value, weight)`` pairs.\\n\\n    Used instead of a mean throughout. A mean lets one bad print run, one fake,\\n    or one auction-sniping accident move the number that gets spent.\\n    \\"\\"\\"\\n    usable = [(v, w) for v, w in pairs if w > 0]\\n    if not usable:\\n        return None\\n    usable.sort(key=lambda p: p[0])\\n    total = sum(w for _, w in usable)\\n    half = total / Decimal(\\"2\\")\\n    running = Decimal(\\"0\\")\\n    for value, weight in usable:\\n        running += weight\\n        if running >= half:\\n            return value\\n    return usable[-1][0]\\n\\n\\ndef _median(values: Sequence[Decimal]) -> Optional[Decimal]:\\n    if not values:\\n        return None\\n    ordered = sorted(values)\\n    n = len(ordered)\\n    mid = n // 2\\n    if n % 2:\\n        return ordered[mid]\\n    return (ordered[mid - 1] + ordered[mid]) / Decimal(\\"2\\")\\n\\n\\ndef mad_outliers(\\n    values: Sequence[Decimal], k: Decimal = Decimal(\\"3.5\\")\\n) -> tuple[frozenset[int], Optional[Decimal], Optional[Decimal]]:\\n    \\"\\"\\"Flag outliers by median absolute deviation.\\n\\n    Returns ``(indices, median, mad)``. Both tails are flagged: a suspiciously\\n    low sale usually means wrong variant, damage, or a counterfeit, and is at\\n    least as dangerous as a high one because it drags fair value down.\\n    \\"\\"\\"\\n    med = _median(values)\\n    if med is None or len(values) < 4:\\n        return frozenset(), med, None\\n    deviations = [abs(v - med) for v in values]\\n    mad = _median(deviations)\\n    if mad is None or mad == 0:\\n        return frozenset(), med, mad\\n    # 1.4826 scales MAD to a normal-consistent standard deviation estimate.\\n    scaled = mad * Decimal(\\"1.4826\\")\\n    flagged = {\\n        i for i, v in enumerate(values) if abs(v - med) > k * scaled\\n    }\\n    return frozenset(flagged), med, mad\\n\\n\\ndef _recency_weight(age_days: Decimal, half_life: Decimal) -> Decimal:\\n    if half_life <= 0:\\n        return Decimal(\\"1\\")\\n    try:\\n        decay = Decimal(str(math.pow(0.5, float(age_days / half_life))))\\n    except (InvalidOperation, ValueError, OverflowError):  # pragma: no cover\\n        return Decimal(\\"0\\")\\n    return max(Decimal(\\"0\\"), decay)\\n\\n\\ndef _to_target(\\n    sale: Sale, fx: Mapping[tuple[Currency, Currency], FxRate], target: Currency\\n) -> Optional[Money]:\\n    if sale.price.currency is target:\\n        return sale.price\\n    rate = fx.get((sale.price.currency, target))\\n    if rate is None:\\n        return None\\n    return rate.convert(sale.price)\\n\\n\\ndef compute_fair_value(\\n    sales: Sequence[Sale],\\n    *,\\n    variant_id: str,\\n    as_of: datetime,\\n    window_days: Optional[int],\\n    fx_rates: Optional[Mapping[tuple[Currency, Currency], FxRate]] = None,\\n    config: Optional[FairValueConfig] = None,\\n    normalize_to: EuCondition = EuCondition.NM,\\n    grade_bucket: str = \\"raw\\",\\n    market: Optional[str] = None,\\n    language: Optional[Language] = None,\\n) -> FairValue:\\n    \\"\\"\\"Compute condition-normalised fair value for one variant in one window.\\n\\n    ``sales`` must already be restricted to a single variant; the function\\n    asserts rather than silently filtering, because a caller that passes mixed\\n    variants has a bug worth surfacing loudly.\\n\\n    ``grade_bucket``, ``market`` and ``language`` are the other three scoping\\n    keys and they are enforced here rather than trusted to the caller. A PSA 10\\n    is a different asset from the raw card and from a PSA 9; a Japanese sale is\\n    evidence of a Japanese price and not of a European resale price. Sales\\n    outside the scope are recorded in ``excluded`` with the reason, not dropped\\n    silently.\\n    \\"\\"\\"\\n    cfg = config or FairValueConfig()\\n    fx = fx_rates or {}\\n\\n    if as_of.tzinfo is None:\\n        as_of = as_of.replace(tzinfo=timezone.utc)\\n\\n    scoped = [s for s in sales if s.variant_id == variant_id]\\n    if len(scoped) != len(sales):\\n        raise ValueError(\\n            \\"compute_fair_value received sales for more than one variant. \\"\\n            \\"Cross-variant pooling is never permitted.\\"\\n        )\\n\\n    cutoff = as_of - timedelta(days=window_days) if window_days else None\\n    notes: list[str] = []\\n\\n    prepared: list[tuple[Sale, Decimal, Decimal, EvidenceRef]] = []\\n    excluded: list[EvidenceRef] = []\\n    seen_identity: set[tuple[str, str]] = set()\\n    seen_fingerprint: set[tuple[str, str, str, str]] = set()\\n\\n    def drop(sale: Sale, when: datetime, reason: str) -> None:\\n        excluded.append(\\n            EvidenceRef(\\n                \\"sale\\", sale.sale_id, sale.source_id, sale.source_url, when,\\n                Decimal(\\"0\\"), reason,\\n            )\\n        )\\n\\n    for sale in scoped:\\n        sold_at = sale.sold_at if sale.sold_at.tzinfo else sale.sold_at.replace(tzinfo=timezone.utc)\\n\\n        # Scope first. A price only counts as evidence for the thing it is\\n        # evidence of: the same grade bucket, the same market, the same\\n        # language. A PSA 10 is not a raw card and a Tokyo sale is not a\\n        # European resale benchmark.\\n        if sale.grade_bucket != grade_bucket:\\n            drop(sale, sold_at,\\n                 f\\"grade bucket {sale.grade_bucket} is not {grade_bucket}; \\"\\n                 \\"raw and each grader/grade combination price separately\\")\\n            continue\\n        if market is not None and (sale.market or \\"\\").upper() != market.upper():\\n            drop(sale, sold_at,\\n                 f\\"market {sale.market or \'unknown\'} is not {market}; \\"\\n                 \\"out-of-market sales are not resale evidence for this market\\")\\n            continue\\n        if language is not None and sale.language is not language:\\n            drop(sale, sold_at,\\n                 f\\"language {sale.language.value} is not {language.value}\\")\\n            continue\\n\\n        # Known-at. Filtering on the transaction date alone lets a backtest use\\n        # a sale that had not yet been published on the calculation date.\\n        known_at = sale.known_at or sold_at\\n        if known_at.tzinfo is None:\\n            known_at = known_at.replace(tzinfo=timezone.utc)\\n        if known_at > as_of:\\n            drop(sale, sold_at,\\n                 f\\"evidence became known at {known_at.isoformat()}, after the \\"\\n                 \\"calculation time; excluded to prevent look-ahead\\")\\n            continue\\n\\n        if cutoff and sold_at < cutoff:\\n            continue\\n        if sold_at > as_of:\\n            continue\\n\\n        # Deduplicate on stable transaction identity, then on a content\\n        # fingerprint. Re-importing the same file, or the same sale arriving\\n        # from one source twice, must not manufacture independent evidence.\\n        identity = sale.dedupe_key\\n        if identity in seen_identity:\\n            drop(sale, sold_at,\\n                 f\\"duplicate of already-counted transaction {identity[1]} from \\"\\n                 f\\"{identity[0]}; not independent evidence\\")\\n            continue\\n        fingerprint = (\\n            sale.source_id,\\n            sold_at.date().isoformat(),\\n            str(sale.price.amount),\\n            sale.price.currency.value,\\n        )\\n        if fingerprint in seen_fingerprint:\\n            drop(sale, sold_at,\\n                 \\"same source, same day, same price as an already-counted sale; \\"\\n                 \\"treated as a duplicate rather than independent evidence\\")\\n            continue\\n        seen_identity.add(identity)\\n        seen_fingerprint.add(fingerprint)\\n\\n        converted = _to_target(sale, fx, cfg.target_currency)\\n        if converted is None:\\n            excluded.append(\\n                EvidenceRef(\\n                    \\"sale\\", sale.sale_id, sale.source_id, sale.source_url, sold_at,\\n                    Decimal(\\"0\\"),\\n                    f\\"no dated FX rate {sale.price.currency.value}->{cfg.target_currency.value}\\",\\n                )\\n            )\\n            continue\\n\\n        if sale.condition is None:\\n            multiplier = cfg.condition_multipliers[normalize_to]\\n            condition_weight = cfg.unknown_condition_weight\\n        else:\\n            multiplier = cfg.condition_multipliers[sale.condition]\\n            condition_weight = Decimal(\\"1\\")\\n        if multiplier <= 0:  # pragma: no cover - defensive\\n            continue\\n\\n        target_multiplier = cfg.condition_multipliers[normalize_to]\\n        normalized = converted.amount * (target_multiplier / multiplier)\\n\\n        age_days = Decimal(str((as_of - sold_at).total_seconds() / 86400.0))\\n        weight = (\\n            _recency_weight(age_days, cfg.half_life_days)\\n            * cfg.source_reliability.get(sale.source_id, cfg.default_source_reliability)\\n            * condition_weight\\n            * sale.condition_confidence\\n        )\\n\\n        ref = EvidenceRef(\\n            \\"sale\\", sale.sale_id, sale.source_id, sale.source_url, sold_at, weight,\\n            f\\"{converted.amount} {cfg.target_currency.value} at {sale.condition.value if sale.condition else \'condition unknown\'}\\",\\n        )\\n        prepared.append((sale, normalized, weight, ref))\\n\\n    if not prepared:\\n        return FairValue(\\n            window_days=window_days,\\n            value=None,\\n            sufficient=False,\\n            n_sales=0,\\n            n_effective=Decimal(\\"0\\"),\\n            dispersion=None,\\n            method=\\"weighted-median/mad\\",\\n            inputs=(),\\n            excluded=tuple(excluded),\\n            notes=(\\"no completed sales in window\\",),\\n        )\\n\\n    values = [p[1] for p in prepared]\\n    flagged, median_value, mad = mad_outliers(values, cfg.mad_k)\\n\\n    final_inputs: list[EvidenceRef] = []\\n    pairs: list[tuple[Decimal, Decimal]] = []\\n    for idx, (sale, normalized, weight, ref) in enumerate(prepared):\\n        if idx in flagged:\\n            direction = \\"above\\" if normalized > (median_value or 0) else \\"below\\"\\n            excluded.append(\\n                EvidenceRef(\\n                    ref.kind, ref.record_id, ref.source_id, ref.source_url, ref.observed_at,\\n                    Decimal(\\"0\\"),\\n                    f\\"MAD outlier {direction} median at k={cfg.mad_k}; \\"\\n                    \\"flagged for review, not deleted\\",\\n                )\\n            )\\n            continue\\n        pairs.append((normalized, weight))\\n        final_inputs.append(ref)\\n\\n    weight_sum = sum(w for _, w in pairs)\\n    weight_sq_sum = sum(w * w for _, w in pairs)\\n    n_effective = (\\n        (weight_sum * weight_sum) / weight_sq_sum if weight_sq_sum > 0 else Decimal(\\"0\\")\\n    )\\n    n_raw = len(pairs)\\n\\n    if flagged:\\n        notes.append(\\n            f\\"{len(flagged)} sale(s) flagged as outliers and down-weighted to zero; \\"\\n            \\"investigate for wrong variant, damage or counterfeit\\"\\n        )\\n\\n    if n_raw < cfg.min_raw_sales or n_effective < cfg.min_effective_sales:\\n        notes.append(\\n            f\\"insufficient evidence: {n_raw} usable sale(s), Kish effective \\"\\n            f\\"sample size {n_effective:.2f}, need {cfg.min_raw_sales} and \\"\\n            f\\"{cfg.min_effective_sales}\\"\\n        )\\n        return FairValue(\\n            window_days=window_days,\\n            value=None,\\n            sufficient=False,\\n            n_sales=n_raw,\\n            n_effective=Decimal(n_effective),\\n            dispersion=None,\\n            method=\\"weighted-median/mad\\",\\n            inputs=tuple(final_inputs),\\n            excluded=tuple(excluded),\\n            notes=tuple(notes),\\n        )\\n\\n    centre = weighted_median(pairs)\\n    assert centre is not None\\n\\n    ordered = sorted(v for v, _ in pairs)\\n    q1 = ordered[max(0, int(len(ordered) * 0.25) - (0 if len(ordered) % 4 else 1))]\\n    q3 = ordered[min(len(ordered) - 1, int(len(ordered) * 0.75))]\\n    dispersion = (q3 - q1) / centre if centre > 0 else None\\n\\n    return FairValue(\\n        window_days=window_days,\\n        value=Money(centre, cfg.target_currency).quantize(),\\n        sufficient=True,\\n        n_sales=n_raw,\\n        n_effective=Decimal(n_effective),\\n        dispersion=dispersion,\\n        method=f\\"weighted-median/mad(k={cfg.mad_k}),half_life={cfg.half_life_days}d,normalized_to={normalize_to.value}\\",\\n        inputs=tuple(final_inputs),\\n        excluded=tuple(excluded),\\n        notes=tuple(notes),\\n    )\\n\\n\\ndef compute_fair_value_curve(\\n    sales: Sequence[Sale],\\n    *,\\n    variant_id: str,\\n    as_of: datetime,\\n    fx_rates: Optional[Mapping[tuple[Currency, Currency], FxRate]] = None,\\n    config: Optional[FairValueConfig] = None,\\n    windows: Sequence[int] = (7, 30, 90, 365),\\n    grade_bucket: str = \\"raw\\",\\n    market: Optional[str] = None,\\n    language: Optional[Language] = None,\\n) -> dict[str, FairValue]:\\n    \\"\\"\\"All windows plus a blended current estimate.\\n\\n    The blend prefers the shortest window that meets the evidence rule, which\\n    keeps the number responsive without letting a thin 7-day window speak for\\n    a market that only trades monthly.\\n    \\"\\"\\"\\n    out: dict[str, FairValue] = {}\\n    for w in windows:\\n        out[f\\"{w}d\\"] = compute_fair_value(\\n            sales, variant_id=variant_id, as_of=as_of, window_days=w,\\n            fx_rates=fx_rates, config=config,\\n            grade_bucket=grade_bucket, market=market, language=language,\\n        )\\n\\n    current = next(\\n        (out[f\\"{w}d\\"] for w in sorted(windows) if out[f\\"{w}d\\"].sufficient),\\n        None,\\n    )\\n    if current is None:\\n        out[\\"current\\"] = FairValue(\\n            window_days=None, value=None, sufficient=False, n_sales=0,\\n            n_effective=Decimal(\\"0\\"), dispersion=None,\\n            method=\\"blend/shortest-sufficient\\",\\n            notes=(\\"no window met the minimum evidence rule\\",),\\n        )\\n    else:\\n        out[\\"current\\"] = FairValue(\\n            window_days=current.window_days,\\n            value=current.value,\\n            sufficient=True,\\n            n_sales=current.n_sales,\\n            n_effective=current.n_effective,\\n            dispersion=current.dispersion,\\n            method=f\\"blend/shortest-sufficient -> {current.window_days}d\\",\\n            inputs=current.inputs,\\n            excluded=current.excluded,\\n            notes=current.notes,\\n        )\\n    return out\\n\\n\\n# ------------------------------------------------- per-condition valuation --\\n\\n@dataclass(frozen=True, slots=True)\\nclass ConditionValue:\\n    \\"\\"\\"Resale value at one point on the condition ladder, and where it came from.\\"\\"\\"\\n\\n    condition: EuCondition\\n    value: Optional[Money]\\n    basis: ValueBasis\\n    n_sales: int\\n    note: str\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ConditionValueCurve:\\n    \\"\\"\\"Value across the whole ladder, with coverage stated rather than implied.\\"\\"\\"\\n\\n    values: Mapping[EuCondition, ConditionValue]\\n    anchor: FairValue\\n    #: Conditions priced from their own completed sales.\\n    observed: tuple[EuCondition, ...]\\n    #: Conditions derived from the anchor by multiplier. These are a documented\\n    #: prior, not a measurement, and the distinction is carried to the response.\\n    modelled: tuple[EuCondition, ...]\\n    notes: tuple[str, ...] = ()\\n\\n    def money_map(self) -> dict[EuCondition, Optional[Money]]:\\n        return {c: v.value for c, v in self.values.items()}\\n\\n\\ndef condition_value_curve(\\n    sales: Sequence[Sale],\\n    *,\\n    variant_id: str,\\n    as_of: datetime,\\n    anchor: FairValue,\\n    fx_rates: Optional[Mapping[tuple[Currency, Currency], FxRate]] = None,\\n    config: Optional[FairValueConfig] = None,\\n    window_days: Optional[int] = 365,\\n    grade_bucket: str = \\"raw\\",\\n    market: Optional[str] = None,\\n    language: Optional[Language] = None,\\n) -> ConditionValueCurve:\\n    \\"\\"\\"Value at every condition, measured where possible and modelled otherwise.\\n\\n    The condition distribution from the shop\'s grade label is worthless unless\\n    there is a value to attach to each condition. Where a condition has its own\\n    completed sales, it is priced from them. Where it does not, it is derived\\n    from the anchor by the documented multiplier and labelled ``MODELLED``, so\\n    a reader can see which numbers are measurements and which are assumptions.\\n    \\"\\"\\"\\n    cfg = config or FairValueConfig()\\n    values: dict[EuCondition, ConditionValue] = {}\\n    observed: list[EuCondition] = []\\n    modelled: list[EuCondition] = []\\n    notes: list[str] = []\\n\\n    anchor_value = anchor.value if anchor.sufficient else None\\n\\n    for cond in EU_CONDITION_LADDER:\\n        own = [s for s in sales if s.condition is cond]\\n        fv = None\\n        if own:\\n            fv = compute_fair_value(\\n                own, variant_id=variant_id, as_of=as_of, window_days=window_days,\\n                fx_rates=fx_rates, config=cfg, normalize_to=cond,\\n                grade_bucket=grade_bucket, market=market, language=language,\\n            )\\n        if fv is not None and fv.sufficient and fv.value is not None:\\n            values[cond] = ConditionValue(\\n                cond, fv.value, ValueBasis.OBSERVED, fv.n_sales,\\n                f\\"priced from {fv.n_sales} completed sale(s) at {cond.value}\\",\\n            )\\n            observed.append(cond)\\n            continue\\n\\n        if anchor_value is None:\\n            values[cond] = ConditionValue(\\n                cond, None, ValueBasis.MODELLED, 0,\\n                \\"no anchor value and no sales at this condition\\",\\n            )\\n            continue\\n\\n        multiplier = cfg.condition_multipliers[cond]\\n        base_multiplier = cfg.condition_multipliers[EuCondition.NM]\\n        derived = anchor_value.amount * (multiplier / base_multiplier)\\n        values[cond] = ConditionValue(\\n            cond, Money(derived, anchor_value.currency).quantize(),\\n            ValueBasis.MODELLED, len(own),\\n            f\\"derived from the NM anchor by the documented {multiplier} multiplier; \\"\\n            \\"a prior, not a measurement\\",\\n        )\\n        modelled.append(cond)\\n\\n    if modelled:\\n        notes.append(\\n            f\\"{len(modelled)} of {len(EU_CONDITION_LADDER)} ladder points are \\"\\n            \\"modelled from the NM anchor rather than measured: \\"\\n            + \\", \\".join(c.value for c in modelled)\\n        )\\n    if observed:\\n        notes.append(\\n            \\"measured from their own sales: \\" + \\", \\".join(c.value for c in observed)\\n        )\\n\\n    return ConditionValueCurve(\\n        values=values,\\n        anchor=anchor,\\n        observed=tuple(observed),\\n        modelled=tuple(modelled),\\n        notes=tuple(notes),\\n    )\\n", "pokearb_core/webcheck.py": "\\"\\"\\"One price check from payloads that were already fetched. No I/O.\\n\\nThis is the function the website runs. It executes unchanged in CPython,\\nwhere the test suite exercises it, and in the browser under Pyodide, so the\\npage runs the very engine the tests cover rather than a second copy of the\\ncost model written in another language. That second copy is exactly how the\\nmaximum-buy solver once came to disagree with the forward calculation.\\n\\nThe caller does the fetching (the page with ``fetch``, a test with recorded\\nfiles) and hands over plain dicts:\\n\\n* ``card``: the TCGdex card response\\n* ``set_listing``: the TCGdex set response, for finding same-name siblings\\n* ``siblings``: the TCGdex responses for those siblings, or ``None`` when they\\n  could not be fetched, which makes the collision check refuse\\n* ``fx``: ECB euro reference rates, ``{\\"as_of\\", \\"JPY\\", \\"DKK\\", \\"source\\"}``\\n* ``params``: the shelf price and cost assumptions\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import date, datetime, timezone\\nfrom decimal import Decimal, InvalidOperation\\nfrom typing import Any, Mapping, Optional, Sequence\\n\\nfrom .adapters.live import EcbFxAdapter, parse_tcgdex_cardmarket, same_name_sibling_ids\\nfrom .arbitrage.engine import CostAssumptionError, CostAssumptions, compute_arbitrage\\nfrom .arbitrage.policy import PolicyUnverifiedError\\nfrom .arbitrage.reference_policy import reference_policy\\nfrom .types import AcquisitionPurpose, Currency, Money, Printing, Scenario\\nfrom .valuation.benchmark import BenchmarkConfig, assess_market_average\\n\\n__all__ = [\\"run_check\\", \\"default_printing\\", \\"sibling_ids\\", \\"SOURCES\\"]\\n\\nSOURCES = {\\n    \\"tcgdex\\": \\"https://tcgdex.dev/markets-prices\\",\\n    \\"tcgdex_faq\\": \\"https://tcgdex.dev/faq\\",\\n    \\"ecb\\": \\"https://data-api.ecb.europa.eu\\",\\n}\\n\\n#: The ECB publishes on working days; older than this and the page says so.\\nFX_STALE_DAYS = 7\\n\\n\\ndef _d(value: Any, name: str) -> Decimal:\\n    try:\\n        return Decimal(str(value).strip())\\n    except (InvalidOperation, AttributeError) as exc:\\n        raise ValueError(f\\"{name} is not a number\\") from exc\\n\\n\\ndef _s(value: Optional[Decimal], places: str = \\"0.01\\") -> Optional[str]:\\n    return None if value is None else str(value.quantize(Decimal(places)))\\n\\n\\ndef default_printing(variants: Mapping[str, Any]) -> Optional[Printing]:\\n    \\"\\"\\"The printing implied when a card exists in exactly one base form.\\"\\"\\"\\n    has_normal, has_holo = bool(variants.get(\\"normal\\")), bool(variants.get(\\"holo\\"))\\n    if has_holo and not has_normal:\\n        return Printing.HOLO\\n    if has_normal and not has_holo:\\n        return Printing.NON_HOLO\\n    return None\\n\\n\\ndef sibling_ids(set_listing: Mapping[str, Any], card_id: str) -> list[str]:\\n    return same_name_sibling_ids(set_listing, card_id)[:6]\\n\\n\\ndef run_check(\\n    *,\\n    card: Mapping[str, Any],\\n    set_listing: Optional[Mapping[str, Any]],\\n    siblings: Optional[Sequence[Mapping[str, Any]]],\\n    fx: Mapping[str, Any],\\n    params: Mapping[str, Any],\\n    now: Optional[datetime] = None,\\n    benchmark_config: Optional[BenchmarkConfig] = None,\\n) -> dict:\\n    \\"\\"\\"Return a JSON-ready verdict. Refusals are results, not exceptions.\\"\\"\\"\\n    now = now or datetime.now(timezone.utc)\\n    notes: list[str] = []\\n\\n    card_id = str(card.get(\\"id\\") or \\"\\")\\n    info = {\\n        \\"id\\": card_id,\\n        \\"name\\": card.get(\\"name\\"),\\n        \\"rarity\\": card.get(\\"rarity\\"),\\n        \\"set\\": (card.get(\\"set\\") or {}).get(\\"name\\"),\\n        \\"image\\": (card.get(\\"image\\") + \\"/low.webp\\") if card.get(\\"image\\") else None,\\n    }\\n\\n    def refused(headline: str, reasons: Sequence[str], **extra) -> dict:\\n        return {\\n            \\"status\\": \\"refused\\", \\"headline\\": headline, \\"card\\": info,\\n            \\"reasons\\": list(reasons), \\"notes\\": notes, \\"sources\\": SOURCES, **extra,\\n        }\\n\\n    # --- inputs ---------------------------------------------------------\\n    try:\\n        price = _d(params.get(\\"price_jpy\\"), \\"price\\")\\n        if price <= 0:\\n            raise ValueError(\\"price must be above zero\\")\\n        roi = _d(params.get(\\"roi\\", \\"0.40\\"), \\"required return\\")\\n    except ValueError as exc:\\n        return refused(\\"Check the inputs\\", [str(exc)])\\n\\n    choice = str(params.get(\\"printing\\") or \\"auto\\")\\n    if choice == \\"auto\\":\\n        printing = default_printing(card.get(\\"variants\\") or {})\\n        if printing is None:\\n            return refused(\\n                \\"Pick the printing\\",\\n                [\\"this card exists in more than one base printing; choose holo, \\"\\n                 \\"non-holo or reverse holo\\"],\\n                needs_printing=True,\\n            )\\n    else:\\n        try:\\n            printing = Printing(choice)\\n        except ValueError:\\n            return refused(\\"Check the inputs\\", [f\\"unknown printing {choice!r}\\"])\\n\\n    # --- the published average and its checks ---------------------------\\n    obs, parse_reasons = parse_tcgdex_cardmarket(\\n        card, printing=printing, variant_id=card_id, known_at=now,\\n        source_url=f\\"https://api.tcgdex.net/v2/ja/cards/{card_id}\\",\\n    )\\n    sibling_products: Optional[list[str]]\\n    if siblings is None:\\n        sibling_products = None\\n    else:\\n        sibling_products = []\\n        for sib in siblings:\\n            prod = ((sib.get(\\"pricing\\") or {}).get(\\"cardmarket\\") or {}).get(\\"idProduct\\")\\n            if prod not in (None, \\"\\", 0):\\n                sibling_products.append(str(prod))\\n    bench = assess_market_average(\\n        obs, as_of=now, sibling_product_ids=sibling_products,\\n        parser_reasons=parse_reasons, config=benchmark_config,\\n    )\\n    figures = None\\n    if obs is not None:\\n        figures = {\\n            \\"avg\\": _s(obs.avg), \\"avg7\\": _s(obs.avg7), \\"avg30\\": _s(obs.avg30),\\n            \\"trend\\": _s(obs.trend), \\"low\\": _s(obs.low),\\n            \\"product_id\\": obs.product_id,\\n            \\"updated\\": obs.provider_updated_at.date().isoformat(),\\n        }\\n    if bench.refused:\\n        return refused(\\"No reliable European price\\", bench.reasons, figures=figures)\\n\\n    # --- exchange rates ---------------------------------------------------\\n    try:\\n        fx_date = date.fromisoformat(str(fx[\\"as_of\\"]))\\n        rates = EcbFxAdapter.derive(\\n            fx_date,\\n            {Currency.JPY: _d(fx[\\"JPY\\"], \\"JPY rate\\"), Currency.DKK: _d(fx[\\"DKK\\"], \\"DKK rate\\")},\\n            str(fx.get(\\"source\\") or SOURCES[\\"ecb\\"]),\\n        )\\n    except (KeyError, ValueError) as exc:\\n        return refused(\\"Exchange rates unavailable\\", [f\\"ECB rates could not be read: {exc}\\"],\\n                       figures=figures)\\n    fx_map = {(r.base, r.quote): r for r in rates}\\n    age = (now.date() - fx_date).days\\n    if age > FX_STALE_DAYS:\\n        notes.append(f\\"the ECB rate is {age} days old\\")\\n\\n    # --- economics, through the one shared cost model ---------------------\\n    try:\\n        assumptions = CostAssumptions(\\n            scenario=Scenario(str(params.get(\\"scenario\\") or Scenario.HAND_CARRY.value)),\\n            acquisition_purpose=AcquisitionPurpose(\\n                str(params.get(\\"purpose\\") or AcquisitionPurpose.RESALE.value)),\\n            proxy_fee_rate=_d(params.get(\\"proxy_rate\\") or \\"0\\", \\"proxy fee\\"),\\n            international_shipping_jpy=_d(params.get(\\"shipping_jpy\\") or \\"0\\", \\"shipping\\"),\\n            outbound_shipping_eur=_d(params.get(\\"outbound_eur\\") or \\"0\\", \\"outbound shipping\\"),\\n            duty_rate=(_d(params[\\"duty_rate\\"], \\"duty rate\\")\\n                       if params.get(\\"duty_rate\\") not in (None, \\"\\") else None),\\n        ).validated()\\n        arb = compute_arbitrage(\\n            purchase_jpy=Money(price, Currency.JPY),\\n            gross_resale_eur=bench.value,\\n            on=now.date(),\\n            assumptions=assumptions,\\n            policy=reference_policy(),\\n            fx_rates=fx_map,\\n            required_roi=roi,\\n        )\\n    except (CostAssumptionError, PolicyUnverifiedError, ValueError) as exc:\\n        return refused(\\"Landed cost cannot be verified\\", [str(exc)], figures=figures,\\n                       value_eur=_s(bench.value.amount))\\n\\n    cap = arb.max_buy_jpy\\n    inside = cap is not None and price <= cap.amount\\n    if cap is None:\\n        headline = f\\"No shelf price clears a {roi:.0%} return on this card\\"\\n    elif inside:\\n        headline = (f\\"{price:,.0f} yen is {cap.amount - price:,.0f} yen under the \\"\\n                    f\\"{cap.amount:,.0f} yen ceiling\\")\\n    else:\\n        headline = (f\\"{price:,.0f} yen is {price - cap.amount:,.0f} yen over the \\"\\n                    f\\"{cap.amount:,.0f} yen ceiling\\")\\n\\n    jpy_eur = fx_map[(Currency.EUR, Currency.JPY)]\\n    return {\\n        \\"status\\": \\"indicative\\",\\n        \\"inside\\": inside,\\n        \\"headline\\": headline,\\n        \\"card\\": info,\\n        \\"figures\\": figures,\\n        \\"value_eur\\": _s(bench.value.amount),\\n        \\"statistic\\": bench.statistic,\\n        \\"spread\\": _s(bench.spread, \\"0.0001\\"),\\n        \\"price_jpy\\": str(price),\\n        \\"required_roi\\": str(roi),\\n        \\"landed_eur\\": _s(arb.landed.total_eur.amount),\\n        \\"upfront_eur\\": _s(arb.landed.upfront_cash_eur.amount),\\n        \\"refund_eur\\": _s(arb.landed.expected_refund_eur.amount),\\n        \\"net_proceeds_eur\\": _s(arb.net_proceeds_eur.amount),\\n        \\"profit_eur\\": _s(arb.expected_profit_eur.amount),\\n        \\"roi\\": _s(arb.roi, \\"0.0001\\"),\\n        \\"capital_basis\\": arb.capital_basis,\\n        \\"max_buy_jpy\\": str(cap.amount) if cap else None,\\n        \\"target_buy_jpy\\": str(arb.target_buy_jpy.amount) if arb.target_buy_jpy else None,\\n        \\"strong_buy_jpy\\": str(arb.strong_buy_jpy.amount) if arb.strong_buy_jpy else None,\\n        \\"fx\\": {\\"jpy_per_eur\\": str(jpy_eur.rate), \\"as_of\\": fx_date.isoformat(),\\n               \\"source\\": str(fx.get(\\"source\\") or SOURCES[\\"ecb\\"])},\\n        \\"notes\\": notes + list(arb.notes),\\n        \\"reasons\\": list(bench.reasons),\\n        \\"unresolved\\": list(arb.unresolved),\\n        \\"sources\\": SOURCES,\\n    }\\n"}')
RUNNER = '#!/usr/bin/env python3\n"""Daily market scan: fetch, analyse, keep history, write the page.\n\n    python scripts/scan.py --out site --data data\n    python scripts/scan.py --series SV --sets SV2a,SV8a     # a smaller universe\n    python scripts/scan.py --fixtures tests/fixtures/scan   # offline, for tests\n\nDesigned to run unattended once a day (see deploy/scan.yml). Every request\ngoes to the public TCGdex API, a few at a time with a pause between them,\nbecause the provider asks users to be considerate and to cache\n(https://tcgdex.dev/faq).\n\nOutputs:\n  site/index.html     the page, ranked signals with their reasons\n  site/latest.json    the same signals as data\n  data/history.json   our own dated record per card, 120 days rolling\n  data/seen.json      buy signals already alerted, so alerts are not repeated\n  alerts/new.md       written only when there are new buy signals; the\n                      workflow turns it into a GitHub issue, which reaches the\n                      phone as a notification\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport html\nimport json\nimport sys\nimport time\nimport urllib.request\nfrom concurrent.futures import ThreadPoolExecutor\nfrom datetime import datetime, timezone\nfrom decimal import Decimal\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve()\nif (HERE.parents[1] / "packages" / "core").exists():\n    sys.path.insert(0, str(HERE.parents[1] / "packages" / "core"))\n\nfrom pokearb_core.scanner import (  # noqa: E402\n    ScanConfig,\n    ScanResult,\n    scan_set,\n    secret_rare_ids,\n    update_history,\n)\n\nAPI = "https://api.tcgdex.net/v2"\nUA = "pokearb-scan/1.0 (+personal price research)"\n\n\nclass Fetcher:\n    def __init__(self, lang: str, delay: float, fixtures: Path | None = None):\n        self.lang, self.delay, self.fixtures = lang, delay, fixtures\n        self.requests = 0\n        self.failures = 0\n\n    def get(self, path: str):\n        if self.fixtures is not None:\n            f = self.fixtures / (path.replace("/", "_") + ".json")\n            return json.loads(f.read_text(encoding="utf-8")) if f.exists() else None\n        url = f"{API}/{self.lang}/{path}"\n        for attempt in range(3):\n            try:\n                self.requests += 1\n                req = urllib.request.Request(url, headers={"User-Agent": UA})\n                with urllib.request.urlopen(req, timeout=25) as resp:  # noqa: S310\n                    data = json.loads(resp.read())\n                time.sleep(self.delay)\n                return data\n            except Exception:  # noqa: BLE001\n                time.sleep(2 * (attempt + 1))\n        self.failures += 1\n        return None\n\n\ndef universe(fetch: Fetcher, series: list[str], only_sets: list[str]) -> list[str]:\n    if only_sets:\n        return only_sets\n    ids: list[str] = []\n    for s in series:\n        data = fetch.get(f"series/{s}") or {}\n        ids.extend(x["id"] for x in data.get("sets") or [])\n    return ids\n\n\ndef run(args) -> int:\n    now = datetime.now(timezone.utc)\n    fetch = Fetcher(args.lang, args.delay, Path(args.fixtures) if args.fixtures else None)\n    out, data_dir = Path(args.out), Path(args.data)\n    out.mkdir(parents=True, exist_ok=True)\n    data_dir.mkdir(parents=True, exist_ok=True)\n\n    hist_file = data_dir / "history.json"\n    history = json.loads(hist_file.read_text()) if hist_file.exists() else {}\n    cfg = ScanConfig(min_value_eur=Decimal(args.min_value))\n    total = ScanResult()\n    set_ids = universe(fetch, [s for s in args.series.split(",") if s],\n                       [s for s in args.sets.split(",") if s])\n\n    for set_id in set_ids:\n        set_payload = fetch.get(f"sets/{set_id}")\n        if not set_payload or "cards" not in set_payload:\n            total.skip("set could not be fetched")\n            continue\n        chosen = secret_rare_ids(set_payload) if not args.all_cards else [\n            c["id"] for c in set_payload["cards"]]\n        # Same-name siblings are fetched too, only so the listing-collision\n        # check can run on the cards that matter.\n        names = {c["id"]: c.get("name") for c in set_payload["cards"]}\n        wanted = set(chosen)\n        for cid in chosen:\n            wanted.update(c["id"] for c in set_payload["cards"]\n                          if c.get("name") == names.get(cid))\n        with ThreadPoolExecutor(max_workers=args.workers) as pool:\n            fetched = dict(zip(sorted(wanted), pool.map(\n                lambda cid: fetch.get(f"cards/{cid}"), sorted(wanted))))\n        cards = {k: v for k, v in fetched.items() if v}\n        subject = {k: v for k, v in cards.items() if k in set(chosen)}\n        # Siblings were fetched for the collision check, not as subjects.\n        result = scan_set(set_payload, cards, now=now, config=cfg, history=history,\n                          subjects=set(subject))\n        total.merge(result)\n        update_history(history, subject, now.date())\n\n    hist_file.write_text(json.dumps(history, separators=(",", ":")))\n\n    by_kind = {k: sorted([s for s in total.signals if s.kind == k],\n                         key=lambda s: s.score, reverse=True) for k in ("buy", "rising", "falling")}\n    latest = {\n        "generated": now.isoformat(), "sets": set_ids, "scanned": total.scanned,\n        "requests": fetch.requests, "failed_requests": fetch.failures,\n        "skipped": total.skipped,\n        "signals": {k: [s.as_dict() for s in v] for k, v in by_kind.items()},\n    }\n    (out / "latest.json").write_text(json.dumps(latest, ensure_ascii=False, indent=1))\n    (out / "index.html").write_text(render(latest), encoding="utf-8")\n\n    seen_file = data_dir / "seen.json"\n    seen = set(json.loads(seen_file.read_text())) if seen_file.exists() else set()\n    fresh = [s for s in by_kind["buy"] if f"{s.card_id}@{s.numbers[\'buy\']}" not in seen]\n    alerts = Path(args.alerts)\n    if fresh:\n        alerts.mkdir(parents=True, exist_ok=True)\n        lines = [f"{len(fresh)} card(s) newly listed well under their recent price.\\n"]\n        for s in fresh[:15]:\n            lines.append(f"- **{s.name}** ({s.card_id}): {s.headline}. "\n                         f"{s.numbers[\'roi\'] and format(Decimal(s.numbers[\'roi\']), \'.0%\')} return "\n                         "if resold at the recent level after fees and postage.")\n        lines.append("\\nFull list on the PokeArb page. Check each listing\'s condition before buying.")\n        (alerts / "new.md").write_text("\\n".join(lines), encoding="utf-8")\n    seen.update(f"{s.card_id}@{s.numbers[\'buy\']}" for s in by_kind["buy"])\n    seen_file.write_text(json.dumps(sorted(seen)[-2000:]))\n\n    print(f"scanned {total.scanned} cards in {len(set_ids)} sets with {fetch.requests} requests "\n          f"({fetch.failures} failed): {len(by_kind[\'buy\'])} buy, {len(by_kind[\'rising\'])} rising, "\n          f"{len(by_kind[\'falling\'])} falling; {len(fresh)} new buy alert(s)")\n    return 0\n\n\n# ------------------------------------------------------------------ page ----\n\nCSS = """\n:root{--navy:#13294B;--orange:#E07A1F;--mist:#EEF2F6;--slate:#5B6878;--ink:#1B2533;--rule:#D5DCE4;\n--serif:Cambria,Caladea,Georgia,serif;--sans:Calibri,Carlito,"Segoe UI",system-ui,sans-serif}\n*{box-sizing:border-box}body{margin:0;color:var(--ink);font:17px/1.45 var(--sans);background:#fff;\npadding:env(safe-area-inset-top,0px) 0 env(safe-area-inset-bottom,0px)}\nmain{max-width:40rem;margin:0 auto;padding:1.2rem 1.1rem 3rem}\nheader{border-bottom:3px solid var(--navy);padding-bottom:.6rem;margin-bottom:1rem}\nh1{font:700 1.35rem/1.2 var(--serif);color:var(--navy);margin:0}\nheader p{margin:.2rem 0 0;color:var(--slate);font-size:.95rem}\nh2{font:700 1.3rem/1.25 var(--serif);color:var(--navy);margin:1.8rem 0 .2rem}\nh2.warm{color:var(--orange)}\n.lead{color:var(--slate);margin:0 0 .8rem;font-size:.95rem}\n.item{display:grid;grid-template-columns:4rem 1fr;gap:.8rem;padding:.8rem 0;border-top:1px solid var(--rule)}\n.item.noimg{grid-template-columns:1fr}\n.item img{width:4rem;border-radius:4px;background:var(--mist);aspect-ratio:63/88;object-fit:cover}\n.name{font-weight:700}.meta{color:var(--slate);font-size:.88rem}\n.head{margin:.2rem 0;font-weight:700;color:var(--navy)}\n.item.buy .head{color:var(--orange)}\nul{margin:.2rem 0 0;padding-left:1.1rem}li{font-size:.9rem;margin:.1rem 0}\n.empty{color:var(--slate);border-top:1px solid var(--rule);padding:.8rem 0}\nfooter{margin-top:2rem;font-size:.8rem;color:var(--slate)}\nfooter a{color:var(--navy)}\n"""\n\n\ndef _item(s: dict) -> str:\n    img = (f\'<img src="{html.escape(s["image"])}" alt="" loading="lazy">\' if s.get("image") else "")\n    meta = ", ".join(html.escape(x) for x in (s.get("rarity"), s.get("set"), s["card_id"]) if x)\n    details = "".join(f"<li>{html.escape(d[0].upper() + d[1:])}</li>" for d in s["detail"])\n    cls = "item" + ("" if img else " noimg") + (" buy" if s["kind"] == "buy" else "")\n    return (f\'<div class="{cls}">{img}<div><div class="name">{html.escape(s["name"])}</div>\'\n            f\'<div class="meta">{meta}</div><p class="head">{html.escape(s["headline"])}</p>\'\n            f"<ul>{details}</ul></div></div>")\n\n\ndef _section(title: str, lead: str, items: list[dict], empty: str, warm: bool = False,\n             limit: int = 30) -> str:\n    body = "".join(_item(s) for s in items[:limit]) or f\'<p class="empty">{html.escape(empty)}</p>\'\n    cls = \' class="warm"\' if warm else ""\n    return f"<section><h2{cls}>{html.escape(title)}</h2><p class=\\"lead\\">{html.escape(lead)}</p>{body}</section>"\n\n\ndef waiting_note(latest: dict) -> str:\n    waiting = latest["skipped"].get("buy check waiting for price history", 0)\n    if waiting:\n        return (f"{waiting} cards are still building price history. Buy signals need three "\n                "earlier daily scans to know what a new low looks like.")\n    return "Nothing cleared the bar. That is a normal day."\n\n\ndef render(latest: dict) -> str:\n    sig = latest["signals"]\n    n_buy, n_up, n_down = len(sig["buy"]), len(sig["rising"]), len(sig["falling"])\n    when = datetime.fromisoformat(latest["generated"]).strftime("%d %b %Y, %H:%M UTC")\n    buy_title = (f"{n_buy} card{\'s\' if n_buy != 1 else \'\'} listed well under the recent price"\n                 if n_buy else "No card is listed far enough under its recent price today")\n    skipped = ", ".join(f"{v} {k}" for k, v in sorted(latest["skipped"].items(), key=lambda kv: -kv[1]))\n    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n<title>PokeArb market scan</title><link rel="icon" href="data:,">\n<link href="https://fonts.googleapis.com/css2?family=Caladea:wght@400;700&family=Carlito:wght@400;700&display=swap" rel="stylesheet">\n<style>{CSS}</style></head><body><main>\n<header><h1>PokeArb market scan</h1><p>Cardmarket, in euro. Updated {html.escape(when)}.</p></header>\n{_section(buy_title, "A new lowest offer, at least 20% under the card\'s usual lowest offer in earlier scans, and reselling at the recent level clears a 30% return after 5% selling fees and postage. Check condition before buying.", sig["buy"], waiting_note(latest), warm=True)}\n{_section(f"{n_up} rising", "The 7-day average is at least 15% above the 30-day average and the trend agrees. Momentum, not a buy signal.", sig["rising"], "Nothing is rising by that much.")}\n{_section(f"{n_down} falling", "The 7-day average is at least 15% below the 30-day average and the trend agrees.", sig["falling"], "Nothing is falling by that much.")}\n<footer><p>Scanned {latest["scanned"]} cards across {len(latest["sets"])} Japanese sets with {latest["requests"]} requests.\nSet aside: {html.escape(skipped) or "none"}.</p>\n<p>Prices are Cardmarket averages relayed by TCGdex, never individual sales, so no signal here knows how many sales are behind a price.\nUS prices are ignored. No permitted UK price source is connected. Taxes are not included.\n<a href="check.html">Check a single card</a>.</p></footer>\n</main></body></html>"""\n\n\ndef main(argv=None) -> int:\n    ap = argparse.ArgumentParser(description="Daily PokeArb market scan")\n    ap.add_argument("--out", default="site")\n    ap.add_argument("--data", default="data")\n    ap.add_argument("--alerts", default="alerts")\n    ap.add_argument("--lang", default="ja")\n    ap.add_argument("--series", default="SV,M", help="TCGdex series ids to scan")\n    ap.add_argument("--sets", default="", help="scan only these set ids instead")\n    ap.add_argument("--all-cards", action="store_true", help="not only the secret rares")\n    ap.add_argument("--min-value", default="10", help="ignore cards below this many euro")\n    ap.add_argument("--workers", type=int, default=3)\n    ap.add_argument("--delay", type=float, default=0.25, help="pause after each request, seconds")\n    ap.add_argument("--fixtures", default="", help="read recorded responses instead of the API")\n    return run(ap.parse_args(argv))\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'

_tmp = Path(tempfile.mkdtemp(prefix="pokearb_"))
for _path, _src in CORE.items():
    _f = _tmp / _path
    _f.parent.mkdir(parents=True, exist_ok=True)
    _f.write_text(_src, encoding="utf-8")
sys.path.insert(0, str(_tmp))
_ns = {"__name__": "pokearb_scan_runner", "__file__": str(_tmp / "scan.py")}
exec(compile(RUNNER, "scan.py", "exec"), _ns)

if __name__ == "__main__":
    raise SystemExit(_ns["main"]())
